window.__D("text/keter-shem-tov/c004",{"p":[[300010641,"קיט\n\nחולין צא, ב: <i>גפן אלו ישראל</i>.\n<b>אידן</b> זיינען פאַרגליכען צו אַ וויינשטאָק צוליעב צוויי טעמים: ערשטענס, דערפאַר וואָס אין אַ וויינשטאָק זיינען אויך די בלעטער וויכטיג פאַר די פירות, און צווייטענס, דערפאַר וואָס די בלעטער פון אַ וויינשטאָק האָבען די וויכטיגע אויפגאַבע צו באַשיצען די וויינטרויבען און זיינען דערפאַר פון דער גרעסטער באַדייטונג, ווייל דער כח פון באַשיצער איז גרעסער ווי פון דער באַשיצען<sup data-n=\"1\">265</sup>.",[["1","265","ספר הזכרונות חלק א פרק ט (ע' 53). ושם לפנ\"ז: זיין [דעם בעש\"ט'ס] טעהעטיגקייט אין די ערשטע יאָרן געווען דורכאויס געווידמעט צום פּשוט'ען פאָלק בעת די טעהטיגקייט זיינע, אין די שפּעטערדיגע יאָרן, איז אויך געווען געווידמעט צו די לומדים און הויכע גייסטער.\nדער אַלטער רבי האָט דערביי איבערגעזאָגט אין בעל שם'ס נאָמען, אַז [ההמשך בפנים]."]]],[300010642,"קכ\n\nערכין טו, ב: <i>לשון תליתאי קטיל תליתאי</i>.\n<b>דער</b> בעש\"ט פלעגט אָפּטייטשן די ווערטער אין אידיש, אַז מ'האָט געלערנט ערכין און געקומען צום מארז\"ל (טו, ב) לשון תליתאי קטיל תליתאי, האָט דער בעש\"ט דאָס אויסגעטייטשט: לשון הרע הרג'ט אַלע דריי: דעם אויסטראַכטער<sup data-n=\"1\">266</sup> דעם דערציילער און דעם צוהערער, נאָר דאָס איז אין לבושים רוחנים, וואָס דאָס איז שווערער, ווי רציחה אין גשמיות<sup data-n=\"2\">267</sup>.",[["1","266","אפשר שזהו ע\"פ פירוש רבינו גרשום בגמ' [ערכין] שם. – לקוטי שיחות ח\"ה ע' 44 הערה 47. חט\"ו ע' 32 הערה 28."],["2","267","\"היום יום\" יג חשון – מאגרות-קודש אדמו\"ר מהוריי\"צ ח\"ו ע' קיב. ושם: דער בעש\"ט פלעגט לערנען מיט זיינע תלמידים אַ שיעור גמרא. דער אופן פון דעם לערנען איז געווען מיט גרויס חריפות און גאונות, און מ'האָט געלערנט דעם רמב\"ם אלפס רא\"ש און אַנדערע מפרשים פון די ראשונים וועלכע זיינען שייך געווען צו דער גמרא וואָס מ'האָט געלערנט."]]],[300010643,"קכא\n\nנדה ל, ב: <i>ומלמדים אותו כל התורה כולה</i>.\n<b>התינוק</b> קודם שנולד מלמדין אותו כל התורה כולה, ושמעתי ממורי ורבי הבעש\"ט נ\"ע אשר ביום החמישי בלילה לומדים עם התינוק פרשת השבוע עם פרש\"י ומי שחננו השי\"ת בזכרון טוב הנה כשנעשה גדול ולומד ביום החמישי בלילה פרשת השבוע עם פרש\"י הוא נזכר אותו הטעם שהי' לו להתינוק כשלמדו עמו פרשת השבוע עוד קודם שנולד<sup data-n=\"1\">268</sup>.",[["1","268","מרשימת היומן של כ\"ק אדמו\"ר מהוריי\"צ – ח' כסלו תרס\"ז וירצבורג – \"התמים\" חוברת ב' ע' עו [פה, ב], ומועתק בזה הסיפור הקשור בזה:\nפעם נזדמן לי להיות בעת קידוש בשבת קדש אצל אחד האדמורי\"ם שנתארח בפרעמישלא. אמרו עליו שהי' כבר בן מאה, כולו הפך לבן, ובבגדיו לבנים והדרת פניו אין לתאר, הבית הי' מלא מפה לפה וכולם מחכים לעת צאתו לסדר את השולחן.\nבין הבאים היו כמה גדולי הדור אשר כל אחד מהם הי' לו כמה אלפים מקושרים.\nוקול נשמע כי האדמו\"ר הולך, והכל הפנו מבטם אל הדלת אשר משם יופיע. אנכי עמדתי על אחד החלונות ובראותי את טוהר פני קדש האדמו\"ר ותלבושתו, ואת שני הזקנים בעלי צורה ההולכים משני עבריו נפלה עלי יראה ופחד.\nכשתי שעות ישבו אצל השולחן, ובמשך הזמן דיבר האדמו\"ר איזה פעמים אבל אנכי לא יכלתי לשמוע, ומה שחזרו אח\"כ השומעים לא הבנתי, רק סיפור אחד, שסיפר האדמו\"ר בעת אמירת שלום עליכם בין בואכם לשלום וברכוני לשלום, שמעתי אח\"כ מהשומעים שחזרו עליו.\nכשהייתי תינוק קטן – התחיל האדמו\"ר לספר – שלח זקני האדמו\"ר את מקורבו שיביאני אליו אל השטיבל המיוחד שלו, זה הי' ביום החמישי בערב ואני כבר למדתי חומש עם פרש\"י והייתי בקי בספר בראשית.\nכשבאתי לזקני מצאתיו יושב ולומד חומש עם פרש\"י וישאלני אם כבר למדתי כל פרשת השבוע אמרתי לא, רבי עדיין לא הספיק לגמור עמו כל הפרשה.\nאתה יודע – אמר לי זקני – אשר . . . [ההמשך בפנים. ולאח\"ז ממשיך:]\nכשגמר זקני את מאמרו בשם מורו הבעש\"ט נ\"י הניח ידיו על ראשי ויברכני, ומני אז הנה בכל יום החמישי בלילה הנני לומד פרשת השבוע עם פרש\"י, ובכל עת שהנני נזכר על החילוק הגדול בין אותו הלימוד שלמדו אתי קודם שנולדתי ללימוד דעכשיו הנני בצער גדול, כשהייתי חזק בבריאותי לא הרגשתי החלישות שפעל עלי אבל עכשיו שזקנתי הנה הצער פועל עלי חלישות גדולה, ואשר ע\"כ מלאכים יקרים, מלאכי ש\"ק, מלאכים נעימים ברכוני לשלום מלאכי השלום.\nעולם מלא הי' בעיניו המאירות של הישיש רז\"ג בעת שסיפר על אודות הקידוש ועריכת השלחן של האדמו\"ר הישיש הנ\"ל אשר את שמו לא זכר ותורתו לא ידע, אבל המחזה כולו בכל הדרו נצב לנגד עיניו."]]],[300010644,"קכב\n\nזוהר חלק ג קסח, א: <i>פתח רב מתיבתא, מאן דאיהו זעיר איהו רב, ומאן דאיהו רב איהו זעיר</i>.\n<b>רב</b> מתיבתא מדייק בלשונו ומתחיל בסדר המסודר בעולם התיקון. אף דתהו קדם לתיקון, דבתהו יש ג\"כ הענין דזעיר ורב, אבל בתהו ההתחלה היא מהרב אל הזעיר, וכמו שאנו רואים במוחש דמי שטועה בדרכי עבודה, ובקטנותו הוא גדול, הנה גם בגדלותו נשאר קטן, ומאן דאיהו זעיר איהו רב, דבתיקון הסדר הוא מקטנות לגדלות, אז בתחלת העבודה באַדאַרף מען פילן אַז מען איז אַ קטן, אַז דאָס וואָס מען פאַרשטייט איז אַ קטנות, דער עיקר איז הרגש – פיהלען<sup data-n=\"1\">269</sup>.",[["1","269","לקוטי דיבורים ח\"ג תקה, א ואילך. ספר השיחות תש\"ט ע' 296. ולאח\"ז שם: און בכדי צו פיהלען מוז מען האָבען גאָר אַן אַנדער הכשרה, און אָט די הכשרה האָט מען ווען מען איז אַ מקבל טוב פון עלטערע חסידים. וראה ספר המאמרים תרנ\"ט ע' רט ואילך."]]],[300010645,"קכג\n\nתקוני זוהר תיקון ה' (יט, ב): <i>מים תתאין אינון בוכין ואמרין אנן בעיין למהוי קדם מלכא</i>.\n<b>אומר</b> הבעל שם טוב . . . איתא בזוהר הקדוש מים תחתונים בוכין אנן בעינן למהוי קדם מלכא קדישא. כל המעינות הנה מן היום אשר הקב\"ה הבדיל בין מים למים, הנה המים התחתונים בוכין אנן בעינן למהוי קדם מלכא קדישא, שיעשו בהם ועל ידם דבר שבקדושה, כמו רחיצת ידים קודם התפלה, טבילת מצוה, טבילת טהרה לתפלה ולתורה, נטילת ידים עם ברכה בהזכרת שם שמים, מים לשתי' ומברכין עליהם לפניהם ולאחריהם. מאז ברא הקב\"ה את המים, והבדיל בין מים למים, הנה מים תחתונים בוכין אנן בעינן למהוי קדם מלכא קדישא להיות תשמישי מצוה ותשמישי קדושה וטהרה, ובכייתם הלזו של המעינות יכולה להמשך מאות ואלפים בשנים עד אשר אחד היהודים עובר עליהם ורוחץ ידיו ומברך על נטילת ידים, או שותה לצמאו ומברך תחלה וסוף<sup data-n=\"1\">270</sup>.",[["1","270","לקוטי דיבורים ח\"ד תקצו, א ואילך. ועיי\"ש בארוכה תקפד, א ואילך – הסיפור הקשור בזה."]]],[300010646,"קכד\n\nתקוני זוהר תיקון סט (קיד, א): <i>אתפשטותי' דמשה בכל דרא ודרא</i>.\n<b>איינער</b> פון די תורה-נקודות-ווערטער וואָס הוד כ\"ק רבינו הזקן האָט מקבל געווען מהוד כ\"ק מורו מורנו הרב המגיד שקיבל ממורו מורנו הבעש\"ט מה שקיבל ממורו הבעל ח\"י<sup data-n=\"1\">271</sup> . . אתפשטותא דמשה בכל דרא, יעדער איינצעלנער איד, איש אָדער אשה, איז אַ דור, וואָס ווען זיי קומען אין זמן פון חיי משפּחה על פּי תורה ווערן זיי געבענטשט פון דעם משה וואָס בדורם, וואָס ער איז כל מהותו ועצמותו טאַקע אַ אור עצמי, אָבער זיין אור עצמי איז דער מאור המאיר מאתפשטותא דמשה בכל אחד ואחת בשלש האהבות: אהבת השם אהבת התורה ואהבת ישראל<sup data-n=\"2\">272</sup>.",[["1","271","ראה לקמן סימן רפא."],["2","272","ספר המאמרים ה'שי\"ת ע' 160, וממשיך שם: דער וואָרט, איז איינער פון די דיוקים-ווערטער, ווי ער רופט זיי בסגנונו המדוייק, וואָס הוד כ\"ק אאמו\"ר הרה\"ק גיט מיר איבער אין געוויסע צייטען, און זאָגט דערביי:\nדאָס וואָס איך גיב דיר איבער זאָל אין דיר פּועל זיין התרחבות העמקת ותוקף הדעת, זיין בכל תוקף עוז, אין אַלע זמנים און אין יעדער מקום ווי איך האָב דיר איבערגעגעבן."]]],[300010647,"קכה\n\nבראשית רבה פ\"ב, ב: <i>אמר הקב\"ה עד מתי יהא העולם מתנהג באפילה תבא האורה . . זה אברהם</i>. שמו\"ר פט\"ו, כו: <i>אברהם התחיל להאיר</i>.\n<b>באחת</b> משיחותיו אומר מורנו הבעש\"ט:\nעד אברהם הי' העולם מתנהג באפילה, שלא היו צדיקי הדור לא מלמדים את בני דורם ארחות הוי' ולא מבקשים עליהם רחמים מכיון שבא אברהם התחיל להאיר<sup data-n=\"1\">273</sup>. ללמוד את בני דורו את דרכי העבודה בעבודת הבורא ית', ומוסר נפשו לעורר רחמי שמים על בני דורו, עד כי גם בעד הרעים והחטאים אנשי סדום ועמורה הוא מתפלל ומבקש רחמים עליהם.\nבכל זה הנה בדורו של אברהם אבינו נקרא ההמון, וגם ישמעאל, עם הדומה לחמור<sup data-n=\"2\">274</sup>. אבל בזרע ישראל נקרא ההמון בתואר עם הארץ, עם הדומה לארץ. ומה הארץ הכל דורסים עלי', ובה הטביע הקב\"ה את כח הצומח להצמיח יבול להחיות את כל החי על פני האדמה. ובה נמצאו אוצרות זהב וכסף וכל יקר במחמדי תבל. כך ישראל אשר כפלח הרמון רקתך<sup data-n=\"3\">275</sup>, דגם הריקנין מיראת אלקים מלאים מצות כרמון<sup data-n=\"4\">276</sup>. ומה גם המקיימים את המצוות בתום לב בפּשטות דאמונה פּשוטה, שהם עמי הארץ, עם הדומה לארץ כאמור כי<sup data-n=\"5\">277</sup> תהיו אתם ארץ חפץ<sup data-n=\"6\">278</sup>.",[["1","273","וראה לקמן סימן שנו."],["2","274","יבמות סב, א."],["3","275","שה\"ש ד, ג. ו, ז."],["4","276","עירובין יט, א. וש\"נ."],["5","277","מלאכי ג, יב."],["6","278","ספר הזכרונות ח\"א ע' 342. וראה לעיל סימן כט. נז."]]],[300010648,"קכו\n\nתנא דבי אליהו.\n<b>הגם</b> עס שטייט אין תדב\"א<sup data-n=\"1\">279</sup>, דאָס אויב מען פאַסט ארבעים ימים רצופים און מ'איז זיך פּורש פון עניני עולם איז אפילו אַ עבד ושפחה זוכה צו גילוי אלי'. איז גילוי אלי' קען מען האָבן, אָבער ניט גילוי הנשמה<sup data-n=\"2\">280</sup>.",[["1","279","ראה תדבא\"ר רפ\"ט: מעיד אני עלי את השמים ואת הארץ בין ישראל בין עובד כוכבים בין איש בין אשה בין עבד ובין שפחה הכל לפי המעשה שהוא עושה כך רוח הקודש שורה עליו."],["2","280","ספר השיחות תש\"ד ע' 98. ומועתק בזה הסיפור ע\"ד פתגם הנ\"ל (שם):\nמורנו הבעש\"ט איז אַמאָל געפאָרן מיט תלמידיו הצדיקים אין אַ ווייטן ישוב. אין יענעם ישוב האָט געוואוינט אַ פּרוש, וועלכער איז געזעסן על התורה ועל העבודה און האָט זיך אינגאַנצן אָפּגעזאָגט פון עניני עולם און אויף יעדער זאַך פלעגט ער זאָגן: כך קבלתי מאליהו. ער פלעגט קענען מסביר זיין אַ ענין צו יעדערן, אַפילו צו אַ איש פּשוט.\nדאָרט אין ישוב האָט אויך געוואוינט אַ איש פּשוט, אַ שינדער, אַ פּושט נבילות, וועלכער פלעגט זאָגן זייער אַ סך תהלים, נאָר בשעת די אַרבעט, ווען זיינע הענט זיינען געווען מלוכלכות און זייער פאַרשמירט, דעמאָלט האָט ער ניט געזאָגט. דער בעש\"ט איז אַריינגעגאַנגען מיט זיינע תלמידים אין הויז פון דעם איש פּשוט און האָט זיי געהייסן פאַרמאַכן די אויגן און זאָלן אַרויפלייגן זייערע הענט אויף זיינע אַקסלען און האָט אָנגעהויבן זינגען אַ ניגון און זיי האָבן געזען וואָס זיי האָבן געזען. האָבן זיך די תלמידים זייער געוואונדערט, ווי קומט אין אַזאַ קליינע \"כאַטקע\" אַזאַ גרויסער הימלישער יריד.\nנאָכדעם איז דער בעש\"ט געגאַנגען מיט די תלמידים אין הויז פון דעם פּרוש און האָט זיי ווידער געהייסן פאַרמאַכן די אויגן און אַרויפלייגן די הענט אויף זיינע אַקסלען און געזונגען אַ ניגון שטילערהייט, האָבן די תלמידים דערזען נחשים ועקרבים.\nהאָט דער בעש\"ט מסביר געווען זיינע תלמידים, אַז [כבפנים].\nאון די נחשים ועקרבים וואָס זיי האָבן געזען איז מצד זיין – דעם פּרוש'ס – גסות הרוח, וואָס דאָס איז פון די ניצוצות פון נחש הקדמוני."]]],[300010649,"קכז\n\nאורחות צדיקים שער יז (שער הנדיבות): <i>יש שלשה מיני נדיבות, האחד נדיב בממון, השני נדיב בגוף, השלישי נדיב בחכמה, ואלו השלשה היו באברהם אבינו כו'</i>.\n<b>אברהם</b> אבינו הי' נדיב בממונו בגופו ובנפשו. בממונו – שהי' מאכיל ומשקה לכל עובר ושב. בגופו – שהי' משמש את הבאים לביתו. בנפשו – שהי' מניח את לימודיו העיוניים במחקרי אלקות. כדאיתא בספר יצירה<sup data-n=\"1\">281</sup> שאברהם אבינו עליו-השלום הי' חכם נפלא בחכמת המחקר האלקי, ובודאי שכל רגע ורגע היתה יקרה לו בנפשו, ועם זה הי' נדיב בנפשו להניח את עצמו בשביל ללמוד עם אנשים פּשוטים שאינם מערכו כלל<sup data-n=\"2\">282</sup>, כי נושא ותוכן מעלת נדיב בנפשו הוא להניח את עצמו בשביל טובת זולתו<sup data-n=\"3\">283</sup>.",[["1","281","ראה ספר יצירה סוף פרק ו."],["2","282","ראה גם ספר המאמרים תרפ\"ט ע' 98. וש\"נ."],["3","283","ספר הזכרונות ח\"א ע' 344."]]],[300010650,"קכח\n\nתפלת העמידה: <i>ותהי לרצון תמיד עבודת ישראל עמך</i>.\n<b>בתפלת</b> שמונה עשרה אנו מתפללים ותהי לרצון תמיד עבודת ישראל עמך, הפירוש: תמיד עבודת ישראל עמך עושה רצון להחליש את הגזרה ולבטלה, ועבודת ישראל שהיא עומדת תמיד לפני השי\"ת לעשות רצון טוב הם אותיות שבתורה, שהם בשני אופנים: אמירת אותיות שבתורה וספר תהלים וכתיבת ספר תורה שבה ישתתפו הכל<sup data-n=\"1\">284</sup>.",[["1","284","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ו ע' רפב. ושם לפנ\"ז: בשנת תקי\"ב הי' – ל\"ע – קטרוג גדול על מעזיבוז, והרבה אנשים נשים וטף חלו במחלות שונות וכמה מהם היו גוססים ר\"ל ותהי צעקה גדולה בעיר כי אין בית אשר אין שם חולה אחד או שנים.\nויבאו אל מורנו הבעש\"ט ויבכו במר נפשם על החולים, ויתחננו לו להרבות בתפלה עבורם.\nויען מורנו הבעש\"ט נ\"ע שהוא אינו יכול להושיע אותם בזה. ורק הם בעצמם יכולים להציל את החולים, להחליש או גם לבטל את רוע הגזירה, כי [ההמשך בפנים. ולאח\"ז ממשיך:]\nכרגע החליטו פה אחד לכתוב ספר תורה, וכולם התחייבו להשתתף בכתיבתה, מורנו הבעש\"ט אמר לסופרו הצדיק ר' צבי נ\"ע אשר הוא יכתוב שתי יריעות ותיכף התחילו החולים להרפא, ויקראו את הספר תורה בשם \"די מופת ספר תורה\"."]]],[300010651,"קכט\n\nברכת המזון: <i>לידך המלאה הפתוחה הקדושה והרחבה</i>.\n<b>בסידורו</b> של הבעש\"ט כתוב הגדושה (בגימ\"ל)<sup data-n=\"1\">285</sup>.",[["1","285","הובא בלקוטי שיחות חי\"ד ע' 476. ובכ\"מ. וראה לקוטי שיחות חכ\"ג ע' 287: \"הגדושה\" – מיט אַ גימ\"ל, אַז דאָס גיסט זיך אַריבער, וואָס דאָס איז אויך אַ סימן ברכה. ובלקוטי שיחות חכ\"ט ע' 319: הגדושה (מיט אַ גימל), וואָס איז נאָך מער ווי \"מלא\", עס קומט אַראָפּ אין אַן אופן פון גדוש.\nוראה שיחת ש\"פ במדבר מבה\"ח וער\"ח סיון תשי\"ב (תורת מנחם – התוועדויות ח\"ה ע' 209): כ\"ק מו\"ח אדמו\"ר הי' מבטא לפעמים תיבת \"הקדושה\" באופן שהי' נשמע בקו\"ף ובגימ\"ל: ה<i>ק</i>דושה וה<i>ג</i>דושה."]]],[300010652,"קל\n\nסדר הקפות: <i>עוזר דלים הושיעה נא</i>.\n<b>דער</b> בעש\"ט האָט געטייטשט: עוזר: דער אויבערשטער העלפט – דלים, אַז די וועלכע זיינען דלים זאָלען ווערען אויס דלים, דורכוואָס איז דאָס, דורך – הושיעה נא, דאָס מיינט אַ טרייסעל טאָן זיך אין מוחין אָדער מדות, אָדער עכ\"פ מיט די פיס. אַזוי ווי אין הלל בעת מען זאָגט \"הושיעה נא\" טרייסעלט מען דעם לולב און מען זאָגט \"הצליחה נא\" טרייסעלט מען ניט<sup data-n=\"1\">286</sup>.",[["1","286","ספר השיחות תש\"ד ע' 31. ושם לפנ\"ז: אַמאָל – אין יאָר תרנ\"א – האָט ר' יצחק גרשון בעת הקפות אין ליובאַוויטש געזאָגט: עוזר דלים הושיעה נא, מיט'ן נוסח הידוע, מיט אַ הפסק נאָכ'ן וואָרט דלים, האָט אויף דערויף געזאָגט כ\"ק אאמו\"ר הרה\"ק: דו ווייסט ניט דעם פּשט [ההמשך בפנים]."]]],[300010653,"קלא\n\n<b>אהבה ויראה</b>\n<b>וקרוב</b> להאמין מה שנשמע בשם הבעש\"ט ז\"ל שנודע אליו למעלה שמשך זמן רב כמה שנים לא נתקבל למעלה כל המצות שעשו בנ\"י למטה ונשאר הכל בעולם הפירוד כו' עד שמאיזה סיבה מהתאמצות צדיקים גמורים ויחידי סגולה שפעלו בעת רצון למעלה שיקובלו כו', ואין זה פלא כ\"כ כמו עוסק בתו' בלא דו\"ר כלל דלא פרחא לעילא כלל כו' כמ\"ש בזוהר<sup data-n=\"1\">287</sup>.",[["1","287","מאמרי אדמו\"ר האמצעי דרושי חתונה ח\"ב ע' תמח. וראה לקמן סימן קסה."]]],[300010654,"קלב\n\n<b>אהבת ישראל</b>\n<b>כ\"ק</b> מורנו הבעש\"ט זאָגט: אַז אהבת ישראל דאָס איז דער ערשטער טויער וואָס פירט אַריין אין חצרות הוי'<sup data-n=\"1\">288</sup>.",[["1","288","לקוטי דיבורים ח\"ב רו, סע\"א ואילך. ספר השיחות תרצ\"ו ע' 20."]]],[300010655,"קלג\n\n<b>רבינו</b> הזקן סיפר לבנו אדמו\"ר האמצעי: דער זיידע (הבעש\"ט) זאָגט אַז מ'דאַרף האָבן מסירת נפש<sup data-n=\"1\">289</sup> אויף אהבת ישראל, אפילו צו אַ אידן, וועלכן מ'האָט קיינמאָל ניט געזען<sup data-n=\"2\">290</sup>.",[["1","289","ראה לקוטי שיחות ח\"א ע' 105 ואילך. שם ע' 128. קונטרס אהבת ישראל (תשל\"ז) ע' 7. – ומועתק בזה הערת כ\"ק אדמו\"ר זי\"ע שם:\nולהעיר ממה שסיפר ר' אלימלך בשם רבו הרב המגיד: הערסט מלך וואָס מען זאָגט אין מתיבתא דרקיע, אַז אהבת ישראל איז ליב האָבן אַ רשע גמור ווי אַ צדיק גמור (ספר השיחות קייץ ה'ש\"ת ע' 117. ראה ספר המאמרים תשי\"א ע' 247).\nולהעיר גם מתומר דבורה (להרמ\"ק) פרק ב': ירגיל עצמו להכניס אהבת בני אדם בלבו, ואפילו הרשעים, כאילו היו אחיו ויותר מזה, עד שיקבע בלבו אהבת בני אדם כולם, ואפילו הרשעים יאהב אותם בלבו, ויאמר: מי יתן ויהיו אלו צדיקים שבים בתשובה, ויהיו כולם גדולים ורצויים למקום, וכמאמר אוהב נאמן לכל ישראל שאמר: ומי יתן כל עם ה' נביאים וגו'.\nבסדר הדורות ה\"א של\"ב (מס' חרדים): ב' חכמים גדולים מקובלים בדורינו מ' משה קורדאווירי הי' אב\"ד בק\"ק צפת ונפטר בשנת ש\"ל והאר\"י הי' מלווה מטתו והעיד שראה שלווהו תרין עמודי דנהורי וגמירי דלא אתחזי אלא לחד בדרא או לתרין (ויקהל משה ד\"ז ע\"ד). עכ\"ל – והמדובר בדורו של הרמ\"ק!"],["2","290","\"היום יום\" טו כסלו (מאגרות-קודש אדמו\"ר מהוריי\"צ ח\"ה ס\"ע פח ואילך). וראה אגרות-קודש שם ע' רמח. ספר השיחות קייץ ה'ש\"ת ס\"ע 115: מורנו הבעש\"ט האָט זיך מוסר נפש געווען אויף אהבת ישראל אפילו צו דעם וועלכן ער האָט גאָרניט געקענט. וראה ספר השיחות תש\"ז ע' 96. לקוטי שיחות ח\"א ע' 201. ח\"ב ע' 435 ואילך. ע' 686."]]],[300010656,"קלד\n\n<b>הרב</b> המגיד אמר: מרגלא בפומי' פון רבי'ן – הבעש\"ט – אהבת ישראל איז אהבת המקום, בנים אתם לה' אלקיכם<sup data-n=\"1\">291</sup>, אַז מען האָט האָלט דעם פאָטער האָט מען האָלט די קינדער<sup data-n=\"2\">292</sup>.",[["1","291","פ' ראה יד, א."],["2","292","\"היום יום\" כד מנחם אב (מאגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' תקנד)."]]],[300010657,"קלה\n\n<b>עס</b> איז פאַראַן צוויי טעמים אויף אהבת ישראל: א) ווייל ער איז אַ איד<sup data-n=\"1\">293</sup>. ב) ווייל ער איז אַ בן תורה, און פלעגט מבאר זיין די ביידע מעלות, אַז די מעלה ראשונה איז אַ מעלה עצמית, ביי אַלע אידן, און די צווייטע מעלה איז אַ התפּשטות מעלה<sup data-n=\"2\">294</sup>.",[["1","293","ראה לקמן סימן שס-שסא."],["2","294","ספר השיחות תש\"ג ע' 12. ושם לפנ\"ז: הצדיק הגאון הר' ברוך – אבי הוד כ\"ק רבינו הזקן – האָט שטאַרק מקרב געווען די פּשוט'ע אידן. ווי עס איז באַוואוסט פלעגן די גדולי תלמידי חכמים, רבנים און בעלי בתים לומדי תורה זיין אָפּגעזונדערט פון די פּשוט'ע בעלי מלאכות. אין די גרעסערע קהילות האָבן די בעלי מלאכות געהאַט באַזונדערע בתי תפלה.\nמורנו הבעש\"ט איז געווען דער ערשטער וואָס האָט דאַן מדריך געווען זיינע תלמידים מקרב זיין אַ אידן, ווייל ער איז אַ איד און האָט מבאר געווען אז [ההמשך בפנים. ולאח\"ז ממשיך:] תלמידי מורנו הבעש\"ט האָבן מסירות נפש'דיק אויסגעפאָלגט די הוראות מורנו הבעש\"ט, אויך אין דעם פּרט פון מקרב זיין די פּשוט'ע אידן האָבן זיי געהאַט געוויסע מסירות נפש פאַלן."]]],[300010658,"קלו\n\n<b>עס</b> איז דאָ אַ קורצע תורה פון הוד כ\"ק רבינו הזקן פון די ערשטע יאָרן פון זיין נשיאות, וועלכע ער האָט געזאָגט בשם רבו, דעם מעזריטשער מגיד בשם מורנו הבעש\"ט:\nאהבת ישראל מיינט האָלט האָבן אַ אידן אָן קיין שום חילוק, צי אַ למדן צי אַ פּשוט'ר איד, און דער אופן האהבה אין אהבת ישראל באַדאַרף זיין אַ ברידערלעכע<sup data-n=\"1\">295</sup>, וואָס די התגלות האהבה איז אין נשיקה<sup data-n=\"2\">296</sup>, אָט אַזוי ווי אהבת התורה איז, אַז מען איז מחבב און מייקר די מענטעלע פון אַ ספר תורה<sup data-n=\"3\">297</sup>.",[["1","295","מעלתה שאינה פוסקת ואין בה שינויים. ראה לקו\"ת ר\"פ בהר ועוד."],["2","296","שהיא באה ונמשכת מחמת פּנימיות אהבה שבלב, שאותיות הדבור אין יכולים להכיל אה\"ר זו. לכך אינה מתלבשת בדבור רק בבחי' נשיקין (תו\"א ס\"פ תרומה. וראה ג\"כ לקו\"ת שה\"ש בתחלתו)."],["3","297","ספר השיחות תש\"ז ע' 127."]]],[300010659,"קלז\n\n<b>דער</b> הייליגער בעש\"ט נ\"ע האָט געזאָגט צו זיינע תלמידים אז אהבת ישראל – האָלט האָבן אַ אידן – איז באַ אבינו שבשמים זייער טייער, ביים אויבערשטן ב\"ה איז יעדער איד אַ ספר תורה<sup data-n=\"1\">298</sup>.",[["1","298","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ט ע' שסו."]]],[300010660,"קלח\n\n<b>בבואו</b> [אדמו\"ר הזקן] למעזריטש הנה בימים הראשונים שמע כמה ספורים מכ\"ק מורנו הבעש\"ט נ\"ע בענין אהבת ישראל, ואמר כי בדרך כלל הנה כל בית ישראל נחלקו לשתי פלוגות, א) אנשים פשוטים שאינם יכולים ללמוד, ויש בזה כמה חלוקי דרגות, אבל בד\"כ הם בסוג אחד, ב) לומדים. ואם כי גם בהם יש כמה וכמה חלוקי דרגות, אבל בד\"כ הם ג\"כ בסוג אחד.\nדי מצוה פון אהבת ישראל – זאָגט כ\"ק מורנו הבעש\"ט נ\"ע – איז אויף ביידע גלייך. די אנשים פּשוטים באַדאַרף מען ליב האָבן, ווייל זיי זיינען דאָך נעבעך אנשים פּשוטים און מאמינים בה' ובתורתו מיט אַזעלכע ריינע פיינע תמימות'דיגע הערצער, און די לומדים באַדאַרף מען ליב האָבן ווייל זיי זיינען דאָך גדולים אין ידיעת התורה, און די הייליגע גמרא זאָגט דאָך<sup data-n=\"1\">299</sup> כל הגדול יצרו גדול, האָבן זיי – די לומדים – נעבעך אַזעלכע גרויסע פייערדיגע יצר הרע'ס, און דאָך זיינען זיי ב\"ה ערליכע אידן, באַדאַרף מען זיי ליב האָבן<sup data-n=\"2\">300</sup>.",[["1","299","סוכה נב, א."],["2","300","לקוטי דיבורים ח\"ב רו, ב. ספר השיחות תרצ\"ו ע' 20 ואילך."]]],[300010661,"קלט\n\n<b>מען</b> זאָל ליעב האָבן און מייקר זיין דעם גאָר פּשוטן אידן אַזוי ווי דעם גרעסטן גאון, ווייל ער איז אַ איד<sup data-n=\"1\">301</sup>, ואב אחד לכולנו כאמור, בנים אתם לה' אלקיכם{291}, ונאמר<sup data-n=\"2\">302</sup> אהבתי אתכם אמר ה'<sup data-n=\"3\">303</sup>.",[["1","301","ראה לעיל סימן קלה. לקמן סימן קמ. שנט. שס-שסא."],["2","302","מלאכי א, ב."],["3","303","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ט ע' שכט."]]],[300010662,"קמ\n\n<b>מען</b> בעדאַרף האָלט האָבן אַ אידן ווייל ער איז אַ איד. דער הפרש פון אַ איש פשוט ביז אַ משכיל איז נאָר אין דער התפשטות פון אור הנשמה, אָבער אין עצם הנשמה איז כל הנשמות מתאימות המה<sup data-n=\"1\">304</sup>.",[["1","304","אגרות-קודש שם ע' קסא."]]],[300010663,"קמא\n\n<b>מען</b> דאַרף מקרב זיין אויך אנשים פשוטים, ווייל מען דאַרף ליב האָבען אַ איד ווייל ער איז אַ איד. און יעדער איד איז ירידת נשמתו למטה בהתלבשות בגוף גשמי צוליב מאַכען דעם מטה הגשמי פאַר אַ כלי צו אלקות<sup data-n=\"1\">305</sup>.",[["1","305","אגרות-קודש שם ע' קסה."]]],[300010664,"קמב\n\n<b>איך</b> האָב ליב דעם פּראָסטען אידען, דער פּשוט'ער איד איז דער גרעסטער אוצר<sup data-n=\"1\">306</sup>.",[["1","306","אגרות-קודש שם ע' רפה. וראה לעיל סימן נז."]]],[300010665,"קמג\n\n<b>אין</b> אַ געוויסע תורה זאָגט דער בעש\"ט פאַר דער חבריא קדישא, אַז דורך דער עבודה פון מסירות נפש אויף אהבת ישראל איז מען זוכה צו גילוי מ\"ה שבנשמה מער ווי דורך דער טיפסטער השגה-עבודה אין אלקות<sup data-n=\"1\">307</sup>.",[["1","307","ספר המאמרים אידיש ע' 214."]]],[300010666,"קמד\n\n<b>פעם</b> אחד בא [הבעש\"ט] לאיזה מושב ובא באמצע השוק, ונתקבצו סביבו אנשים פשוטים נשים וילדים והתחיל לדבר אתם מענין אהבת ישראל, וביאר זה להם שזה יכולים להבין עד כמה שצריך להיות אהבת ישראל, מאהבת הקב\"ה לישראל. וביאר זה בדוגמא: באותה העיר הי' אחד ושמו ר' יעקב, בכלל בזמנים ההם הי' בכל העיירות אנשים בעלי כשרון מופלגים בתורה, וזה ר' יעקב הי' בקי בש\"ס גמרא רש\"י ותוס' בעל פה, והי' לומד בעל פה, און אַז מען לערנט בעל פּה מוז מען זיין מער צוגעבונדן, איז ער געזעסן און געלערנט אַ \"בויכיגן\" תוס' (כך קראו לתוספות ארוכים ביותר בולטים כמעט תופסים כל הדף), ובא אליו בנו הילד ואמר לו איזה דבר חכמה ונתפעל ר' יעקב מהדבר חכמה והפסיק לימודו – אָט דאָס פּועל'ט אַ קינד.\nאזוי אויך, השי\"ת איז פאַרנומען, כמארז\"ל<sup data-n=\"1\">308</sup> שלש שעות הראשונות יושב ועוסק בתורה כו', ומפסיק כביכול און פאַרנעמט זיך מיט די תפלות ובקשות ישראל, אַזוי איז די אהבת השם יתברך לישראל, אַז דער אויבערשטער האָט געדאַרפט באַשאַפן דעם מענטשן אמר למלאכים שרוצה לברוא האדם, ככתוב<sup data-n=\"2\">309</sup> נעשה אדם, והשיבו המלאכים מה אנוש כי תזכרנו<sup data-n=\"3\">310</sup>, אויף וואָס דאַרף מען אַזאַ מענטשן. אבל הקב\"ה ברא את האדם. איז אַ איד שטייט אויף אין דער פרי און לויפט דאַוונען בצבור ותיקין, ואחר כך כל היום איז ער טרוד ומוטרד און לאָזט אַלע עסקים און לויפט אין שול דאַוונען, ובין מנחה למעריב הערט ער \"עין יעקב\" און דאַוונט מעריב, און נעמט מיט זיך דעם ענין פון \"עין יעקב\" אַהיים, איז דעמולט רופט דער אויבערשטער צונויף די מלאכים און באַרימט זיך מיט דעם מענטשן וואָס ער האט באַשאַפן, און זאָגט זיי: איר מלאכים האָט ניט קיין רחיים על צוארו קיין פרוי און קינדער, קיין טרדות, קיין מסים וארנוניות, אָבער דער אדם האָט רחיים על צוארו, אשה ובנים, און די רחיים האָב איך אים געהייסן נעמען אויף זיך, ער האָט דאָך געטאָן ע\"פ התורה, דאַרף ער זיי מפרנס זיין און איז טרוד ומוטרד, און האָט מסים וארנוניות ועול הגלות און דאָך איז ער זיך מתנהג אַזוי, בארימט זיך מיט אים דער אויבערשטער.\nאון אַז מען זאָל זיך אין דעם מצייר זיין ווי פון כל דבר בארימט זיך דער אויבערשטער מיט עם, וועט דאָס פּועל זיין אַ סאך<sup data-n=\"4\">311</sup>.",[["1","308","ע\"ז ג, ב. ד, ב."],["2","309","בראשית א, כו."],["3","310","תהלים ח, ה."],["4","311","ספר השיחות תרצ\"ט ע' 317 ואילך (הועתק בשינויים קלים – בלקוטי שיחות חכ\"ד ע' 533 ואילך). ושם לפנ\"ז:\nהבעש\"ט קודם התגלותו ובתחלת שנות התגלותו, הי' דרכו ליסע במושבות ישראל והי' באמצע השוק מקבץ סביבו אנשים פשוטים נשים וילדים והי' מספר להם סיפורים, הסיפורים היו בעיקרם מדבר אגדות רז\"ל או איזה סיפור המוזכר באגדה והי' מאריך ומבאר אותו או איזה ענין המוזכר באגדה הי' מקשר אליו איזה סיפור בכדי שהענין יהי' נקבע ונקלט בהשומעים. פעם אחד [ההמשך בפנים. וממשיך שם:]\nהמעשה הלזאת סיפרה אדמו\"ר הצ\"צ באחד מלילי חנוכה, שהי' המנהג אצלו שבאחד הלילות היו עושים \"לאַטקעס-אָווענט\" והיו באים כל בניו כלותיו ובני ביתם והי' מספר להם סיפורים שהיו מבינים גם בני הבית, ובאחד הלילות חנוכה הנ\"ל סיפר סיפור זה."]]],[300010667,"קמה\n\n<b>דער</b> בעש\"ט האָט געזאָגט, אַז אַ ברכה פון גוטע פריינט איז חשוב אין הימל אָנגענומען צו ווערן מער ווי די המלצה טובה און התעוררות רחמי שמים פון מלאך מיכאל<sup data-n=\"1\">312</sup>.",[["1","312","לקוטי דיבורים ח\"ג תקסד, ב. ספר השיחות תש\"ה ע' 68. ושם לפנ\"ז:\nדער רבי וואָס ער איז דער מחולל און גרינדער פון תורת וחסידות חב\"ד ערקלערט יעדן ענין אויף זיין חב\"ד שטייגער, האָט ער – דער אַלטער רבי – אויך ערקלערט דעם בעש\"ט'ס וואָרט אויף דעם חב\"ד שטייגער [ההמשך בפנים. וממשיך שם:]\nדער טעם הדבר – זאָגט דער רבי – איז, עס שטייט בנים אתם לה' אלקיכם, אידן זיינען השי\"ת'ס קינדער.\nדער סדר הנהגה למעלה איז ווי למטה, למטה זעהען מיר אַז עלטערן – טאַטע מאַמע – טוען אַלץ צוליב דעם גוט פון די קינדער, אָט אַזוי איז אויך למעלה באַ השי\"ת איז יעדער איד טייער, ער ית' איז זיך מצטער מיט דעם ניט גוט פון יעדן אידן, און פרייט זיך מיט דעם גוט פון יעדן אידן, און אַז ח\"ו וח\"ו הקב\"ה שטראָפט אַ אידן אין געזונט, קינדער, אָדער פּרנסה איז די כוונה אַז מען זאָל ווערן בעסער.\nלמטה זעען מיר אַז טאַטע און מאַמע האָבן דעם גרעסטן פאַרגעניגן אַז די קינדער ליבען זיך, און אַזוי איז אויך למעלה אין הימל, און דאָס איז דער טעם וואָס דער רבי דער בעש\"ט זאָגט אַז אַ ברכה פון גוטע פריינד איז חשוב אין הימל אָנגענומען צו ווערן מער ווי די המלצה טובה פון התעוררות רחמי שמים פון מלאך מיכאל, ווייל ווי גרויס מלאך מיכאל איז און ווי גוט ער זאָל ניט זיין איז ער אַלץ מער ניט ווי אַ מלאך, אָבער נשמות זיינען דאָך העכער במדריגה פון מלאכים און דערום איז אַ ברכה פון גוטע פריינד מער חשוב אין הימל ווי אַ המלצה טובה און התעוררות רחמי שמים פון מלאך מיכאל."]]],[300010668,"קמו\n\n<b>מקובל</b> בשם הבעש\"ט דכל הפוסק איזה דבר על חבירו הן לטוב והן לרע הוא פוסק על עצמו. כגון האומר עבור מעשה הטוב או דיבור הטוב שעשה או דיבר זולתו מגיע לו שיעזרהו השי\"ת בהדרוש לו, או האומר בעד הלא-טוב שעשה או שדיבר חבירו מגיע לו כך וכך, הנה בכל דבר אלה הוא פוסק על עצמו, בין לרע ובין לטוב, והמצדיק דין שמים על זולתו ואינו מצטער ומעורר עליו רחמים, הנה בדיבורו זה מקטרג על עצמו שמעיינים במעשיו ובדיבוריו, והמשתתף בצערו של חבירו ומעורר עליו רחמים בא על שכרו<sup data-n=\"1\">313</sup>.",[["1","313","\"התמים\" חוברת ז' ע' קד [שע, ב]. וראה לעיל סימן קיב-קיג."]]],[300010669,"קמז\n\n<b>מאמר</b> הבעש\"ט באחת משיחותיו הקדושות: הנני מעיד עלי שמים וארץ, אשר במשפט הקשה שהי' על איש אחד בבית-דין של מעלה והוא איש פשוט שלא ידע רק להתפלל ולאמר תהלים, והי' מופלא באהבת ישראל בכל כחות נפשו: במחשבה שחשב תמיד באהבת ישראל, בדבור שהי' מדבר באהבת ישראל ומעשה שהי' מהנה לכל אחד מישראל כפי כחו, הצטער בצערו של כל אחד מישראל בין איש ובין אשה ושמח בשמחתו, ופסקו בבית-דין של מעלה חלקו בגן עדן בין הצדיקים הגאונים שאמרו רז\"ל שהם אוהבי ישראל.\nדער קרעכץ וואָס אַ איד גיט אויף דעם צער ח\"ו פון אַ צווייטן אידן – צוברעכט אַלע מחיצות של ברזל פון די מקטרגים, און די שמחה און ברכה וואָס אַ איד פרייט זיך מיט דער שמחה פון נאָך אַ אידן און בענטשט אים – איז מקובל באַ השי\"ת ווי תפלתו של ר' ישמעאל כהן גדול אין קדש הקדשים<sup data-n=\"1\">314</sup>.",[["1","314","ספר השיחות תש\"ג ע' 161."]]],[300010670,"קמח\n\n<b>מקובל</b> בידינו בשם מורנו הבעש\"ט: כששומעים דבר לא טוב על אחד מישראל, גם אם אין מכירים אותו, צריך להצטער צער רב, כי אחד מהם הוא בודאי לא טוב: אם אמת הדבר שמספרים על פלוני, הלא הוא לא טוב, ואם אינו אמת הלא המספר נמצא במצב לא טוב<sup data-n=\"1\">315</sup>.",[["1","315","\"היום יום\" יב כסלו (מאגרות-קודש אדמו\"ר מהוריי\"צ ח\"ה ס\"ע קא ואילך). וראה גם ספר השיחות תרפ\"ט ע' 37."]]],[300010671,"קמט\n\n<b>אַ</b> תורה גס הרוח באַדאַרף מען מעורר זיין מיט אהבת ישראל, אַזוי פיל מקרב זיין ביז יענער דערפילט זיין חסרון<sup data-n=\"1\">316</sup>.",[["1","316","ספר השיחות קייץ ה'ש\"ת ע' 119. ושם (ע' 118):\nאין אַ געוויסער שטאָט, וואוהין דער מגיד פלעגט קומען מזמן לזמן, איז געווען אַ בעל הבית נכבד, אַ גרויסער בעל צדקה און בעל מדות טובות, וועלכער פלעגט ניט גיין הערן דעם מגיד און פלעגט געפינען כמה דרכים ווי אויסצומיידן אַז דער מגיד זאָל זיך מיט אים טרעפן.\nר' ישראל יצחק נדבן – אַזוי האָט געהייסן יענער בעל הבית – איז געווען באמת אַ גרויסער למדן, און יומם ולילה געלערנט מיט התמדה. ער האָט געהאַט אַ בראיי הויז וואָס האָט אים געגעבן פּרנסה בהרחבה גדולה באופן אַז ער האָט געקענט געבן צדקה ביד רחבה, און ער האָט טאַקע געטאָן צדקה און עוסק געווען בגמילות חסדים ביד רחבה.\nר' ישראל יצחק'ס אַ גמילות חסד האָט זייער מצליח געווען און אַלע בעלי עסקים, גרויסע אַזוי ווי קליינע, פלעגן באַ אים נעמען אַ גמילות חסד אויף הצלחה און ער פלעגט געבן מיט גרויס פאַרגעניגן.\nפון צייט צו צייט איז ר' ישראל יצחק מצליח געוואָרן מער גס הרוח און מער צופרידן פון זיך. הגם ער איז געווען אַ גרויסער ירא שמים און למדן, אָבער ער האָט זיך געהאַלטן פאַר אַ גרויסן בעל מדריגה און אַזוי אַרום באַרעכטיגט צו דער ברכת הצלחה, און הערנדיק אַז דער מגיד וואָס קומט מזמן לזמן רעדט שאַרפע דברי מוסר, האָט ער מורא געהאַט טאָמער וועט דער מגיד אים ניט אָפּגעבן דעם געהעריקן כבוד וואָס עס קומט אים לויט זיין מיינונג, און צוליב דעם האָט ער געטאָן אַלץ אויף ניט צו באַגעגענען זיך מיטן מגיד.\nהצדיק הגאון רא\"מ קרעמעניצער האָט געוואוסט אַז ר' ישראל יצחק מיידט אים אויס צוליב דער מורא ער זאָל אים ניט פּוגע בכבוד זיין, אָבער רא\"מ האָט זיך געמוזט באַקענען מיט אים.\nווען זיי האָבן זיך באַקענט, האָט הגרא\"ם געפרעגט אַ ענין אין לערנען. רי\"י האָט דעם ענין שטאַרק גוט געזאָגט, און הגרא\"מ האָט זייער הנאה געהאַט, און האָט אים געזאָגט אויף אייער תורה איז אַ גרויסער רחמנות, און האָט מבאר געווען דעם מאמר גסות הרוח שבו טרדתו מן העולם.\nר' ישראל יצחק איז געוואָרן זייער צוטראָגן. דברי הצדיק האָט אים שטאַרק פאַרדראָסן, זיין גסות הרוח האָט דאָס ניט געקענט צונעמען און עס האָט אים שטאַרק מבלבל געווען צו עסק התורה.\nהגרא\"מ האָט געפילט אַז הרי\"י איז דורך זיין מוסר געוואָרן אַ יורד ממדריגתו אין עסק און הצלחת הלימוד, און הגרא\"מ האָט געהאַט דערפון שטאַרקע עגמת נפש. ווען ער האָט זיך דערנאָך געזעען מיט מורנו הבעש\"ט האָט ער אים דערציילט דעם ענין. האָט אים מורנו הבעש\"ט געזאָגט אז [ההמשך בפנים:]."]]],[300010672,"קנ\n\n<b>אומות העולם</b>\n<b>ואף</b> כל המלחמות בין האומות הוא צורך איזה בירור מהם אף שאין שייכות זה לקדושה. והיינו כענין שאמר הבעש\"ט ז\"ל שהי' איזה מלחמה ז' שנים בין שני גוים בשביל שיתבררו הקולות מתרועת המלחמה כו' ויעשה מהם איזה ניגון שיעבוד הצדיק את ה' בניגון ההוא כו'<sup data-n=\"1\">317</sup> וד\"ל<sup data-n=\"2\">318</sup>.",[["1","317","ראה גם תורת חיים ס\"פ ויחי (קח, ד [רמט, ד])."],["2","318","ספר מאה שערים ע' כח. מאמרי אדמו\"ר הזקן תקס\"ה ח\"א ס\"ע רא ואילך."]]],[300010673,"קנ-א\n\n<b>אותיות – אות יו\"ד</b>\n<b>וכידוע</b> בשם הבעש\"ט נ\"ע שהיו\"ד מורה על הנביעה מא\"ס בבחי' החכ' כו'<sup data-n=\"1\">319</sup>.",[["1","319","סה\"מ תר\"ל ע' לה."]]],[300010674,"קנא\n\n<b>אחדות השם</b>\n<b>וע\"פ</b> עומק יסוד הבעש\"ט בזה\"ק יתפרש עוד ענין זה ביותר הפלא ופלא בביאור ענין היחוד . . שאין עוד ממש אפי' בנבראים ור\"ל שע\"פ האמת אין הנבראים בחי' יש ודבר כמו שנראי' אנחנו בעינינו כי זהו אצלינו לפי שאיננו רואים חיות האלקות, אבל לגבי חיות אלקות המחי' אותנו אנחנו בטלים ממציאות . . וזהו אמיתית החסידות<sup data-n=\"1\">320</sup>.",[["1","320","סהמ\"צ להצ\"צ מצות אחדות ה' פ\"ג (סב, א). וראה שם מצות זכירת מעשה עמלק (צד, ב): והנה אנו אומרים מודים אנחנו לך, פי' שאנחנו מודים שהאמת כמו שהוא קמי' ית', שלמעלה הוא היש ולמטה הוא אין, וזהו כל עיקר מצות האמנת היחוד לפמש\"ש פ\"ג בשם הבעש\"ט ז\"ל. וראה לקוטי שיחות חכ\"ד ע' 181: דער בעש\"ט האָט מגלה ומדגיש געווען דעם פנימיות ואמיתית ענין פון \"אין עוד מלבדו\" – אַז ס'איז ניטאָ קיין מציאות זולתו ית'."]]],[300010675,"קנב\n\n<b>אכילה</b>\n<b>ווען</b> אַ אידען ציט די האַרץ אַז ער וויל עסען, זהו התעוררות בהנשמה, שהנשמה מתגעגעת למקורה, כמו שהנר בטבעו וכו', אבל האדם אינו מרגיש וסובר שרוצה לאכול<sup data-n=\"1\">321</sup>.",[["1","321","אגרות-קודש אדמו\"ר מהוריי\"צ חי\"ד ע' תמה. וממשיך שם: ובזה פי' אדה\"ז ענין שהיו מרעיבים עצמם ב' שעות וכו', שרעבון שלהם היו ממלאים במזון דתורה, ואח\"כ רעבון הגוף."]]],[300010676,"קנג\n\n<b>אלף אלפים</b>\n<b>המספר</b> אלף אלפים הנה התחלתו הוא הקוץ העליון של האל\"ף ומקוץ הזה נמשך חיות עצמי ופנימי באלף אלפים<sup data-n=\"1\">322</sup>.",[["1","322","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"י ע' רסה."]]],[300010677,"קנד\n\n<b>אמונת צדיקים</b>\n<b>הנה</b> מענין אמונת חכמים צדיקים יש אדם שהוא שוטה במילי דעלמא והוא בעל מדות רעות ויש להם אמונה בצדיקים, ויש אנשים אחרים שהם חכמים ויש להם מע\"ט אעפי\"כ אין להם אמונה בצדיקים ואינם יודעים האמת, [ולכאורה תמוה, ושמעתי תירוץ בשם הבעש\"ט ז\"ל דהנה יש עוד קושי' מפני מה יש צדיקים שהם בהסתר ואינם בהתגלות אל העולם אלא למתי מספר] ואינם בהתגלות אל העולם דהיינו כמו הבעש\"ט הנ\"ל שהי' ישן כל היום ולומד כל הלילה ולא בהתגלות אלא למתי מספר, ולכאורה הוא תמוה שהביא הרבים לידי שדברו עליו לה\"ר ורכילות מפני שלא היה בהתגלות אל כל העולם בודאי לא היה ירא משום גאוה ופני' ח\"ו.\n<b>אך</b> הענין הוא הוא כן בכל דור ודור יש צדיק שא\"א לעולם בלי צדיק שצדיק יסוד עולם<sup data-n=\"1\">323</sup>, אך אם הדור זוכים הצדיק שלהם בהתגלות אצלם ואם לאו הוא בהסתר אצלם, אך גם זה תמוה שאנו רואים אדם שאין לו זכיות ועוונות ולא שייך לומר שזכה זה דהיינו נער בן י\"ג שנה מפני מה זכה זה שיודע האמת ויש לו אמונה בצדיקים דודאי אין לפי מעשיו. אך הענין הוא דהכל תלוי בשרשים שעכשיו הוא גלגולים ואם השורש מזוכך שבא לידי הזדככות ע\"י גלגולים שזוכה שהצדיק שלו יהי' בהתגלות, והשרשים שאינם מזוככים כל כך אזי הצדיק שלהם בהסתר ומפני זה אין להם אמונה בו [ואף אם הי' בהתגלות לא הי' להם אמונה בו], אלא שמכניסים הדבר בטבע מפני שהוא בהסתר פנים, מפני כן אין יודעים בו.\n<b>וא\"כ</b> מה שאנו יודעים האמת ויש שם אמונה בצדיקים אין זה תלוי במעשים הטובים כנ\"ל שזה נמשך מהשורש שלו וא\"כ אין לנו יתרון על בנ\"א שאין יודעים האמת ומתנגדים [על הצדיקים] שאפשר שיש שם יותר אלקות שעושים מצות ומע\"ט הרבה, וא\"כ אין ראוי להיות בפירוד עמהם אלא צריך להיות אחדות עמהם. ושמעתי שזה גורם התנגדות יותר מה שעושין פירוד ואומרים שהסתלקות האלקות אצלם שזה רע גמור, וצריכין להאמין שהכל הוא אלקות שנתלבש בהם וזה נק' המתקת הסוד [הדינים] בשרשו ואז לא יהי' שורש דין ויהי' באמת רחמים. ואעפ\"י שאנו רואים בתורה שמשה רע\"ה היה במחלוקת עם קורח אין ראיה, וקורח הי' הסתלקות האלקות לגמרי, וכמאמר בני גד ובני ראובן כל אשר דיבר לעבדיך נעשה<sup data-n=\"2\">324</sup> והלא מעולם לא ציוה ה' ומשה מעצמו אמר, אלא ודאי מה שמשה אמר הוא וודאי אלקות בלתי ספק. אבל עכשיו אין צדיק שיהי' טוב כמשה, ולהיפך בכל רע מהסתלקות האלקות כקורח. אלא שאינם זוכים שהצדיק שלהם יהי' בהתגלות אלא בהסתר כנ\"ל. והכלל שצריך להיות באחדות עמהם ושלא לאמר שאנו יודעים האמת והם אינם יודעים והם ברע גמור שאין שם אלקות, שזה יותר גורם התנגדות כנ\"ל. כל זה [שמעתי] מהבעש\"ט זלה\"ה וד\"ל<sup data-n=\"3\">325</sup>.",[["1","323","משלי י, כה."],["2","324","ע\"פ מטות לב, לא."],["3","325","מאמרי אדמו\"ר הזקן ענינים ע' רצט-ש."]]],[300010678,"קנה\n\n<b>אנשים פשוטים</b>\n<b>די</b> פּשיטות העצמות פון עצמות א\"ס ב\"ה איז זיך מתגלה אין די פּשיטות פון אַ איש פּשוט<sup data-n=\"1\">326</sup>.",[["1","326","לקוטי דיבורים ח\"ג תצא, ב. ספר השיחות תש\"ז ע' 136. ושם לפנ\"ז: עס איז אַ מצוה לפרסם, אַז אַלע זאָלן וויסן, אַז די מעלה פון אַ איש פּשוט איז אין להעריך.\nדעם ענין האָט מגלה געווען מורנו הבעש\"ט אין עטלעכע קורצע ווערטער: [ההמשך בפנים. ולאח\"ז ממשיך:].\nהוד כ\"ק רבינו הזקן וואָס האָט מקבל געווען תורת הבעש\"ט מהוד כ\"ק מורנו הרב המגיד ממעזריטש, האָט עס מבאר און מסביר געווען, אַז בעלי תורה און בעלי עבודה, איז דאָך דאָס הגבלה, גילויים און ניט עצמות. תורה און מצות זיינען עצמות, אָבער ניט פּשיטות העצמות. די מעלה פון עצמות איז דאָך פּשיטות.\nפּשיטות העצמות, וואָס דאָס איז גאָר אַן אַנדער זאַך, אויף דעם איז געווען תכלית ירידת הנשמה בגוף און תכלית בריאת העולמות: אצילות, בריאה, יצירה, עשי' ביז עוה\"ז הגשמי, צוליב עולה זיין צו פּשיטות העצמות, וואָס איז אַ סך העכער פון עולם האצילות.\nאצילות נעמט נאָר אַ געוויסע מעקלעריי, אָבער די פּשיטות העצמות פון עצמות א\"ס ב\"ה איז פאַראַן אין די פּשיטות פון אַ איש פּשוט. וראה לקוטי דיבורים ח\"ד תקעח, ב ואילך. ספר השיחות ה'שי\"ת ע' 383. לקוטי שיחות ח\"ב ע' 559. שיחת ש\"פ שמות תשכ\"ה."]]],[300010679,"קנו\n\n<b>העבודה</b> פשוטה בפשיטות העבודה בקיום התומ\"צ דאנשים פשוטים הוא כלי לעצם הפשוט יתברך ויתעלה<sup data-n=\"1\">327</sup>.",[["1","327","ספר המאמרים תרצ\"ו ע' 13. וראה גם שיחת יב תמוז תש\"ח ס\"ל (ספר השיחות תש\"ח ע' 248)."]]],[300010680,"קנז\n\n<b>עס</b> איז ידוע דער מאמר קדש וואָס דער אַלטער רבי האָט געזאָגט בשם הבעל שם טוב, אַז דעם פשוט'ן אידנ'ס קיום המצות מצד אמונה אין עצמות, איז אַ כלי צו עצמות און איז גורם אַ נחת רוח אין עצמות. די פּשיטות העצמות איז שורה אין דער כלי פון קיום המצות בפּשיטות<sup data-n=\"1\">328</sup>.",[["1","328","ספר השיחות תש\"ו ע' 3. ובשיחת יום ב' דחג השבועות תשי\"ג סמ\"ח (תורת מנחם – התוועדויות ח\"ח ע' 242): \"אומרים בשם הבעש\"ט . . שבכח האמונה יכול יהודי לפרוס מטפחת (\"אַ פאַטשיילע\") בים ולעבור את הים\"."]]],[300010681,"קנח\n\n<b>איש</b> הפּשוט הוא כשדה זרועה אשר למטר השמים תשתה מים<sup data-n=\"1\">329</sup> ותתן את יבולה. והתלמיד חכם הוא כשדה בית השלחין אשר בעלי' משקה אותה ולפיו תתן את יבולה. וכמו המצייר שהוא אומן נפלא בציור הנה כל אומנתו הוא כשמצייר את השדה ותבואתה כאשר הם באמת כפי הדר הטבע שהטביע הקב\"ה בה. וכל אומן שציורו מתאים יותר אל הטבע יותר הוא גדול באומנתו. וכן הוא באיש הפּשוט ובבן תורה, בן תורה כשדה בית השלחין ויכול להיות שהיבול ממנה הוא טוב יותר מיבול שדה רגילה. אבל הדר הטבע שהטביע הקב\"ה שהוא האמת הוא בשדה אשר למטר השמים תשתה מים יותר מבית השלחין<sup data-n=\"2\">330</sup>.",[["1","329","עקב יא, יא."],["2","330","ספר הזכרונות ח\"א ע' 345."]]],[300010682,"קנט\n\n<b>גם</b> איש פּשוט שבישראל נעלה הוא בעצם מהות מעלתו כמו גאון הגאונים ממש<sup data-n=\"1\">331</sup>.",[["1","331","ספר השיחות תש\"ג ע' 161."]]],[300010683,"קס\n\n<b>דער</b> בעש\"ט זאָגט, אַז אַ גדול שבגדולים דאַרף זיך לערנען פון אַ פּשוט שבפּשוטים, וואָס ביי זיי איז דאָ די עצם התמימות<sup data-n=\"1\">332</sup>.",[["1","332","ספר השיחות תש\"ה ע' 91. ושם:\nבאַ חסידים איז ניטאָ קיין חילוקים פון גרויסע און קליינע, אַלע זיינען גלייך. ווי הוד כ\"ק אדמו\"ר הזקן זאָגט אין תניא<sup data-n=\"2\">1</sup>, שכולן מתאימות ואב אחד לכולנה. עס זיינען דאָ חילוקים ווי בני תורה, יושבי אוהל, בעלי עסקים, אָבער דאָס איז נאָר בהתגלות אָבער מצד הנשמה זיינען אַלע גלייך. דער בעש\"ט [ההמשך בפנים. ולאח\"ז ממשיך:]\nאין חסידות פון הוד כ\"ק רבינו הזקן<sup data-n=\"3\">2</sup> איז מבואר כמה דרגות אין תמימות און אַז די עצם התמימות איז בהתגלות ביי אנשים פּשוטים.\n-----שולי הגליון-----"],["2","1","<i>פרק לב</i>."],["3","2","<i>כ\"ה ברשימת ההנחה</i>.<i> – ואולי צ\"ל אדמו\"ר האמצעי</i>.<i> ראה דרך חיים ע' יב</i>.<i> טז</i>."]]],[300010684,"קסא\n\n<b>בשם</b> מורנו הבעש\"ט: אַז בשעת פתיחת הארון איז אַ איד גאָר אַ פּשוט'ר איד זאָגט בריך שמי' דמרא עלמא, בריך כתרך ואתרך, יהא רעותך עם עמך ישראל לעלם, מיט אַ אמונה פּשוטה, פון טיפן האַרצן, איז הקב\"ה ממלא זיין בקשה כולה אָדער מקצתה<sup data-n=\"1\">333</sup>.",[["1","333","לקוטי דיבורים ח\"ב רכו, סע\"א ואילך. ספר השיחות תרצ\"ו ע' 49."]]],[300010685,"קסב\n\n<b>דער</b> בעש\"ט זאָגט אַז יעדער איד, אפילו דער פּשוט שבפּשוטים קען און דאַרף זיין אַ עובד ה'<sup data-n=\"1\">334</sup>.",[["1","334","ספר המאמרים אידיש ע' 202."]]],[300010686,"קסג\n\n<b>אפיקורסים</b>\n<b>והן</b> הן אפיקורסים שכופרים בה' לגמרי ואינם מאמינים בחידוש העולם, כידוע שאין להם עליה ותיקון כלל, כידוע בשם הבעש\"ט ז\"ל שיותר יש תיקון לגוי עובד ע\"ז מן האפיקורסים מטעם הנ\"ל<sup data-n=\"1\">335</sup>. וראי' לזה שהרי לעתיד נאמר<sup data-n=\"2\">336</sup> אז אהפוך אל עמים כו' ונהרו<sup data-n=\"3\">337</sup> אליו כל הגוים כו' לפי שהם מאמינים באחדות ה' רק שמפני משכא דחויא נתגשמו ביותר נדמה להם הנהגה הטבעית שע\"פ הכו\"מ וכה\"ג שזהו העיקר ולע\"ל כתיב<sup data-n=\"4\">338</sup> וראו כל בשר מפני שיהי' לאחר הבירור כו' אבל האפיקורסים אין להם עליה גם לעתיד כ\"א איבודם זהו תקונם כו'<sup data-n=\"5\">339</sup>.",[["1","335","ראה מגן אבות ח\"ז סח, א-ב."],["2","336","צפני ג, ט."],["3","337","ישעי' ב, ב."],["4","338","שם מ, ה."],["5","339","דרוש תער השכירה – אוה\"ת נ\"ך ח\"ב ריש ע' תשפב. וראה גם לקו\"ש ח\"ח ע' 303: \"וכידוע דכופר גמור – גרוע מעוע\"ז (ראה הסדר ברמב\"ם הל' תשובה פ\"ג ה\"ז והלכות עדות סוף פי\"א, שו\"ע אדמו\"ר הזקן הלכות נזקי גוף ונפש סעי' ט-י). וכמאמר הבעש\"ט ז\"ל שיותר יש תיקון לגוי עוע\"ז מן האפיקורסים שכופרים בה' לגמרי ואינם מאמינים בחידוש העולם\"."]]],[300010687,"קסד\n\n<b>ארץ העמים</b>\n<b>בשם</b> הבעש\"ט ז\"ל: נתפזרו ישראל בכל מקומות הארץ באיים רחוקים, וגם מה שטועים<sup data-n=\"1\">340</sup> בדרך להתהלך בעיירות, הוא כדי לטהר ארץ העמים שאוירה טמא, וישראל באמונתם הפּשוטה בלב כאו\"א מישראל אף שהוא בבחי' שינה אפ\"ה מטהרת טומאת האויר, מפני שהוא עטרת בעלה וכו'<sup data-n=\"2\">341</sup>.",[["1","340","נו\"א: שתועים. וכ\"ה ב\"היום יום\" חלק שני ע' יח."],["2","341","ספר תקנ\"ז. הועתק בהערת כ\"ק אדמו\"ר מהורש\"ב נ\"ע בהוספות ללקו\"ת יח, ד. מאמרי אדמו\"ר הזקן הקצרים ע' רנו. וראה בשם הבעש\"ט – מאמרי אדמו\"ר הזקן ענינים ע' קלא. וראה גם (לא בשם הבעש\"ט) מאמרי אדמו\"ר האמצעי קונטרסים ע' יב. ע' ערב."]]],[300010688,"קסה\n\n<b>התפלה</b> שאנו מתפללים בכאן מתערבות באוירא מסאבא של ארץ העמים, ויכול להיות אשר התפילות דכאן אינה עולה כלל כמ\"ש<sup data-n=\"1\">342</sup> בשם הבעש\"ט<sup data-n=\"2\">343</sup>.",[["1","342","ראה שבחי הבעש\"ט (מהדורת הורודצקי – תש\"ז) ע' קו. שבחי הבעש\"ט כת\"י (ירושלים, תשמ\"ב) ע' 85."],["2","343","מאמרי אדמו\"ר האמצעי קונטרסים ע' כז."]]],[300010689,"קסו\n\n<b>ביטול</b>\n<b>הבעש\"ט</b> כינה לו<sup data-n=\"1\">344</sup> במשל אותיות באופן ערך ביטול אות א' מן המח' לגבי מהות הנפש עצמה כן ערך ביטול אוא\"ס ב\"ה המהווה עולמות אבי\"ע לגבי עצם המאור המאציל ית' בעצמו'<sup data-n=\"2\">345</sup>.",[["1","344","להארת אוא\"ס ב\"ה ראשית הקו."],["2","345","מאמרי אדמו\"ר הזקן ענינים ע' שכח. וממשיך שם: ויש לכינוי זה סמך מדרז\"ל בתושבע\"פ ע\"פ בי\"ה ה' צור עולמים בי\"ה [אוצ\"ל: בה\"א] נברא העולם הזה וביו\"ד נברא העוה\"ב כו' וד\"ל."]]],[300010690,"קסז\n\n<b>בני ישראל</b>\n<b>מאמר</b> הבעש\"ט: אַז יעדער איד איז טייער ביי דעם אויבערשטן ווי אַ בן יחיד וואָס איז געבאָרן געוואָרן ביי עלטערן לעת זקנותם<sup data-n=\"1\">346</sup>, און נאָך טייערער<sup data-n=\"2\">347</sup>.",[["1","346","דלכאורה, איז ניט מובן דער משל פון \"הורים זקנים לעת זקנותם\" אויף דעם אויבערשטן, ובלשון חז\"ל (יבמות טז, ב): \"מי איכא זיקנא קמי'\"?!\nויש לומר, ע\"פ הידוע אז \"זקן\" איז פאַרבונדן מיט (חכמה, ביז מיט) עתיק (יומין), וואָרום עתיק איז לשון זקן (כמ\"ש \"ועתיק יומין יתיב גו'\"), פנימיות הכתר, ביז מיט פנימיות עתיק, עצמות התענוג . . וי\"ל אַז דער משל הנ\"ל . . איז מרמז ווי אַ איד איז פאַרבונדן מיט בחי' זקן (עתיק) שלמעלה, וואָס איז איין זאַך מיט עצמות ומהות – ישראל וקוב\"ה כולא חד (ספר השיחות תנש\"א ח\"א ע' 422 ואילך)."],["2","347","לקוטי שיחות ח\"ג ע' 982. ועד\"ז שם ח\"ד ע' 1280.\nוראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"ד ע' רכ: דעם וואָרט פון שווער כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, וואָס ער האָט איבערגעגעבן אין נאָמען פון בעל שם טוב, אַז יעדער איד, סיי מאַן און פרוי, איז טייער ביים אויבערשטן ווי אַ בן יחיד ביים פאָטער (באמת מערער, נאָר מיר באַנוצן דעם ביישפּיל ווייל מיר קענען זיך ניט פאָרשטעלן אַ גרעסערע ליבשאַפט ווי צו אַ בן יחיד)."]]],[300010691,"קסח\n\n<b>אבינו</b> מלכנו אבינו אב הרחמים השי\"ת רעדט מיט אונז אידין אויף פערשידענע שפּראַכין. אויך, ער רעדט מיט אונז אידין ויא אַ פאָטער וואָס רעדט מיט אַ קלוגין קינד אויפן וואונק<sup data-n=\"1\">348</sup>.",[["1","348","אגרות-קודש אדמו\"ר מהוריי\"צ חי\"ג ע' רצה (ובשינויים – שם ע' רצז). וממשיך שם: ד. ה. אַז אַלעס וואָס עס טוט זעך אין אַלע לענדער בכלל, און מיט אחינו בני ישראל יחיו בפרט, בעדאַרפין מיר גוט פאַרשטיין, וואָס דאָס מיינט."]]],[300010692,"קסט\n\n<b>מורנו</b> הבעש\"ט זאָגט: לב ישראל חי. די אידישע האַרץ לעבט, מען באַדאַרף קענען מעורר זיין די פנימיות הלב, דאָס מיינט אַז מען באַדאַרף צוקומען צו די פנימיות שבלב, און ווען מען קומט-צו צו די פנימיות ווערט במילא אַ שינוי לטוב אויך אין חיצוניות הלב.\nדער וועג אויף צוקומען צו פנימיות הלב איז ענליך ווי צוצוקומען צו די מים חיים שליסל קוואַלן וואָס געפינען זיך אין דער ערד<sup data-n=\"1\">349</sup>.",[["1","349","ספר השיחות קייץ ה'ש\"ת ע' 34. עיי\"ש בארוכה. ברשימה אחרת מהשיחה (וכ\"ה ב\"היום יום\" ח\"ב ע' כ): מען דאַרף גראָבן אין זיך, אַזוי ווי אַ באר. פאַראַן אַזאַ וואָס די וואַסער איז אויבען אויף. עס איז אָבער פאַראַן אַזאַ וואָס מען דאַרף גראָבן אַסך, אַראָפּנעמען עפר ביז עס ווערט נתגלה ווערן די וואַסער."]]],[300010693,"קע\n\n<b>כ\"ק</b> רבו מורנו הבעש\"ט האָט אַמאָל געזאָגט די צווייטע נאַכט ר\"ה: דער טאַטע אין הימל, אבינו שבשמים, וויל הערן ווי זיינע קינדער זאָגן זיינע מעלות און זיינען אים זייער שטאַרק משמח מיט שבחים עצמיים, וואָס ניט נאָר מלאכים וואָס זיינען שכליים נבדלים, נאָר אויך ספירות דאצילות העליון, וואָס האָבן אַ שייכות צו חכמה ושכל פון עולמות בי\"ע קענען ניט מקבל זיין און פאַרשטיין דעם נחת רוח שלמעלה<sup data-n=\"1\">350</sup>.",[["1","350","ספר השיחות תש\"ב ע' 3. ושם:\nדי צווייטע נאַכט ר\"ה אין יאָר תרנ\"א האָט הוד כ\"ק אאמו\"ר הרה\"ק דערציילט, אַז די צווייטע נאַכט ר\"ה תרל\"ג האָט הוד כ\"ק אביו אאזמו\"ר הרה\"ק מוהר\"ש דערציילט, וואָס ער האָט געהערט מהוד כ\"ק אאזמו\"ר צ\"צ, וואָס ער האָט געהערט – צוזאַמען מיט כ\"ק דודו וחותנו, הוד כ\"ק הרה\"ק אדמו\"ר האמצעי – די צווייטע נאַכט ר\"ה תקנ\"ט, פון כ\"ק זקנו רבינו הזקן, אַז זייענדיק דעם ערשטן מאָל ביי מורו ורבו הרב המגיד ממעזריטש, האָט דער מגיד דערציילט וואָס כ\"ק רבו [כבפנים]. וראה ד\"ה ואתה קדוש שבספר המאמרים אידיש נעתק לעיל סימן ס."]]],[300010694,"קעא\n\n<b>אַ</b> איד איז ניט קיין עלענדער, וואו ער גייט און וואו ער שטייט איז ה' עמו<sup data-n=\"1\">351</sup>.",[["1","351","לקוטי דיבורים ח\"ג תצ, ב. ספר השיחות תש\"ז ע' 135. ושם:\nדער וואָרט איז רבי מפי רבי ביז דעם בעש\"ט נ\"ע. דער אַלטער רבי האָט דעם וואָרט געמאַכט אַ יסוד פאַר אַ ביאור, אויף דעם וואָס אין די זמנים פון בעש\"ט און מעזריטשער מגיד איז געווען די אידישע הויפּט-פּרנסה דאָרפס-גייעהריי, און אויף דעם האָט מען געזאָגט, אַז יעדער איד איז ניט עלענד, וואו ער גייט און וואו ער שטייט איז ה' עמו, דאָס הייסט די התגלות פון שם הוי'.\nדער וואָרט איז איינער פון די ווערטער וואָס הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ האָט מקבל געווען פון די זקני חסידי הוד כ\"ק רבינו הזקן, וועלכע האָבן דאָס געהערט פון הוד כ\"ק רבינו הזקן קומענדיק פון מורו הוד כ\"ק הרב המגיד ממעזריטש.\nווען הוד כ\"ק אאמו\"ר הרה\"ק האָט מיר איבערגעגעבן דעם יסוד וואָרט האָט ער באריכות גדולה מבאר געווען, אַז דער עיקר איז די התגלות שם הוי' דורך דעם שם אלקים."]]],[300010695,"קעב\n\n<b>כמו</b> ששמעתי מרבותי<sup data-n=\"1\">352</sup> כי אילו נמצא מלאך אחד עומד במעמד עשרה מישראל ביחד, אף שאינם מדברים בדברי תורה<sup data-n=\"2\">353</sup> תפול עליו אימתה ופחד בלי גבול ותכלית משכינתא דשריא עלייהו עד שהי' מתבטל ממציאותו לגמרי<sup data-n=\"3\">354</sup>.",[["1","352","מורנו הבעש\"ט והרב המגיד ממעזריטש (ספר השיחות תש\"ד ע' 97 (הועתק לקמן הערה 354). תש\"ה ע' 59). \"ולהעיר שמרמז גם להבעש\"ט וגם עליו קאי \"ששמעתי\". – לקוטי שיחות חט\"ז ע' 596 בהערה."],["2","353","ראה ירושלמי עירובין פ\"א ה\"י בקרבן העדה ד\"ה וכמה. תוספת נדרים ח, א. – לקוטי שיחות ח\"ב ע' 328 הערה 15."],["3","354","אגה\"ק סימן כג (קלו, ב). וראה ספר השיחות ה'תש\"ד ע' 97 ואילך:\nדאָס צווייטע מאָל ווען הוד כ\"ק אאמו\"ר הרה\"ק האָט מיט מיר געלערנט דעם תניא איז צוקומענדיק צום מאמר (כ\"ג) פון אגה\"ק, עשרה שיושבין ועוסקין בתורה, וואָס ער איז מבאר דאָרטן דעם חילוק פון השראת השכינה ביז קביעת שכר דיחיד, און רעדט דאָרט וועגן די מעלת הנשמות אויף מלאכים און פירט אויס, כמו ששמעתי מרבותי כי אילו נמצא מלאך אחד וכו' תפול עליו אימתה ופחד וכו' משכינתא דשריא עלייהו, האָט הוד כ\"ק אאמו\"ר הרה\"ק גערעדט מכח דעם לשון \"ששמעתי מרבותי\", וואָס פריער אין תניא (פל\"ה) זאָגט ער דעם לשון: ששמעתי ממורי און דאָ זאָגט ער ששמעתי מרבותי, האט ער אויף דעם געזאָגט, ששמעתי ממורי מיינט ער הוד כ\"ק הרב המגיד ממעזריטש און שמעתי מרבותי מיינט, מורנו הבעש\"ט און הרה\"מ ממעזריטש.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט דאַן געזאָגט, אַז דאָס זיינען פון די הלכות וואָס מען לערנט אין ג\"ע וועגן די מעלת הנשמות אויף מלאכים ווי זיי ווערן נתבטל פון דעם אור הוי' דשכינתא שרי' במעמד עשרה מישראל, הגם זיי רעדן ניט אין דברי תורה און ער האָט מיר דערציילט אַכט סיפּורים בהנוגע צו די הלכות וואָס מען לערנט אין ג\"ע און האָט מסיים געווען:\nאון דאָס איז אַלץ אין תניא אַ הקדמה אויף דעם, צו מאַכן אַ קביעות בכל יום צו לערנען עין יעקב, וואָס ער זאָגט אויף דעם, שרוב הסודות גנוזין בה ומכפּרת עוונותיו של אדם*.\nוראה גם שיחת ש\"פ נצבים תשכ\"ה. אור לי\"ד כסלו תשל\"ט בתחלתו.\n-----שולי הגליון-----\n*) <i>ראה בשיחת יום שש\"פ שם אות א</i>."]]],[300010696,"קעג\n\n<b>דיבור</b>\n<b>כל</b> הגה היוצא מפי אחד מישראל, בין איש בין אשה, בין זקן בין צעיר, בין גדול בידיעת התורה ובין עני בדעת ובור, הנה אם הוא לשם ה' בהנוגע לחזוק היהדות, הרבצת התורה ואהבת ישראל הוא יקר וחביב לצור עולמים<sup data-n=\"1\">355</sup>.",[["1","355","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ה ע' תל."]]],[300010697,"קעד\n\n<b>הדלקת המנורה</b>\n<b>כי</b> התורה הוא נצחי' וגם עתה יש בחי' הדלקת נרות המנורה ברוחני' כידוע בשם הבעש\"ט נבג\"מ<sup data-n=\"1\">356</sup>.",[["1","356","פלח הרמון על ספר בראשית קא, סע\"ג ואילך."]]],[300010698,"קעה\n\n<b>הוכח תוכיח</b>\n<b>תורת</b> הבעש\"ט האָט אונז געלערנט דעם ענין פון הוכחה, אַז אַלע חסרונות זאָל מען זען אין זיך. אַז מען זעט אין יענעם אַ חסרון שפּיגלט זיך אָפּ אַליין. מען זעט אַמאָל אין שפּיגל אַ חי' רעה און דאָס זעט אויף יענעם אַ חסרון<sup data-n=\"1\">357</sup>.",[["1","357","ספר השיחות תרפ\"ט ע' 62. וש\"נ."]]],[300010699,"קעו\n\n<b>תורתו</b> של הבעל שם טוב<sup data-n=\"1\">358</sup>, שכאשר אדם רואה רע בזולתו, הרי זו הוכחה ש(דוגמת) אותו הרע נמצא בו בעצמו<sup data-n=\"2\">359</sup>. וכמו אדם המביט בראי – \"אם פניו נקיים, אינו רואה במראה שום דופי\"<sup data-n=\"3\">360</sup>, אבל אם הוא רואה לכלוך וכתם בראי, אין זה אלא משום ש\"פניו מטונפין\"<sup data-n=\"4\">361</sup>.",[["1","358","מאור עינים ר\"פ חקת. וראה גם תולדות יעקב יוסף ס\"פ תרומה. ובכ\"מ. וראה גם ספר השיחות קייץ ה'ש\"ת ע' 83. תש\"ח ע' 185."],["2","359","ראה <i>עד\"ז</i> לקו\"ת בהעלותך לג, סע\"א."],["3","360","שלכן \"הצדיק הגמור שאין רע בקרבו אין רואה שום רע על שום אדם\" (מאור עינים שם)."],["4","361","לקוטי שיחות ח\"י ע' 24. וממשיך שם: ולכאורה: מהו ההכרח שראיית הרע בזולתו הוא בבחי' \"דמות\" ו\"מראה\" של הרע שברואה – למה לא תתכן מציאות כזו שבאמת ישנו הרע הנראה רק בחבירו והוא עצמו מושלל מזה?\nוהביאור בזה<sup data-n=\"5\">1</sup>: כל מאורע שבעולם הוא בהשגחה פרטית. וכן גם במאורע זה (שהוא רואה רע בזולתו)\nאין זה במקרה ח\"ו, אלא דבר שהזמינו לו <i>מלמעלה</i>; ומכיון שלא ברא הקב\"ה בעולמו דבר אחד לבטלה<sup data-n=\"6\">2</sup>, הרי אי-אפשר לומר שמלמעלה יביאוהו לידי ראיית רע במישהו <i>לשווא</i> – אלא שבודאי יש בזה הוראה<sup data-n=\"7\">3</sup> והודעה והיא – שהרע נמצא ברואה עצמו ועליו לתקנו.\nוהטעם למה צ\"ל ההוראה באופן מסובב כזה – להיוודע מהרע <i>שלו</i> ע\"י אמצעות חבירו ולא באופן ישיר? – הרי זה משום ש\"על כל פשעים תכסה אהבה\"<sup data-n=\"8\">4</sup> (ואהבת עצמו מכ\"ש), ו\"כל הנגעים אדם רואה חוץ מנגעי עצמו\"<sup data-n=\"9\">5</sup>, ולכן הדרך להביא את האדם לידיעת חסרונות שלו, הוא ע\"י שיזמינו לו לראותם בזולתו<sup data-n=\"10\">6</sup>, והזדמנות זו, בעת שהוא \"רואה\" (בחבירו) פחיתות החסרונות והרע, מעוררת בו התבוננות במצבו הוא; וכאשר יתבונן היטב במצבו \"אליבא דנפשי'\", יבוא להכרה שהחסרונות שראה הם באמת חסרונות <i>שלו</i> – אשר \"כל הנגעים (שה)אדם רואה (ב)חוץ (הרי זה תוצאה) מנגעי עצמו\". עיי\"ש בארוכה. וראה גם לקוטי שיחות ח\"ב ע' 351. ח\"ז ע' 18 הערה 33.\n-----שולי הגליון-----"],["5","1","<i>ראה גם ספר השיחות קייץ ה'ש\"ת ע' 83</i>."],["6","2","<i>שבת עז</i>,<i> ב</i>."],["7","3","<i>וכתורת הבעש\"ט, שכל מה שאדם רואה או שומע – הוראה היא בעבודתו (\"היום יום\" ט אייר [וראה לקמן סימן רכג ואילך])</i>."],["8","4","<i>משלי יו\"ד</i>,<i> יב</i>."],["9","5","<i>נגעים פ\"ב מ\"ה</i>.<i> והכוונה </i>כאן<i> היא – כפירוש המאירי לאבות (פ\"א מ\"ז – הובא גם במדר\"ש שם פ\"ג</i>.<i> וכ\"ה בד\"ה איש על דגלו ש\"ת פ\"ג</i>.<i> ואהבת תש\"א פט\"ו) – בנוגע ל\"נגעים\" רוחניים, ש\"נגעי </i>עצמו<i>\" אינו רואה אותם ל\"נגעים\" וחסרונות כלל</i>."],["10","6","וע\"ד<i> המבואר במק\"א (ראה לקוטי שיחות ח\"ד ע' 1207</i>. וש\"נ<i>)</i>,<i> שכשרוצים שאדם יפסוק הדין על עצמו</i>,<i> עושים זה בתחבולה – ע\"י שפוסק הדין על זולתו [וראה לעיל סימן קיב]</i>."]]],[300010700,"קעז\n\n<b>אין</b> מדרש<sup data-n=\"1\">362</sup> שטייט געשריבן, האָט דער בעש\"ט געזאָגט, אַז ג-ט ב\"ה האָט געזאָגט צו משה רבינו אַז ער – משה רבינו – זאָל אים מוסר'ן, פאַרוואָס מוסר'ט איר די אידן פאַר דעם וואָס זיי דינען ניט אַזוי גוט דעם בורא עולם ב\"ה, זייט מוכיח כביכול דעם אדון עולם ב\"ה פאַרוואָס ער האָט ניט רחמנות אויף זיינע קינדערלעך<sup data-n=\"2\">363</sup>.",[["1","362","ראה דברים רבה פ\"א, ב. ילקוט שמעוני דברים רמז תשצה."],["2","363","ספר השיחות תש\"א ע' 158. לקוטי דיבורים ח\"ג שפט, ב. ושם לפנ\"ז: מיט הייסע טרערן און מיט גרויס תחנונים בעט זיך מורנו הבעש\"ט באַ איינעם פון די מגידים, וועלכער האָט שטאַרק געמוסרט דעם עולם און האָט זיי דערציילט וועגן פאַרשידענע שטראָף מיט וועלכע ג-ט ב\"ה וועט זיי שטראָפן: אין מדרש [ההמשך בפנים]. – הסיפור בארוכה – ראה לקוטי דיבורים ח\"ב ריח, א ואילך. ספר השיחות תרצ\"ו ע' 34 ואילך."]]],[300010701,"קעח\n\n<b>הנחות העולם</b>\n<b>מי</b> שנמשך אחרי הנחות העולם הנה עיוות ועיקום זה גורם כמה מכשולים וצריך לתשובה שהיא חרטה על העבר וקבלה טובה על להבא, ומורנו הבעש\"ט נ\"ע מפרש את המכשולים שהם ענינים בלתי מסודרים בעבודה וזה בא מהעון שהוא העיוות והעיקום בטעותי העבודה ולתקן זה הוא ע\"י התשובה עילאה שהוא לתקן ולסדר נפשו<sup data-n=\"1\">364</sup>.",[["1","364","ספר המאמרים תש\"ה ע' 30."]]],[300010702,"קעט\n\n<b>השגחה פרטית</b>\n<b>וכידוע</b> בענין השגחה פרטית שמבאר מורנו הבעש\"ט נ\"ע<sup data-n=\"1\">365</sup> דלא זו לבד דכל פרטי תנועות הנבראים למיניהם היא בהשגחה פרטית מהבורא ית', והשגחה פרטית הלזו היא חיות הנברא וקיומו, אלא דעוד זאת דתנועה פרטית דנברא פרטי הרי יש לו יחס כללי לכללות כונת הבריאה<sup data-n=\"2\">366</sup>, ועל דרך דוגמא הנה תנועת אחד הדשאים הצומח בעמקי יער או באחד ההרים הגבוהים או בעמקים היותר עמוקים אשר לא עבר שם איש, הנה לא זו בלבד דתנועת הדשא ההוא לימינו ולשמאלו לפנים ולאחור בכל משך ימי חייו הוא עפ\"י השגחה פרטית אשר הוא ית' גזר אומר אשר דשא פרטי זה חי' יחי' חדשים ימים ושעות קצובות, ובמשך זה יסוב ויכוף לימינו ושמאלו לפניו ולאחוריו במספר כזה וכזה, אלא עוד זאת דתנועת הדשא הפרטי הלזה יש לו יחס כללי לכללות כונת הבריאה, דבצרוף ואחוד כל הפעולות הפרטים של הרבוי רבבות פרטים אין מספר שישנם בכל האלפים ורבבות מינים שישנם בהד' חלוקות דדצח\"מ הנה נשלמה כונה העליונה בסוד הבריאה כולה, וא\"כ הנה לא זו בלבד דתנועה אחת של דשא פרטי היא באה בהשגחה פרטית, אלא עוד זאת דגם תנועה אחת של דשא פרטי משלים הכונה העליונה בענין הבריאה<sup data-n=\"3\">367</sup>.",[["1","365","ע\"ד שיטת הבעש\"ט בהשגח\"פ בארוכה (בסימן זה והבאים לאחריו) – ראה רשימה \"השגחה פרטית\" – אגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"א ע' קיח ואילך. לקוטי שיחות ח\"ח ע' 277 ואילך. וראה אגרות-קודש הנ\"ל ח\"ב ע' שצד. לקוטי שיחות ח\"ד ע' 1253 ואילך. ח\"ז ע' 63. ח\"ט ע' 181. חי\"ג ע' 5-164. חי\"ח ע' 167. ע' 199. חכ\"ג ע' 157. ח\"ל ע' 149. \"רשימות\" חוברת מד. ועוד."],["2","366","ראה גם ספר המאמרים תרפ\"ו ע' קנו ואילך: דזהו יסוד תורת רבינו הבעש\"ט ז\"ל . . ובענין השגחה פרטית דעתו הק' דלבד זאת דכל דבר שנמצא בעולם הוא בהשגחה פרטי פרטית, הנה עוד זאת שההשגחה פרטי' היא גם בהסבות וסבות דסבות, וכמו עד\"מ עלה הנובלת מן האילן ומתגלגלת ממקום למקום הוא בהשגחה פרטית, וגם אפי' אופן גלגולה אם ע\"י רוח או בכח אדם, הוא ג\"כ בדין ומשפט דהשגחה פרטית. ויסוד דבר זה הוא כדאיתא בגמ' חולין דס\"ג א' ר' יוחנן כי הוי חזי שלך אמר משפטיך תהום רבה . . ופרש\"י . . משפטיך אף בתהום רבה, שזמנתה שלך לשפוט ולעשות נקמתך בדגת הים להמית המזומנים למות, עכ\"ל. הרי שההשגחה פרטית הוא בכל דבר בהפרטי פרטים שלו. ומזה הביא רבינו הזקן נ\"ע ראי' ותשובה לאותן שהתוכחו עמו בדברי תורת רבינו הבעש\"ט, וידוע דרבינו הגדול מסר נפשו על תורת רבינו הבעש\"ט, ובענין זה דהשגחה פרטי' שמנגדי תורת הבעש\"ט אומרים שהשגחה פרטית הוא רק על מין האדם, הוכיח להם רבינו הגדול בראי' טבעית שהרי בדגת הים יש דין ומשפט ומזמין את השלך לשפוט ולעשות נקמתו באותן המזומנים כו'. ובמדרש וישלח דגם צפור מבלעדי שמיא לא מתצדי, דבת קול יוצא ומכריז דימוס או ספקולי כו'. וראה גם אוה\"ת (יהל אור) לתהלים ע' קלב. ספר המאמרים תרע\"ח ע' תיג ואילך. ד\"ה מים רבים תשי\"ז פ\"ג (ספר המאמרים מלוקט ח\"א ע' נד. בהוצאה החדשה – ע' שכג). שיחת ש\"פ ויצא תשי\"ב (תורת מנחם – התוועדויות ח\"ד ע' 157 ואילך)."],["3","367","ד\"ה על כן יאמרו המשלים תרצ\"ו (ספר המאמרים קונטרסים ח\"ב שע, ב. ספר המאמרים תרצ\"ו ע' 120. חלקו הועתק ב\"היום יום\" כח חשון). וממשיך שם:\nאשר מזה יוצא לנו ענין עמוק בעבודה, דכאשר יתבונן האדם ומה אם דשא אחד פרטי הרי גם מספר תנועותיו ואופניו הוא בא בהשגחה פרטית ונוגע להשלמת כונת הבריאה, הנה האדם הרי ודאי שהוא מושגח בהשגחה פרטית בכל פרטי פרטיות עניני צרכיו, אשר ע\"כ הנה עיקר השתדלותו צריכה להיות בזה שלא יקלקל, והוא שלא יגרום מניעה ועכוב בההשפעה העליונה, שהוא ית' זן ומפרנס לכל, וישים לבו ודעתו על טיב טהרת הכלי, והיינו דכלי פרנסתו יהי' עפ\"י התורה טהורה מכל סיג פסולת דאונאה וכו', והנהגתו תהי' עפ\"י התורה והמצות בשמירת תפלה בצבור וקביעת עתים לתורה, וקיום המצות מעשיות בחיות פנימי, שבזה ישלים כונת הבריאה.\nראה גם – בשם הבעש\"ט – לקוטי דיבורים ח\"ד תקצו, ב. ספר השיחות תרפ\"ז ע' 194. ועוד."]]],[300010703,"קפ\n\n<b>כך</b> אנו לומדים בתורתו של מורנו הבעש\"ט נ\"ע דכל ברואי הדצח\"ם כולם מושגחים מאתו ית' בכל פרטי פרטי' עניניהם כל אחד לפי מעלתו. והקב\"ה מסבב כמה סבות ועילות בכדי לפעול איזה פעולה הנוגע להנברא. והכל הוא בהשגחה פרטי פרטי' הנראה במוחש ממש, דבאמצע הקיץ ביום בהיר אשר השמש זורח בכל תקפו לפתע פתאום מתעורר רוח חזק המנענע עלי האילן ונתלשים כמה עלין ומפרק קש הגגות וקשי התבן המתגוללים ע\"פ הארץ מגביהם ומטלטלם ממקום למקום. וכעבור איזה רגעים נשקט הרוח והי' כלא הי'. דכונת הרוח חזק הי' עילה וסבה מאתו ית' לפעול תלישת עלי האילן ופריקת איזה קשי תבן מהגג ולטלטל העלים הנתלשים והקש המתגלגל לאותו המקום כפי גזרת ההשגחה העליונה ית' בשביל כונה אלקית. והיינו שגם טלטול העלים או קשי התבן המתגוללים ברחוב או בשדה הוא בהשגחה פרטית<sup data-n=\"1\">368</sup>. ומכש\"כ במין המדבר בכלל ובישראל עם קרובו ית' בפרט דהשגחה העליונה ית' בהם הוא בפרטי פרטיות כל הענינים<sup data-n=\"2\">369</sup>.",[["1","368","ראה גם – בשם הבעש\"ט – ספר המאמרים תרפ\"ח ס\"ע ה ואילך. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ו ע' לג. ח\"ט ע' ערב. ע' שי. ע' תיד. חי\"ד ע' תלט (הועתק באגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"ה ס\"ע סה ואילך. והובא בשיחת ש\"פ ויצא תשי\"ב (תורת מנחם – התוועדויות ח\"ד ע' 157)). לקוטי דיבורים ח\"ג תקיב, א. ספר השיחות תרפ\"ז ע' 126. ע' 134. ע' 193. ע' 194. תש\"ו ע' 19). ובשיחת יום שמחת תורה ה'שי\"ת ס\"א (ספר השיחות ה'שי\"ת ע' 378): דער בעש\"ט איז מבאר דעם ענין פון השגחה פּרטית, אַז אין מיטען העלן טאָג ווערט אַ ווינט און עס טראָגט איבער אַ בלעטעלע פון אַ בוים פון איין אָרט אויף אַ צווייטען, ביז עס קומט צו אַ פּלאַץ און דאָרט בלייבט עס ליגען, וואָס דאָס איז דאָך אַלעס בהשגחה פּרטית, צו דער רגע, ובאותו מקום ובאותו האיש."],["2","369","ד\"ה הטה אלקי תרצ\"ד (ספר המאמרים קונטרסים ח\"ב רעט, א)."]]],[300010704,"קפא\n\n<b>דער</b> בעש\"ט נ\"ע גיט צו פאַרשטיין אַז אַלע נבראים יעדער איינער האָט אַ בעזונדער באַטרעף למעלה. יעדער באַשעפעניש פאַרנעמט גאָר אַ באַזונדער אָרט לויט זיין מהות. עס איז ניט גלייך אַ דומם צו אַ צומח, אַ צומח צו אַ חי און אַ חי צו אַ מדבר, און מדבר גופא זיינען ישראל עם קרובו. נאָר די השגחה פרטית איז אפילו אויף דער גרעסטער קלייניקייט, און איז מסיים אַז די השגחה פרטית וואָס על עם קרובו ית' דאָס קען מען גאָרניט אויסמאָלן. והדברים קל וחומר ומה דבר קטן כזה אם העלה הנתלש או הקש יהי' במקום זה או יטולטל למקום אחר הוא בהשגחה פּרטית ומכל שכן דאָס וואָס עס איז נוגע אַ אידן הוא בהשגחה פּרטית וואָס מען קען דאָס ניט פאַרשטיין<sup data-n=\"1\">370</sup>.",[["1","370","לקוטי דיבורים ח\"א פד, א ואילך."]]],[300010705,"קפב\n\n<b>אַלעמען</b> איז גוט באַוואוסט דער ענין פון השגחה פּרטית, ווי דער בעש\"ט איז מבאר, אַז אפילו אַ שטרויעלע און אַ אָפּגעריסענע בלעטעלע וואָס וואַלגערט זיך אין גאַס איז פאַראַן אַ דין ומשפּט וויפיל מאָל זיי זאָלן זיך אומדרעהען און וואו, אין וואָסערע ערטער זיי זאָלען זיך וואַלגערען.\nדער בעש\"ט נ\"ע זאָגט אַז הקב\"ה איז מסבב כמה סבות מסבות שונות בכדי דורכפירן אַ השגחה פּרטית פון אַ קליינעם נברא ויצור, אַז בכדי אַז אַן אַראָפּגעפאַלענע בלעטל פון אַ בוים וואָס וואַלגערט זיך נאָך פון פאַראַיאָרן ערגעץ וואו אין אַ הינטער הויף, אָדער אַ שטרויעלע פון אַ זאַנג מיט וועלכער מען האָט מיט אייניגע יאָר פריער צוגעדעקט אַ דאַך אין אַ דאָרף זאָלן זיך רירן פון זייערע ערטער און אַריבער אין אַן אַנדער אָרט איז צוליב דעם ברעכט אויס אין אַ הייסן זונענשיינענדיגן טאָג אַ שטורם ווינט וואָס קערט הימל און ערד, און יעמאָלט ווערט דורכגעפירט די השגחה פּרטית אויף דעם אַראָפּגעפאַלענע בלעטל און דער אַלטער שטרויעלע<sup data-n=\"1\">371</sup>.",[["1","371","לקוטי דיבורים ח\"א פג, ב."]]],[300010706,"קפג\n\n<b>אַ</b> איד ווייס אַז יעדער טראָט פון אַ נברא איז בהשגחה פּרטית<sup data-n=\"1\">372</sup>, ווי מורנו הבעש\"ט האָט געזאָגט אַז השי\"ת איז משיב רוח חזק בכדי אַ שטרויעלע וואָס וואַלגערט זיך אויפן מאַרק זאָל אַריבערגעטראָגן ווערן פון איין אָרט אויף אַ צווייטן, וואָרום די שטרויעלע וואָס וואַלגערט זיך אין גאַס איז צוליב אַ כוונה פּרטית. די בלאָטע און די שטרויעלע וואָס וואַלגערט זיך אין דער בלאָטע זיינען אַ טייל פון הנהגת העולם בהשגחה פּרטית.\nאָט דאָס איז דער ענין פון ג-טלעכקייט, אַז חכמה דאצילות, וואָס לית מחשבה תפיסא אין מהות פון אַ ספירה עליונה בכלל, און אין מהות פון ספירות דאצילות בפרט און אין מהות פון חכמה דאצילות בפרטי פּרטיות, איז מהות אלקות ממש איז ניט תופס מקום אין עצמות און אַלץ איז בהשגחה פרטית, ניט נאָר אַ נשמה און אַ ספירה שלמעלה נאָר אויך דער אַריבער פון איין אָרט אויפן צווייטן פון אַ שטרויעלע איז השגחה פרטית, וואָס צוליב דעם שינוי מקום פון דער שטרויעלע שיקט השי\"ת אַ רוח סערה און איז מסבב כמה סיבות גלויות ונעלמות<sup data-n=\"2\">373</sup>.",[["1","372","ראה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ט ס\"ע שנא ואילך: וכידוע ביאור רבינו אדמו\"ר הזקן על מאמר רבינו הבעש\"ט, אז יעדער הילוך פון א אידן איז בהשגחה פרטית מכניס זיין אור תורה ומצוה אין וועלט, וכתוב אצלי ביאור ארוך שזכיתי לשמוע מהוד כ\"ק אאמו\"ר בענין זה בחוהמ\"ס תרנ\"ו."],["2","373","ספר השיחות קייץ ה'ש\"ת ע' 125."]]],[300010707,"קפד\n\n<b>מורנו</b> הבעל שם טוב נ\"ע זאָגט, אַז יעדער איד מוז קלאָר וויסן אַז אַלעס וואָס מיט דעם מענטשן פּאַסירט – פון דער קלענסטער קלייניגקייט ביז דער גאָר גרעסטער זאַך – איז דאָס ע\"פּ השגחה פּרטית פון השי\"ת, וואָס דאָס איז אַלץ צוליב אַ כוונה אין דער שליחות פון דעם מענטשן וואָס צוליב דעם האט אים השי\"ת באַשאַפן<sup data-n=\"1\">374</sup>.",[["1","374","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ו ע' שב. וממשיך שם:\nדי השגחה העליונה בריינגט דעם מענשען אין אַ געוויסן אָרט, אַ שטאָט אָדער אַ שטעדטעל. דער מענש מיט זיין שכל אנושי מיינט, אַז ער איז געקומען אַהין צוליב געשעפטליכע זאַכען, אָבער באמת האָט איהם די השגחה העליונה געבראַכט אַהין צוליב אַ כוונה רוחנית, אַז ער זאָל דאָרטען דאַוונען איינע פון די תפלות, שחרית, מנחה וערבית, אָדער מאַכען אַ ברכה, וואָס אויף דעם דאַווענען, אָדער אויף דער ברכה האָט דער אָרט געוואַרט הונדערטער יאָהרען, אַז אין יענעם און יענעם טאָג וועט קומען אַ איד און וועט דאָרטען דאַוונען אָדער אַ ברכה מאַכען.\nאַמאָל טרעפט אַז אַ מענש פאָהרט אַ גרויסע שטרעקע צוליב געשעפט – אַזוי מיינט ער – און ער קומט אַהין און האָט גאָרנישט אויפגעטאָן, און צופעליג טרעפט ער זיך מיט נאָך אַ אידען און מען רעדט זיך פאַנאַנדער, און איינער פון זיי דערמאָהנט זיך אויף דער פרומער הנהגה פון זיינע עלטערען און עס געהט איהם דורך אַ הרהור תשובה רעיון, און באמת איז דאָס גאָר געווען די כוונה פון זיין נסיעה בכדי ער זאָל אַליין דערוועקט ווערען אָדער בריינגען דעם צווייטן צו אַ הרהור תשובה, און אָנהויבן פירן אַ תורה ומצות לעבען.\nדער מענש, וועלכער קוקט זיך צו צו דער השגחה פּרטית ווי השי\"ת פיהרט מיט איהם אין אַלע זיינע זאַכען, דערזעהן געטליכקייט אויף שריט און טריט."]]],[300010708,"קפה\n\n<b>די</b> שיטה פון מורנו הבעש\"ט אין השגחה פּרטית איז, אַז דער אויבערשטער מאַכט מען זאָל זיך טרעפן אין דער צייט מיט דעם מענטשן איז עס צוליב אַ כוונה. יעדערער דאַרף זיין אַ מלמד<sup data-n=\"1\">375</sup> אויף לערנען זיך פון אים. און אויב מען גלויבט ניט אין דעם איז מען אַ כופר ר\"ל<sup data-n=\"2\">376</sup>.",[["1","375","ראה לעיל סימן קיד-קטו."],["2","376","לקוטי דיבורים ח\"ד תרז, א. ספר השיחות תש\"ד ע' 123."]]],[300010709,"קפו\n\n<b>דער</b> בעש\"ט נ\"ע האָט געזאָגט, אַז אפילו אַ בלעטל פון אַ בוים ווען דער ווינט קערט איר איבער איז דאָס בהשגחה פּרטית, צוליב דעם אויבערשטנ'ס אַ געוויסע כוונה<sup data-n=\"1\">377</sup>.\nעס שטייט<sup data-n=\"2\">378</sup> כי כארבע רוחות השמים פרשתי אתכם, אידן זיינען צושפּרייט און צוזייט אויף דעם גאַנצן ערד-קוגל וואָס דאָס איז צוליב אַ כוונה פּנימית און דאָס איז דער מיין פון גוי אחד בארץ<sup data-n=\"3\">379</sup>, אַז אַלע אידן זיינען איין זאַך און מוזן אַרויסהעלפן איינער דעם צווייטן אין אַ ביטערע צייט<sup data-n=\"4\">380</sup>.",[["1","377","ראה ג\"כ ד\"ה ע\"כ יאמרו המושלים תרצ\"ו. \"היום יום\" כח חשון. לעיל סימן קעט."],["2","378","זכרי' ב, יא."],["3","379","שמואל-ב ז, כג. דברי הימים-א יז, כא."],["4","380","ספר השיחות קייץ ה'ש\"ת ע' 3."]]],[300010710,"קפז\n\n<b>דער</b> בעש\"ט – זכותו יגן עלינו – זאָגט, אַז אַ באַגעגעניש צווישן מענטשן איז דאָס על פּי סדר ההשגחה העליונה, וואָס דער מיין פון דער באַגעגעניש מוז אויסגענוצט ווערן אין אַ תורה ומצות זאַך. דאָס מיינט אַז די בעגעגעניש פון מענטשן איז אַ געטליכער וואונק אַז יעדער פון די צוויי מענטשן וואָס האָבן זיך באַגעגענט מוזן עפּעס לערנען איינער פון צווייטן און מוזן ווירקן איינער אויפן צווייטן אויך אין אַ תורה ומצות ענין, ניט נאָר אין צדקה וגמילות חסדים<sup data-n=\"1\">381</sup>.",[["1","381","ספר המאמרים תש\"ט ע' 45. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ח ע' ק ואילך. וממשיך שם: אָט אַזוי לערנט אונז אונזער ערשטער רבי, דער בעל שם טוב – נשמתו עדן – און אַזוי לערנען אונז אַלע איבעריגע רביים אין זייערע דברי חסידות, אַז מיר דאַרפן און מוזן קוקן אויף אַלע – אַפילו וואָס מענטשן רופן קליינליכע – פּאַסירונגען, אַז זיי זיינען באמת אַ הוראה מן השמים – אָנדייטונגען פון הימל – אויף געוויסע זאַכן וואָס די השגחה העליונה – השם יתברך – האָט אַרויפגעלעגט אויף די אידן וועלכע באַגעגענען זיך אַז זיי דאַרפן דאָס דורכפירן."]]],[300010711,"קפח\n\n<b>השתלשלות העולמות</b>\n<b>יש</b> פלוגתא בין הפילוסופים ובין המקובלים, הפילוסופים אומרים שהתהוות עולמות הוא בדרך עילה ועלול . . אבל המקובלים אומרים שאין שייך לומר עילה ועלול אלא במשפיע ומקבל שהמשפיע בעצמו הוא בע\"ג . . אך הם אומרים שהשתלשלות העולמות בדרך אור וזיו . . אבל הבעש\"ט והמגיד אומרים שאין שייך לומר בדרך אור וזיו כי א\"כ הוא מוכרח שעולם הוא קדמון כו' ולא הי' התחדשות העולמות, אך השתלשלות העולמות הוא כמו<sup data-n=\"1\">382</sup> שהנשמה ממלא את הגוף כך הקב\"ה כו'<sup data-n=\"2\">383</sup>.",[["1","382","ראה ברכות י, א. ויק\"ר ספ\"ד."],["2","383","מאמרי אדמו\"ר הזקן כתובים ח\"א ע' צא ואילך."]]],[300010712,"קפט\n\n<b>התייעצות</b>\n<b>וידוע</b> משם כ\"ק אבותינו הק' זצוקללה\"ה וכמדומה שהוא מהבעש\"ט ז\"ל אשר ג' אנשים<sup data-n=\"1\">384</sup> יש להם כח גדול<sup data-n=\"2\">385</sup>.",[["1","384","ראה גם אגרות-קודש אדמו\"ר הצ\"צ ח\"ב ע' קב."],["2","385","אגרות-קודש אדמו\"ר מהורש\"ב ח\"ג ע' קצד. ושם לפנ\"ז: ובפרט כאשר כן הסכימו ידידינו אהובינו יחיו [ההמשך בפנים. וממשיך שם:] וכאשר הסכימו כן בטח יהי' מזה תועלת טוב."]]],[300010713,"קצ\n\n<b>זכרון</b>\n<b>הוד</b> כ\"ק רבינו הזקן האָט מקבל געווען מרבו המגיד ממעזריטש, וואָס ער האָט מקבל געווען מרבו מורנו הבעש\"ט דעם וואָרט: <i>וואָס געדענקסטו</i>?<sup data-n=\"1\">386</sup>.",[["1","386","ספר השיחות תש\"ט ע' 333. וממשיך שם: אָט דער וואָרט – וואָס געדענקסטו – האָט מחי' געווען מיט אַ חיות פון תחיית המתים די חסידים לדורותם. תחיית המתים הייסט חיים ארוכים, חיים אמיתיים, מיתה איז הפסק, און חיים ארוכים איז חיים בלי הפסק, וואָס דאָס איז חיים אמיתיים, עס איז ניטאָ דער העדר החיים, עס איז מער ווי לעבן. אין עבודה איז דאָס, אַז ניט נאָר וואָס מען לעבט אַליין, נאָר מען באַלעבט אויך אַנדערע.\nובספר השיחות שם ע' 336: בעת די ערשטע יאָרצייט פון בעש\"ט אום שבועות, ווען דעם בעש\"ט'ס זון הרה\"ק ר' צבי האָט זיך אויפגעשטעלט און געזאָגט אַז די גאַנצע פּמליא של מעלה האָט זיך איבערגעטראָגען צום מעזריטשער, האָט דאַן דער מעזריטשער מגיד אויך געפרעגט ביי אַלע זיינע תלמידים: וואָס געדענקסטו?"]]],[300010714,"קצא\n\n<b>זמני ומועדי השנה</b>\n<b>אלול – תשרי</b>\n<b>דער</b> מאמר הידוע וואָס רבינו נ\"ע האָט געזאָגט בשם הבעש\"ט נ\"ע:\nבחדש תשרי גיט השי\"ת מזונותיו של אדם בהקפה און אין חדש אלול בעדאַרף מען מאַכען דעם חשבון און באַצאָלען דאָס וואָס קומט, די צאָלונג איז מיט תשובה, ווען השי\"ת זעט אַז מען צאָלט און מען וויל צאָלען שענקט ער דעם רעשט חוב וואָס דאָס זיינען די ימי הסליחות און דורך דער תשובה פון ימי הסליחות ווערט מען אַ בטוח אַז ר\"ה גיט השי\"ת אַ קצבה אויף אַ שנה טובה ווייטער בהקפה<sup data-n=\"1\">387</sup>.",[["1","387","ספר המאמרים אידיש ע' 78."]]],[300010715,"קצב\n\n<b>ראש השנה</b>\n<b>אמר</b> רבינו מה ששמע מהרב המגיד ממעזריטש, מה שאמר הבעל שם טוב נ\"ע לנכדו הרב דגל מחנה אפרים הסדר דתקיעת שופר למעלה, אשר הא-ל הגדול השם הנכבד והנורא יושב על כסא רם ונשא שהיא כסא דין, ואברהם אבינו בגודל אהבתו מבקש ומתחנן לפני א-ל רם ונשא אשר יעמוד מכסא דין וישב על כסא רחמים, וזהו דאיתא בזוהר<sup data-n=\"1\">388</sup> אברהם אתקין לכורסייא שהוא המתקן את הכסא רחמים ויצחק אבינו מתעורר בהתעוררות גדולה ומזכיר את עקדתו ומבקש על זרעו והתעוררות מסיר כל המסכים ופרסאות, ויעקב אבינו מעורר רחמים רבים על בנ\"י ומשה רבינו עומד בתפלה ותחנונים, והרועים עומדים על ידו ומתאמצים בתפלה ומלאכי מעלה מליצי יושר מביאים זכותיהם של ישראל כו' ולעומתם ישנם התובעים כו' וסופרים ומונים את כל מחשבותיו דיבוריו ומעשיו הטובים והלא טובים של כל אחד ואחד בפרט, והאבות ומרע\"ה ממליצים טוב על כאו\"א, דזה סדר התקיעות תקיעה שברים תרועה דתקיעה דא אברהם, שברים דא יצחק, תרועה דא יעקב וכאשר האדם צועק אבא ומלכי הצילני ורחמני הנה נותן כח במדה\"ר להתגבר<sup data-n=\"2\">389</sup>.",[["1","388","ח\"ג צט, ב. וראה ביאורי הזוהר לאדמו\"ר הצמח צדק ח\"א ע' שצו ואילך. ח\"ב ע' תתקנו ואילך."],["2","389","ספר המאמרים תרצ\"ט ע' 13."]]],[300010716,"קצג\n\n<b>ופי'</b> מורנו הבעל שם טוב נ\"ע דההתעוררות הפּנימית בהצעקה דתקיעת שופר שצועקים אבא אבא לא תהי' על העקתא שהוא הצער והמיצר מגודל היסורים שמהעבר כ\"א הצעקה בתחנון אבא הצילני אבא רחמני<sup data-n=\"1\">390</sup>.",[["1","390","ספר המאמרים תש\"ה ע' 1. ומוסיף שם: ועם היות שהקריאה באה מסיבת המיצר והדוחק דלכן הנה הקריאה לשם י\"ה הנה כאשר הקריאה היא בצעקת תחנונים הנה העני' של מעלה היא מהמרחב דשם י\"ה."]]],[300010717,"קצד\n\n<b>התקיעה</b> בשופר בחי' קול פשוט שהיא צעקה פשוטה מתוך ועומק לבבו על היותו נפרד מה' אחד כו', והוא בקרן בהמה ע\"ש אדם ובהמה תושיע ה'<sup data-n=\"1\">391</sup>, ונת' משל ע\"ז בשם הבעש\"ט ז\"ל, למלך שהי' לו בן יחיד מלומד היטב שהי' חביב אצלו כבבת עינו ממש ועלה בדעת האב ובנו שיסע למדינות אחרות ללמוד חכמות ולידע הנהגת בנ\"א אז נתן לו אביו המלך שרים ומשרתים והון רב שילך ויתור במדינות ואיי הים למען יגיע הבן למעלה יתירה יותר מכמו היותו אצל אביו בביתו ויהי ברבות הימים וכל אשר נתן לו אביו הלך על הוצאות הדרך מהצטרכות תפנוקיו שהי' מורגל והעיקר במה שהוסיף תאוה על תאותו בעניני' רבים שעלה לו זה להוצאה מרובה עד שמכר כל אשר לו, ובין כך הלך למדינה רחוקה עד שגם אביו לא נודע שם כלל, ובאמרו שהוא בן מלך פלוני מלבד שאינו מאמיני' לו לא נודע כלל שם אביו, וכאשר ראה שכלתה כל תרופות תעלות להחיות את נפשו בצר לו עלה בלבו לחזור למדינת אביו, אבל מחמת אריכות הזמן שכח גם לשון מדינתו, ובבואו למדינתו מה יכול לעשות מאחר שגם הלשון שכח, והתחיל לרמז להם שהוא בן מלכם והי' אצלם לשחוק היתכן שבן מלך אדיר כזה ילך קרוע ובלוי כ\"כ והכו אותו על קדקדו ונעשה מלא פצעים וחבורות ומכה טרי' עד שהגיע לחצר המלך והתחיל לרמז להם שהוא בן המלך ולא השגיחו עליו כלום עד שהתחיל לצעוק בקול גדול בכדי שיכיר המלך קולו, וכשהכיר המלך קולו אמר הלא זהו קול בני צועק מתוך דוחקו ונתעורר אצלו אהבת בנו וחבקו ונשקו כו', וכך יובן הנמשל למעלה שנש\"י נק' בנים למקום, שהגם שבן ואח אין לו<sup data-n=\"2\">392</sup> עכ\"ז חבבן וקראן בנים כמ\"ש<sup data-n=\"3\">393</sup> בני בכורי ישראל, וכתיב<sup data-n=\"4\">394</sup> בנים אתם לה' אלקיכם, והוריד הנשמה בגוף שזהו כמשל בן המלך שהלך בדרך רחוקה בכדי להתלמד היינו שע\"י מצות ומעש\"ט עי\"ז מתעלים הנשמות בעילוי יותר נעלה מכמו שהי' מקודם, ואמנם ע\"י אהבת הגוף ותאוות הממון ושארי תאוות האדם מתאווה להן, וע\"י היותו משוקע כ\"כ עי\"ז נתרחק מאד למקום שא\"י כלל שם אביו, וכמו שא' פרעה<sup data-n=\"5\">395</sup> מי הוי' אשר אשמע בקולו לא ידעתי את הוי', והכל נק' ע\"ש מצרים כמ\"ש במד\"ר<sup data-n=\"6\">396</sup>, וע\"י ריחוק זה שכח כל מה שהי' רגילה בהיותה למעלה שכחה לגמרי ונחסר אצלה הן ברוחניות כל מה שהי' וגם בגשמיות ה\"ה מחוסר וכמארז\"ל<sup data-n=\"7\">397</sup> הריעותי את מעשי וקפחתי את פרנסתי, ובאריכות הזמן שגולי' ומטולטולי' מתדלדלי' מכל וכל וכמ\"ש<sup data-n=\"8\">398</sup> וידל ישראל והיינו בין ברוחניות ובין בגשמי' וכנ\"ל במשל ששכח גם הלשון והיינו בנמשל ענין הרגילה בדביקו' אלקות, עד שהתחיל לשוב ולצעוק בקול פשוט שאביו יכירו בטביעת עין דקלא, וזהו התקיעה בקול שופר שהוא בחי' צעקה פנימי' מעומקא דלבא איך שהוא מתחרט על העבר ומקבל ע\"ע להבא לשמוע בקול אביו וע\"י צעקה זו מתעורר ממה\"מ הקב\"ה ומראה חיבתו לבנו יחידו ומוחל וסולח לו על העבר שז\"ע יוהכ\"פ יום מחילה וסליחה, עד שיום הראשון דחה\"ס הוא ראשון לחשבון עוונות כמארז\"ל<sup data-n=\"9\">399</sup> ע\"פ<sup data-n=\"10\">400</sup> ולקחתם לכם ביום הראשון, ומשל החיבוק ז\"ע וימינו תחבקני<sup data-n=\"11\">401</sup> דחגה\"ס הקפת הסכך דסוכה כו' כמ\"ש מזה במ\"א<sup data-n=\"12\">402</sup>.",[["1","391","תהלים לו, ז."],["2","392","קהלת ד, ח."],["3","393","שמות ד, כב."],["4","394","פ' ראה יד, א."],["5","395","שמות ה, ב."],["6","396","ס\"ר פט\"ז, ד."],["7","397","קידושין פב, ב."],["8","398","שופטים ו, ו."],["9","399","תנחומא אמור כב, יל\"ש אמור רמז תרנא."],["10","400","אמור כג, מ."],["11","401","שה\"ש ב, ו. ח, ג."],["12","402","המשך וככה תרל\"ז פרק ע. נתבאר בד\"ה יו\"ט של ר\"ה תשמ\"ב וד\"ה אדון עולם תשמ\"ג (ספר המאמרים מלוקט ח\"א ע' תכו. ע' תלד ואילך. בהוצאה החדשה – ע' נו. ע' סד ואילך). לקוטי שיחות חל\"ד ע' 184 ואילך.\nוראה לקוטי שיחות ח\"ב ע' 405 ואילך. ושם: די משנה זאָגט אויף ראש השנה, אַז מצות היום בשופר<sup data-n=\"13\">1</sup>.\nעס איז פאַראַן אַ משל פון מורנו הבעל שם טוב<sup data-n=\"14\">2</sup> אויף דעם ענין פון שופר, אַז דאָס איז אַזוי ווי אַ בן שצועק אבא אבא הצילני (אַ קינד וואָס שרייט טאַטע, טאַטע, ראַטעווע מיר).\nכ\"ק מו\"ח אדמו\"ר האָט דערציילט<sup data-n=\"15\">3</sup> בשם די פריערדיקע רביים אַז מען האָט אַמאָל אַרויסגעשיקט זאָגן דעם עולם אין בית המדרש, אַז דער עיקר איז ניט אַזוי דער אבא אבא הצילני, נאָר דער צועק.\nדער פּירוש איז: עס זיינען דאָך דאָ אין דעם צוויי ענינים: א) די צעקה אַליין, ב) דער תוכן וואָס מען לייגט אַריין אין דער צעקה. איז דער עיקר ניט דער תוכן וואָס מען לייגט אַריין אין דער צעקה, נאָר די צעקה (געשריי) גופא<sup data-n=\"16\">4</sup>.\nאין דעם תוכן וואָס מען לייגט אַריין אין דער צעקה, זיינען ניט אַלע גלייך, אָבער אין דער צעקה אַליין, דאָס איז דאָך שייך צו יעדן אידן. יעדער איד איז צועק, בקלא פּנימאה דאשתמע אָדער בקלא פּנימאה דלא אשתמע, אָבער בנפשו פּנימה איז ער דאָך צועק.\nאון דאָס איז דער ענין התקיעות, און דאָס ווערט נתקבל למעלה.\nווי עס איז פאַראַן דער משל פון הרה\"ק הר\"ר לוי יצחק באַרדיטשעווער, אַז אַ קינד האָט געוואָלט אַן עפּל און דער טאַטע האָט אים ניט געוואָלט געבן, האָט דער קינד געמאַכט אויף גיך אַ ברכה, האָט שוין דער טאַטע געמוזט אים געבן דעם עפּל.\nוואָס דאָס איז דאָך בשעת דער טאַטע וויל ניט געבן, ומכל שכן אַז דער טאַטע וויל אים געבן און דאָס ניט געבן איז מער ניט ווי אויסצופּרואוון דעם קינדס קלוגשאַפט, איז דאָך אַודאי אַזוי.\nלמעלה איז דאָך, אַז דער אויבערשטער וויל געבן. ווי עס ברענגט זיך דער לשון<sup data-n=\"17\">5</sup>: יותר ממה שעגל רוצה לינק כו', אַזוי שטייט אויך דער לשון אויף למעלה: למעשה ידיך תכסוף<sup data-n=\"18\">6</sup>, אַז דער אויבערשטער וויל מען זאָל אים דינען.\nבשעת אידן מאַכן אַ ברכה שומע תרועת עמו ישראל, און ברחמים, וואָס על פּי דין איז דאָך ספק ברכות להקל<sup data-n=\"19\">7</sup>, איז אויב די אנשי כנסת הגדולה האָבן אָפּגע'פּסק'נט אַז מען דאַרף מאַכן די ברכה, האָבן זיי ממילא אָפּגע'פּסק'נט אַז דער אויבערשטער איז מקבל תרועת עמו ישראל – די צעקה פון אידן, וואָס דאָס איז דער ענין התקיעות – ברחמים.\n-----שולי הגליון-----"],["13","1","<i>ראש השנה כו</i>,<i> ב</i>."],["14","2","<i>געבראַכט אין המשך וככה תרל\"ז אות ע</i>."],["15","3","<i>ס' השיחות תש\"ד ס\"ע 4 ואילך</i>."],["16","4","<i>זע ספר המאמרים – קונטרסים – ע' 642</i>."],["17","5","<i>פסחים קיב</i>,<i> א</i>."],["18","6","<i>איוב יד</i>,<i> טו</i>."],["19","7","<i>שולחן ערוך אדמו\"ר הזקן קפד</i>,<i> א</i>.<i> זע אויך אגרת התשובה פרק יא</i>."]]],[300010718,"קצה\n\n<b>דער</b> בעל שם טוב זאָגט אַ משל אויף תקיעת שופר, אַ מלך האָט געשיקט זיינע קינדער אין אַ גרויסן וואַלד פיינגען חיות. די קינדער האָבן פאַרבלאָנדזעט, האָבן זיי אָנגעהויבן ריידן צום פאָטער און ניט באַקומען קיין ענטפער, האָבן זיי געטראַכט אפשר האָבן זיי פאַרגעסן זייער אייגענע שפּראַך, האָבן זיי גענומען שרייען פון טיפן האַרצן צום פאָטער, אי אי אָן ווערטער נאָר די שטימע אַליין, האָט זיי דער פאָטער געענטפערט<sup data-n=\"1\">403</sup>.",[["1","403","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' תצ."]]],[300010719,"קצו\n\n<b>מורנו</b> הבעל שם טוב נ\"ע אומר דענין תקיעת שופר הוא צעקת אבא אבא, ומבאר זה במשל כבן שתעה ביער בין חייתו ארץ וצועק אבא אבא הצילני, דבכללות מצות תקיעת שופר אומר מורנו הבעש\"ט נ\"ע דזהו הענג פנימי שלמעלה כבי' כשצועקים בקריאה פנימית דאין לו להאב ענג גדול ופנימי יותר מכמו זה דבנו ובתו קוראי' לו בקריאה פנימי' ועצמית<sup data-n=\"1\">404</sup>.",[["1","404","ספר המאמרים תרצ\"ו ע' 2."]]],[300010720,"קצז\n\n<b>יום הכיפורים</b>\n<b>מורנו</b> הבעל שם טוב האָט אַמאָל מוצאי יום הכיפורים געזאָגט אַ תורה אַז יום כיפּורים איז כפּורים<sup data-n=\"1\">405</sup>.",[["1","405","ספר השיחות תש\"ד ע' 70 ומבאר שם: הכוונה שיוכ\"פּ הוא כמו פּורים* סיי יוכ\"פּ און סיי פּורים איז דאָ דער ענין הגורלות. יו\"כ במקדש איז געווען גורלות און ביי פּורים שטעהט הפּיל פּור הוא הגורל. די נפקא מינא איז, אַז יוכ\"פּ איז עבודת הצדיקים ובין כך ובין כך איז געווען די גורלות, נאָר אויב ס'איז געווען עושין רצונו של מקום דאַן האט דער גורל לה' עולה געווען בימין, אָבער שטענדיג איז געווען דער ענין גורלות. וכתיב לה' חטאת, אַז עס האָט מכפּר געווען. פּורים איז דער הפּיל פּור געווען אויף גזירות רעות אויף אידען, און אַלץ צוליעב דעם, אַז אידען זאָלען תשובה טאָן. פּורים איז די עבודה מעומקא דליבא אין דעם ענין פון מסירת נפש.\n-----שולי הגליון-----\n*) <i>ראה תיקוני זוהר תי' כא (נז</i>,<i> ע\"ב)</i>:<i> פּורים אתקריאת ע\"ש יום הכפּורים</i>.<i> תורה אור מגלת אסתר ד\"ה ומרדכי יצא</i>.<i> שם סד\"ה חייב אינש (הראשון וגם השני)</i>,<i> בהוספות שם ד\"ה ויקח המן פ\"ח</i>."]]],[300010721,"קצח\n\n<b>מחרת יום הכיפורים</b>\n<b>מהבעש\"ט</b>: מה שקורין למחרת יוהכ\"פ גאָטש נאָמען. הנה שם הוי' ושם קודב\"ה אינו אלא מה ששייך לעולם אפי' לעולם הנאצלים, אך לעצמותו אינו שייך לקרותו בשום שם שבעולם<sup data-n=\"1\">406</sup>, והנה אם פוגם הוא בשם הוי' דוקא וכידוע<sup data-n=\"2\">407</sup>, ובימי סליחות העון יש עליות לפני הוי'<sup data-n=\"3\">408</sup>, וזה למחרת יוהכ\"פ אין לו שום שם פרטי לא הוי' ולא אדני רק גאָטש נאָמען<sup data-n=\"4\">409</sup>, וד\"ל<sup data-n=\"5\">410</sup>.",[["1","406","ראה בזה בארוכה בזהר ח\"ב מב, ב. ח\"ג רנז, ב."],["2","407","ראה אגרת התשובה ספ\"ז. ובכ\"מ."],["3","408","ראה לקו\"ת עטרת ראש וסידור בדרושי ס\"פ אחרי ודרושי יוהכ\"פ."],["4","409","בס' אשל אברהם – להרה\"צ וכו' מבוטשאַטש – או\"ח סתרכ\"ד, הובא ביאור על השם ג-ט'ס נאָמען באו\"א וג\"כ בשם הבעש\"ט. ויש לתווך. ואכ\"מ."],["5","410","ספר המאמרים תשי\"א ע' 102. ספר המנהגים-מנהגי חב\"ד – ע' 59 (נדפס ג\"כ בס' גנזי נסתרות (ירות\"ו תרפ\"ד) ח\"א ס\"ק קט)."]]],[300010722,"קצט\n\n<b>סוכות</b>\n<b>מורנו</b> הבעש\"ט האָט געזאָגט: די טבילה אין מקוה און זיצען אין סוכה<sup data-n=\"1\">411</sup> האָבען אַ שייכות, הן אין דעם הכשרת המקבל און הן אין דעם המשכת האור<sup data-n=\"2\">412</sup>.",[["1","411","<i>מקוה . . סוכה</i>: שייכות מקוה וסוכה י\"ל דמקוה הוא בחינת בינה (פע\"ח שער השבת פ\"ג. סידור בכוונת המקוה. לקו\"ת פ' ואתחנן תוס' ביאור ע\"פ וידעת פ\"ב. ועוד). ושייך למקיפים (לקו\"ת פ' תבוא סד\"ה תחת אשר), וסוכה היא מקיפים דבינה (זח\"ג רנה, ב בכתבי האריז\"ל. ודא\"ח בדרושי סוכות). – ולהעיר בתו\"א ר\"פ נח דהמבול כדוגמת המקוה מ\"ם סאה, ובד\"ה כי פדה ה' את יעקב (נדפס בלקו\"ת לג' פרשיות פ' נח [סה, א ואילך. ולאח\"ז – באוה\"ת נח חלק ג תרסט, א ואילך]) ובהמשך וככה – תרל\"ז פצ\"ה ואילך – ביאור הצד השווה דסוכה ותיבת נח וההפרש שביניהם. ואכ\"מ."],["2","412","לקוטי דבורים ח\"ג תקה, ב. ספר השיחות תש\"ט ע' 296. ומוסיף שם: דער מעזריטשער – אמר הוד כ\"ק אאמו\"ר הרה\"ק – זאָגט מקוה איז מטהר און סוכה איז מעלה.\nאָט די צוויי תורות וואָס הוד כ\"ק רבינו הזקן האָט מיטגעבראַכט מיט זיך קומענדיק דעם ערשטן מאָל פון מעזריטש, האָבן די זקנים געהערט פון רבינו הזקן און דאָס האָט זיי געהאַלטן בכל הדרוש להם עד יומם האחרון. פון זיי האָבן דעם רבי'נס קינדער בקטנותם און אויך די חסידים הראשונים אַ סך מקבל געווען.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט מבאר געווען באריכות אין יענעם פאַרבריינגען אָט די ענינים, וואָס דאַן האָב איך דאָס ניט געקענט באַנעמען, און אויך החסיד ר' חנוך הענדיל האָט דאָס מיר ניט געקענט מאַכן צו פאַרשטיין, ערשט שפּעטער מיט יאָרן האָב איך זוכה געווען צו הערן ביאורים מפורטים באריכות ההסבר."]]],[300010723,"ר\n\n<b>דער</b> בעש\"ט האָט געזאָגט, אַז זיין נוי סוכה זיינען פּשוט'ע קבלת עול אידען, וואָס זיינען גורם אַ שמחה למעלה מיט זייער שמחה של מצוה מצד אמונה פּשוטה<sup data-n=\"1\">413</sup>.",[["1","413","ספר השיחות תש\"ו ע' 3."]]],[300010724,"רא\n\n<b>איינער</b> פון די מנהגי קודש של מורנו הבעש\"ט נ\"ע איז געווען די עבודה בשמחה בחג הסוכות מיט גאָר פּשוט'ע אידן{413}.\n----- הערות -----"],[300010725,"רב\n\n<b>שמחת תורה</b>\n<b>דער</b> אַלטער רבי האָט דערציילט אַז דעם ערשטען מאָל וואָס דער בעש\"ט האָט גערעדט מיט זיינע תלמידים וועגען שמחת תורה האָט ער זיי דערציילט: שמחת תורה בכלל פאַרשלאָפען אידען, שבת ויו\"ט בכלל איז דער זמן התפלה שפּעטער ווי בחול, ובפרט שמחת תורה פאַרשלאָפט מען אַביסל, צוליב די הקפות און די סעודת יו\"ט. מלאכים אָבער האָבן ניט די עבודה, ממילא שטייען זיי אויף שמחת תורה אַזוי פרי ווי אַלע מאָל. זיי ווילן זאָגן שירה, אָבער אָן נשמות קאָנען זיי ניט, כמ\"ש<sup data-n=\"1\">414</sup> ברן יחד כוכבי בוקר<sup data-n=\"2\">415</sup>, זיינען זיי אַוועק אויפראָמען דעם גן עדן, מיט אַמאָל געפינען זיי זאַכען וואָס זיי ווייסען גאָר ניט וואָס דאָס איז: פּאַדמיאָטקעס, פּאַנטאָפעל, האָבען זיי זיך שטאַרק פאַרוואונדערט, זיי זיינען געוויינט צו געפינען אין גן עדן ציצית תפילין, אָבער ניט פּאַנטאָפעל.\nזיינען זיי אַוועק פרעגן מלאך מיכאל, האָט ער זיי גיענטפערט, אַז דאָס איז זיין סחורה, און האָט זיי מסביר גיווען, אַז דאָס איז פון די אידישע ריקודים מיט דער תורה און האָט אָנגיהויבען ציילען די פּאַנטאָפעל, די זיינען פון קאַמינקע און די זיינען פון מעזריטש כו'.\nאון דער מיט האָט זיך מלאך מיכאל מתגאה גיווען אויפ'ן מלאך מט\"ט וואָס ער איז קושר כתרים לקונו מתפילותיהן של ישראל<sup data-n=\"3\">416</sup> און ער – מלאך מיכאל – וועט מאַכן אַ בעסערן כתר פון די שמחת תורה טענץ צעריסענע פּאַנטאָפעל<sup data-n=\"4\">417</sup>.",[["1","414","איוב לח, ז."],["2","415","דערפון לערנען אָפּ רז\"ל אַז אין מלאכי השרת אומרים שירה למעלה עד שיאמרו ישראל למטה (חולין צא, ב)."],["3","416","ראה זוהר ח\"ג לז, ב. מאמר ד\"ה צאינה וראינה תש\"ח (קונטרס נח – ספר המאמרים תש\"ח ע' 202)."],["4","417","ספר השיחות תש\"א ע' 31 ואילך. נתבאר בארוכה בשיחת שמחת תורה וש\"פ בראשית (התוועדות ב') תשל\"א. וראה גם – בשם אדה\"ז – ספר השיחות תרצ\"ז ע' 205. תרצ\"ט ע' 308 ואילך."]]],[300010726,"רג\n\n<b>פסח</b>\n<b>מצה</b> שמורה ווערט גערופן בשני שמות עצמיים ופּנימיים: מיכלא דמהימנותא און מיכלא דאסוותא<sup data-n=\"1\">418</sup>, עס גיט אַ חיזוק אין דעת<sup data-n=\"2\">419</sup>.",[["1","418","זח\"ב קפג, ב."],["2","419","שיחת י\"א ניסן תש\"ט (ספר השיחות תש\"ט ע' 312, ושם:\nדאָס איז דער פּנימי נקודי עצמי וואָרט וואָס מורנו הרב המגיד ממעזריטש האָט מקבל געווען ממורו הקדוש מורנו הבעש\"ט בשם הבעל ח\"י ומסרו להוד כ\"ק תלמידו המקבל פּנימי רבינו הזקן ובא ביחוד ובירור מרבי לרבי. וראה שיחת ש\"פ שמיני תשל\"א ושם, ש\"פּנימי נקודה עצמי\" – כנגד חב\"ד, עיי\"ש."]]],[300010727,"רד\n\n<b>הא</b> לחמא עניא, הא איז בינה, איז דאָס לחמא עניא, אַז מען פאַרשטייט די עניות פון השגה דאַן פאַרשטייט מען די עשירות פון חכמה.\nפּסח איז פּה סח<sup data-n=\"1\">420</sup>.",[["1","420","ספר השיחות תש\"ט ס\"ע 314 ואילך, ושם:\nהחסיד ר' זלמן זעזמער האָט איבערדערציילט וואָס ער האָט געהערט פון די זקני החסידים קורצע תורה-ווערטער פון בעש\"ט. איינע פון די תורה-ווערטער [ההמשך בפנים. ולאח\"ז ממשיך:] הוד כ\"ק אאמו\"ר האָט גערעדט אין דעם אַן אריכות הביאור."]]],[300010728,"רה\n\n<b>חכמה ושמחה</b>\n<b>דער</b> רבי האָט געזאָגט: איך האָב מקבל געווען פון זיידן – מורנו הבעש\"ט נ\"ע – אַז שטות, ניט נאָר רוח שטות נאָר שטות, וואָס מענטשן רופן ניט קיין קלוגער מענטש, עצבות און הרגש מעלת עצמו זיינען באַ חסידים עבירות דאורייתא. חכמה, וואָס מענטשן רופן אַ קלוגער, שמחה דורך געפינען אין יעדער זאַך דעם גוט וואָס איז משמח, און זריזות במתינות זיינען באַ חסידים מצות דאורייתא<sup data-n=\"1\">421</sup>.",[["1","421","ספר השיחות קייץ ה'ש\"ת ע' 52."]]],[300010729,"רו\n\n<b>חיצוניות</b>\n<b>ידוע</b> מהבעש\"ט והמגיד ז\"ל ששרש החיצוניות גבוהות מהפנימיות<sup data-n=\"1\">422</sup>.",[["1","422","מאמרי אדמו\"ר הזקן תקס\"ד ע' קכו. וממשיך שם: דזהו הוראה על גובה מדריגות שרש החיצוניות מאחר שירדה כ\"כ בלבושי' והעלמות עד למטה מטה כידוע שכל הגבוה יותר יוכל להשפיל עצמו כו'."]]],[300010730,"רז\n\n<b>חלת דבש</b>\n<b>רבינו</b> הזקן נ\"ע אמר זייענדיג אין מעזריטש האָב איך געהערט פון רבי'ן בשם דעם זיידען: אַז חלת דבש פון קמח דגן – קאָרענע לעקאַך – מאַכט אַ המשכת הלב צו תורה, וויילע דגן און דבש בשרשם זיינען כלים צו תורה<sup data-n=\"1\">423</sup>.",[["1","423","ליקוטי דיבורים ח\"ב רסו, א. ספר השיחות תרצ\"ו ע' 91."]]],[300010731,"רח\n\n<b>הוי'</b>\n<b>צו</b> אונז גזע הוד כ\"ק רבינו הזקן איז איבערגעגעבען אַ וואָרט וואָס הוד כ\"ק רבינו הזקן האָט מקבל געווען פון זיין רבי'ן כ\"ק רבינו המגיד ממעזריטש וועלכער האָט דאָס וואָרט מקבל געווען מהוד כ\"ק מורנו הבעש\"ט. דער ערשטער אות פון שם הוי' איז דער אות יו\"ד, ווייל אַ איד איז דער טעם און כוונה פון בריאת העולם און די תמונה פון אות יו\"ד איז מגלה און דערקלערט די כוונה צוליב וואָס השם יתברך האָט באַשאַפען די וועלט, דער קוץ העליון איז מרמז אויף דער כוונה וואָס עלה ברצונו יתברך צו באַשאַפן דעם עולם הגשמי און דער קוץ התחתון איז מורה אויף דעם יש הגשמי און ווען מען פירט דורך אין דעם וועלטליכען גשמיות'דיגען לעבען די כוונה העליונה צוליב וואָס השם יתברך האָט באַשאַפען די וועלט איז דאָס דער ריכטיקער תמונת היו\"ד, יעדער איד לפי מצבו ולפי ענינו, דאָס הייסט לפי העבודה וואָס זיין נשמה בעדאַרף דורכפירען בעלמא דין להצלחה און דער יסוד מוסד איז החזקת לומדי תורה ביראת שמים<sup data-n=\"1\">424</sup>.",[["1","424","לקוטי דיבורים ח\"ג תקסט, ב. ספר השיחות ה'שי\"ת ע' 344."]]],[300010732,"רט\n\n<b>ירידת הנשמה</b>\n<b>אמר</b> הבעש\"ט: הקב\"ה שיקט אַראָפּ אַ נשמה אויף דער וועלט און לעבט זיבעציג אָדער אַכציג יאָר וואָס דער תכלית הכוונה פון דער שליחות איז צו טאָן אַ אידן אַ טובה אין גשמיות בכלל און אין רוחניות בפרט<sup data-n=\"1\">425</sup>.",[["1","425","לקוטי דיבורים ח\"ג תקסג, ב. ספר השיחות תש\"ה ע' 67. וממשיך שם: דער בעש\"ט'ס וואָרט האָט זיך איינגעקריצט באַ הונדערטער טויזנטער אידן, מענער און פרויען, אין זייערע הערצער, און די זיסע ליבע מדה טובה אהבת ישראל האָט געגעבן איר ריכטיקע אומשעצבאַרע גוטע פרוכט אין הכנסת אורחים, אין אַרויסהעלפן אַ אָרעמאַן בדרך כבוד, אויפשטעלן אַ געפאַלענעם מיט דער גרעסטער ליבליכער אויפמערקזאַמקייט, משתתף זיין זיך אין דעם צער פון אַ אלמנה און יתום, טרייסטן זיי און זיין זיי באַהילפיק אין זייערע באַדערפענישן.\nוראה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' קעד. ע' רפא. ע' רצה. ח\"ד ע' תקכא. ח\"ה ע' קי. ח\"ז ע' כא. ח\"ח ע' רמו. ע' תקיא. \"היום יום\" ה אייר. ספר השיחות תרצ\"ו ע' 123. לקוטי שיחות ח\"ד ע' 1255. נתבאר בלקוטי שיחות חכ\"ה ע' 389 ואילך.\nובאגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"ד ע' קסח מוסיף: אבל פשיטא שאין להסתפק בעשיית טובה פעם אחת או שתיים כו' אלא, כמורגל בלשון רז\"ל אפילו מאה פעמים (עיין חולין פ\"ז, א': הכא כתיב מיעוטא)."]]],[300010733,"רי\n\n<b>מורנו</b> הבעש\"ט זאָגט:\nיעדער איד קומט אויף דעם עולם הזה החומרי מיט אַ געוויסע שליחות פון תורה אור, תורה ליכט. און מיט אָט דער שליחות פון תורה ומצוות גייט ער אום און פאָרט אַרום, הן באַ זיך אין שטאָט און הן וואוהין און ביי וואָס פאַר אַ געלעגנהייט ער פאָרט, מיט אַ שליחות פון תורה ויראת שמים און מחזק זיין מוסדות התורה<sup data-n=\"1\">426</sup>.",[["1","426","ספר השיחות תש\"ט ע' 287. ושם:\nהחזקת התורה וחינוך הכשר איז דער עמוד האור וואָס באַלייכט דעם חשך פון דער גראָבער חומריות'דיקער וועלט און ברענגט צום אמת'ן תכלית צוליב וועלכן די נשמה איז אַראָפּגעקומען אין דער חומריות'דיקער קאַלטער וועלט."]]],[300010734,"ריא\n\n<b>דער</b> בעש\"ט האָט מגלה געווען אַז די כונה פון ירידת הנשמה בגוף איז אויף ליכטיג מאַכן די וועלט דורך עבודת הרבים דוקא<sup data-n=\"1\">427</sup>.",[["1","427","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ח ע' תקא."]]],[300010735,"ריב\n\n<b>מורנו</b> הבעש\"ט – אמר הוד כ\"ק אאמו\"ר<sup data-n=\"1\">428</sup> – האט מיר געזאגט בעמדי באהלי הקדש אשר כל נשמה ונשמה הנה ירידתה משמי רום במעלת רום הא\"ס ב\"ה להתלבש בגוף גשמי, שיצירתו וירידת נשמתו הוא ע\"פ התורה, בכדי לקיים את המצות בכל יום ויום, בחול שבת ומועד, כפי אשר צוה ה' אלקינו בתורתו הקדושה שניתנה לנו לכל ישראל, הכל לצורך עלי' ע\"י קיום התורה ומצות, וכמאמר הידוע אז חכמה דאצילות איז מקנא תפילין שבראש ישראל למטה<sup data-n=\"2\">429</sup>.",[["1","428","כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["2","429","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ט ע' קנב. וממשיך שם: וביאור דבר זה, דהכוונה העליונה שבעצמותו ית' ויתעלה היא אשר הנשמות בירידתן למטה בגופים גשמי', הנה בכל עניניהן זאלן זיי אויספירן די כוונה העליונה וואס נאר א נשמה בגוף קען אויספירן.\nהוד כ\"ק אאמו\"ר הרה\"ק הואיל לבאר לי הכוונה דירידת הנשמה בגוף ומעלת העלי' שנעשה בנשמה ע\"י ירידתה למטה.\nותוכן הדברים, אז אט דאס האט דער רבי מקבל געווען אין מעזריטש, ולהיותו נשמה חדשה, א אור אצילות אין א גוף גשמי, דעם רבי'נס גוף איז געווען א כלי ממש צו אור חכמה דאצילות, פעל דבר זה בחסידים אשר בכל מקום שיהיו זאלן זיי אויספירן די כוונה העליונה בירידת הנשמה בגוף.\nובאחד הפעמים ביאר לי הוד כ\"ק אאמו\"ר הרה\"ק ענין מעלת העילוי שנעשה בהנשמה על ידי ירידתה למטה בגוף ועניני העבודה, אַז דער אור הגאולה וואָס קומט דורך גלות איז אַ אור מבהיק, וענינו בעבודה פרטית אַז דער גילוי אור עצמי וואָס קומט דורך גלות איז אַ אור תקיף יותר. וראה גם אגרות-קודש שם ע' קנט ואילך."]]],[300010736,"ריג\n\n<b>אַ</b> נשמה לערנט תורה מפי הקב\"ה אין מתיבתא דרקיע און הקב\"ה שיקט אַראָפּ די נשמה אויף דער וועלט ניט נאָר צוליב לערנען תורה נאָר אויך צוליב מאַכן פון אנ\"י אי\"ן. אפילו דער וואָס איז באמת אַ אנ\"י פון תורה און מצוות באַדאַרף מען פון דעם אנ\"י מאַכן אי\"ן. ווי מען איז באמת גאָרנישט לגבי די תמימות'דיגע פּשטות פון דעם פּשוט'ן אידן<sup data-n=\"1\">430</sup>.",[["1","430","ספר הזכרונות ח\"א ע' 345. ספר השיחות תש\"א ע' 150."]]],[300010737,"ריד\n\n<b>כוונה</b>\n<b>ס'איז</b> ידוע מאמר הבעל שם טוב<sup data-n=\"1\">431</sup> אַז ס'זיינען דאָ ענינים אין וועלכע עס איז ניט נוגע אויף אַזוי פיל די כוונה (ווי אין אַלע מצוות). איין ענין איז – טבילה במקוה; אפילו אויב מען האָט זיך טובל געווען צוליב אַנדערע טעמים, ניט צוליב טהרה, – נאָך מערער, אפילו אויב ער האָט גאָרניט געמיינט זיך צו טובל זיין, נאָר נפל עליו הגל איז ער טהור<sup data-n=\"2\">432</sup>. אַ צווייטער ענין – נתינת צדקה, וואו ס'זיינען ניט נוגע אויף אַזוי פיל זיינע טעמים צוליב וואָס ער גיט צדקה; און נאָך מערער, אפילו ווען זיין געבן צדקה איז געווען אינגאַנצן אָן כוונה; ער האָט פאַרלאָרן געלט און אַן אָרימאַן האָט עס געפונען, וואָס ער האָט גאָרניט מכוון געווען צו געבן דעם אָרימאַן, וויבאַלד אָבער אַז דער אָרימאַן האָט געקראָגן זיין געלט, האָט ער דערמיט מקיים געווען אַן ענין פון צדקה<sup data-n=\"3\">433</sup>. און ווי די כללות מצות שכחה<sup data-n=\"4\">434</sup>.",[["1","431","ראה ספר בעש\"ט עה\"ת פ' יתרו סימן יד הערה יט."],["2","432","ראה חגיגה יט, א."],["3","433","ראה ספרי ופרש\"י תצא כד, יט."],["4","434","לקוטי שיחות ח\"ג ע' 908."]]],[300010738,"רטו\n\n<b>כחות הנעלמים</b>\n<b>המשל</b> מהבעש\"ט מאנשי העיר שסמכו על הגיבור, שעי\"ז שהתבוננו אח\"כ שאין להשען על הגיבור נתעוררו בהם כחות עצומים ונפלאים<sup data-n=\"1\">435</sup>.",[["1","435","אגרות-קודש כ\"ק אדמו\"ר זי\"ע חלק טז ע' מא."]]],[300010739,"רטז\n\n<b>לימוד התורה</b>\n<b>ווידער</b> לערנען ניט ווי מען דאַרף איז בעסער גאָרניט<sup data-n=\"1\">436</sup>.",[["1","436","ספר השיחות תורת שלום ע' 232. ושם לפנ\"ז: אַזוי שטייט פון בעש\"ט'ס אָדער פון מגיד'ס וועגען, איך האָב דאָס ניט לאַנג געזעהן, אַז [ההמשך בפנים]."]]],[300010740,"ריז\n\n<b>מהרש\"א</b>\n<b>בשם</b> הריב\"ש שכל החיבורים שהיו עד המהרש\"א ועד בכלל היו ברה\"ק וכיון שהוא ברוה\"ק הוא תורה עצמה, ואמר שרק הגילוי הוא ע\"י רוה\"ק אבל כיון שנתגלה ונעשה תורה באמת תורה בעצם גבוה יותר מרוה\"ק, וכיון שהוא תורה אפשר לפרש ע\"פ פרד\"ס<sup data-n=\"1\">437</sup>.",[["1","437","ספר שארית ישראל למהרי\"ד מווילעדניק – דרוש לסוכות ע\"פ פרד\"ס מאמר א' בתחילתו. הובא בלקוטי שיחות חכ\"ג ע' 40 הערה 76. וראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"כ ע' קל."]]],[300010741,"ריח\n\n<b>משיח</b>\n<b>מאמר</b> הבעש\"ט נבג\"מ<sup data-n=\"1\">438</sup> שצריך כל אחד מישראל לתקן ולהכין \"חלק קומת משיח השייך לנשמתו\"<sup data-n=\"2\">439</sup>.",[["1","438","מאור עינים ס\"פ פינחס."],["2","439","לקוטי שיחות ח\"ב ע' 692. ע' 599. ושם: <i>דרך כוכב מיעקב</i>: ראה ירוש' (מעשר שני ספ\"ד) דלכל או\"א מבנ\"י שייך זה. והנה לפי ירוש' תענית פ\"ד ה\"ה (וכ\"פ הרמב\"ן וכמה ממפרשי החומש) מדבר הכתוב במשיח. אין בזה סתירה, ואדרבה – ע\"פ מאמר הבעש\"ט [ההמשך בפנים. ולאח\"ז ממשיך:] ומובן בעבודת האדם – ע\"פ מש\"כ רבינו הזקן באגרת הקודש ס\"ד. וראה ספר השיחות תנש\"א ח\"ב ע' 776. ובכ\"מ.\nוראה גם ספר המאמרים תרמ\"ג ע' ע."]]],[300010742,"ריט\n\n<b>נגינה</b>\n<b>נאָכדעם</b> אַז דער אַלטער רבי איז געקומען אין מעזריטש האָט ער געהערט פון מעזריטשער מגיד בשם הבעש\"ט, אַז דער ענין פון ניגון איז איינער פון די דרכי העבודה אין חסידות<sup data-n=\"1\">440</sup>.",[["1","440","ספר השיחות תש\"ב ע' 122. וראה לקמן סימן רנא."]]],[300010743,"רכ\n\n<b>קודם</b> ההסתלקות צוה הבעל שם טוב לנגן את ההתעוררות-רחמים-רבים ניגון שחיבר הצדיק ר' מיכעלע מזלאָטשוב וכשכלו לנגן הואיל הבעש\"ט לאמר:\nאיך בין מבטיח לדורותיכם אַז ווען און וואו און ווער עס וועט זינגען דעם התעוררות-רחמים-רבים ניגון מיט אַ תשובה התעוררות איז אין וואָס פאַר אַ היכל איך וועל זיין וועל איך הערן. – עס געפינען זיך מלאכים וואָס בריינגען ידיעות און בשורות צו נשמות – און איך וועל אויך מיט זינגען און מעורר רחמים רבים זיין אויף די בעלי תשובה זינגער<sup data-n=\"1\">441</sup>.",[["1","441","ספר השיחות תש\"ג ע' 169. ומועתק בזה דברי כ\"ק אדמו\"ר מהורש\"ב נ\"ע שם: קבלה בידינו אשר ניגון זה קראו הבעש\"ט נ\"ע בשם התעוררות-רחמים-רבים ניגון.\nאויף דעם ניגון האָט מיר דער טאַטע – הוד כ\"ק אאזמו\"ר אדמו\"ר מוהר\"ש – געזאָגט, אַז עס איז בקבלה, וואָס ער האָט געהערט פון פאָטער – הוד כ\"ק אדמו\"ר צמח צדק – בשם כ\"ק זקנו אדמו\"ר הזקן וואָס דער רבי האָט מקבל געווען ממורו הרב המגיד ממעזריטש שהוא הי' נוכח באותו מעמד אשר קודם ההסתלקות [ההמשך בפנים]."]]],[300010744,"רכא\n\n<b>סדר לבישת טלית גדול</b>\n<b>האדם</b> באשר הוא בחיר הנבראים ותכלית מעלת הבריאה, כאמור אדם אתם<sup data-n=\"1\">442</sup> וארז\"ל<sup data-n=\"2\">443</sup> אתם קרויים אדם, כלומר מעלת האדם הוא שכולל את הבריאה כולה, ברכי נפשי כו' לבשת<sup data-n=\"3\">444</sup>, ממלא כולהו עלמין, עוטה אור כו' כיריעה<sup data-n=\"4\">445</sup>, סובב כולהו עלמין, ומברכים להתעטף בציצית הכוונה אשר כוונת עיגול הגדול שלפני הקו תושלם ע\"י הציצית שהן ל\"ב חוטין הנמשכים ע\"י חכ' דאצילות בד' עולמות אבי\"ע, מה יקר חסדך כו' יחסיון<sup data-n=\"5\">446</sup>, אצילות. ירויון מדשן ביתך כו' תשקם<sup data-n=\"6\">447</sup>, בריאה. כי עמך כו' נראה אור<sup data-n=\"7\">448</sup>, יצירה. משוך חסדך כו' לישרי לב<sup data-n=\"8\">449</sup>, עשי'. וגדלה מעלת ישרי לב שהם אנשים פשוטים המתנהגים בדרכי החסידות לראות מעלתם של ישראל על בעלי השכלה שהם רק ידעוך בהשכלה ולא בהרגש<sup data-n=\"9\">450</sup>.",[["1","442","יחזקאל לד, לא."],["2","443","יבמות סא, ב. וש\"נ."],["3","444","תהלים קד, א."],["4","445","שם, ב."],["5","446","שם לו, ח."],["6","447","שם, ט."],["7","448","שם, י."],["8","449","שם, יא."],["9","450","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ט ע' שסח. וממשיך שם: בכדי מען זאָל פאַרשטיין דעם תוכן פנימי פון דעם וואָרט און דערהערן ענינו ופעולתו בעבודה, וואָס אין מעלת ומדריגת נשמה זיינען פאַראַן חילוקי מדריגות, לבד חילוקי דרגות הנשמה אין אירע זעלבסט מדריגות פון שכל ומדות און ג' לבושי הנפש, עס איז פאַראַן אַ חילוק עצמי צווישן נשמות עצמיות און נשמות מתפשטות, הגם אַלע נשמות זיינען מקושרות דורך מדריגת יחידה אין עצמות אין סוף, בכל זה זיינען פאַראַן חילוקי דרגות אין דעם אופן ההתקשרות דאָס הייסט אין דעם דערהער פון דער נשמה, עס זיינען פאַראַן דרגות און מדריגות נשמה אפילו אין נשמות דבי\"ע וואָס בהעלם – בקירוב אל הגילוי – איז נרגש ומאיר עצמות א\"ס, און עס זיינען פאַראַן אַ זעלכע נשמות וואָס אין זיי איז דער דערהער אַ מוסתר ונעלמ'דיקער.\nדער רבי – אמר הוד כ\"ק אאמו\"ר הרה\"ק – איז געווען אַ עצמי, אַ עצמי איז הן אין קבלה און אין השפעה אַ עצמי, אַז מען איז זיך מתדבק אין אַ עצמי און מען חזרט איבער אַ וואָרט פון אַ עצמי איז דער וואָרט באַלעבט – מיט אַ חיות פנימי – אָט דעם וואָס רעט און אָט דעם וואָס הערט."]]],[300010745,"רכב\n\n<b>ספירות, נשמות ומלאכים</b>\n<b>וביאור</b> הדברים ידוע שבכל עולם יש ג' בחי' ספי' ונשמות ומלאכים ובל' הבעש\"ט נ\"ע<sup data-n=\"1\">451</sup> נק' עולמות ונשמות ואלקות<sup data-n=\"2\">452</sup>.",[["1","451","ראה צוואת הריב\"ש סימן עה. אור תורה להרב המגיד ז, א ואילך. אור התורה נח ח\"ג תריד, א. ספר המאמרים מלוקט ח\"ג ע' רפג. בהוצאה החדשה – ח\"ד ע' רפג."],["2","452","פלח הרמון על שיר השירים ע' 230. וראה מאמר שני המאורות קיד, א: ועד\"ז יש להבין בענין בירורי אנ\"ך דתוהו הנז' בסה\"ק היינו אורות ניצוצין כלים. ובקבלת הבעש\"ט נק' בשם עולמות נשמות אלקות כידוע."]]],[300010746,"רכב-א\n\n<b>עבודה זרה</b>\n<b>הנה</b> בס' בן פורת יוסף<sup data-n=\"1\">453</sup> כתוב בשם הבעש\"ט ששאל ממנו מין א' הלא בע\"ז יש חיות מלמעלה והשיב שיש פרסא מפסיק כו' והפסולת שהם הצואה הוא ע\"ז צואת הארץ וכו'<sup data-n=\"2\">454</sup>.",[["1","453","קכו, ג."],["2","454","מאמרי אדמו\"ר הזקן נביאים ע' רלה (ועם הוספות ושינויים – אוה\"ת שבועות (הוצאת תשנ\"ה) ע' 55 ואילך): וממשיך שם: \"וביאור הענין הנה ידוע שיש בחי' פנימי' ממכ\"ע ובחי' מקיף סכ\"ע, בחי' פנימי' הוא זה בתוך זה ומקיף הוא זה למעלה מזה, פי' פנימי' הוא התגלות והתפשטות ההארה כמו אילן הצומח שבתוכו ופנימיותו הוא התגלות והתפשטות כח רוחני הצומח ולמעלה הימנו מקיפו כח החי וכח המדבר שאינם מתלבשים בו כלל מפני חסרון קבלה שאין לו בית קיבול ובבהמה מתלבשת כח החי ולא כח המדבר לפי שאין לה בית קיבול, אבל האדם שהוא כלי מוכן לקבל גם כח המדבר וכל חלקי הנשמה להתפשט ולהתלבש בכל רמ\"ח איבריו ולהיות כי כל אלו בבחי' פנימי' שהוא התפשטות והתלבשות בכחו ובפנימיותו של דבר ולכן נק' אור שהוא זיו והארה כמו זיו השמש כידוע. ויש בו ג\"כ בחי' מקיפין פי' אורות ומוחין שאינם מתלבשים בתוכו ופנימיותו רק על גביו מבחוץ, ואין הארה וזיו שלהם נכנסים ומתפשטים בתוכו ופנימיותו כלל. וענין הגלגולים הוא ענין צמצום ההארה וזיו כמו נשמת האדם שנכנסת ומתלבשת בגוף בהמה אבל אינה מתפשטת הארתה כלל בבהמה שא\"כ הי' לבהמה דעת כאדם. והנה בבחי' א\"פ כל היותר פנימי שבו הוא יותר רוחני בבחי' אין, כמו מחשבה דו\"מ וכן המדות שאין בהם אפי' אותיות יותר בבחי' אין ואפס מן המחשבה, והחב\"ד יותר בבחי' אין מכולם, אבל בבחי' מקיפים היותר פנימי הוא יותר בבחי' יש כמו הארץ הגשמי נגד הגלגלים המקיפין אותה והמקיפין את הגלגל יותר בבחי' אין עוד עד מדריגה אחר מדריגה הכל בבחי' זה למעלה מזה, כידוע שאף שמלמטה למעלה נק' מה שלמטה יש ומה שלמעלה [אין] אבל בבחי' שמלמעלה למטה הוא בהיפך שכל היותר למטה הוא יותר בבחי' אין ואפם מצד בטולו ביטול גמור להמחי' אותו המקיפו וכו'. נמצא ש[ב]בחי' העגולים המקיפים כל מה שהוא יותר במעלות המדריגות הוא העיקר שנראה כל מה שלמטה בפנימיותיו העגולים אופן בתוך אופן כמו הארץ הגשמי ביטול במיעוטו לאין ואפס שלמעלה כמו ע\"ד שלמעלה למעלה אין פנימיות העגולים תופסים מקום כלל וכלל.\nוהנה האומות אין ביכולתם לקבל חיות מאורות מקיפים דקדושה (כמ\"ש בע\"ח שהיותן מהשערות וגומות אור דנוק' דאור פנימי דרך המשכות שערות וכו' תחתית כל המדריגות אבל מאורות מקיפין אין יכולין לקבל שמסמא את עיניהם וכו'), אבל ישראל חלק נחלתו יכולים לקבל מאורות מקיפים דקדושה שהם המצות רצון העליון הנק' כתר וכו'. והנה אורייתא אף דמחכמה נפקת אינו אלא שיצאתה דרך החכמה אבל באמת לוקחה מבחי' סכ\"ע שלמעלה מן ההכמה, נמצא אותיות התורה אף שהם מדרגה התחתונה בטלים הם לבחי' סכ\"ע כמש' אופן בתוך האופן כו' הנ\"ל בבהי' מקיפי', אבל אותיות של דברים בטלים מפני שיש פרסא שהוא חצר הכבד מפסקת ומבדלת עד כאן תחום הקדוש ולא יעבור הזר וקליפה שם כלל אינן נלקחות מהקדושה כלל רק מהפסולת היוצאי' מהקיבה כמשי\"ת לקמן.\nוהנה למשל מן המאכל הגשמי דומם וצומח אין התינוק יודע לקרות אבא ואמא שהוא חב\"ד עד שיטעום טעם דגן, נמצא שהמוח מקבל חיות מן המאכל. ובאמת א\"א להמוח רוחני בתכלית לקבל המאכל גשמי בתכלית, אך היות מפני כשהגוף בלא אכילה מסתלק הנשמה מהגוף ובאכילה ממשיך הנשמה בתוך הגוף לשרות ברמ\"ח אבריו, נמצא שהמאכל מחבר המוח אל הגוף. וכמו כן בכנ\"י כתיב רעיתי ישראל מפרנסין לאביהם שבשמים ועשיתם אתם מעלה אני עליכם כאילו עשוני שע\"י עשיית המצוה רצון העליון העלאת מ\"ן ממשיכים מ\"ד התגלות אורות עליונים של א\"ס הסכ\"ע באצילות ובכל העולמות ונעשה תוספת הארת המוחין שהיא התורה חב\"ד של המצות. ואף שהמוחין הם הם המוחין דמצות מקבל תוספת הארה על ידן ע\"י העלאת מ\"ן בהיות שכל עניני התורה הם רק באופני פרטיות עשיות המצות מעשיות נמצא מקבלת מן המצות, ונעוץ תוכן תחלתן בסופן ואין ראש שלא יהי' סוף כי הראש מוכרח לקבל מן הסוף, כמו למשל מאכל גשמי המחי' את המוח, וכל מצות מעשיות הן מדברים מעניני גשמיות, כמו צמר כבשים לציצית וקלף תפילין רק שמתבררין ע\"י הבישול בקיבה תחת הפרסא ע\"י אפי' כמבואר במ\"א. ואחר הבירור עולה המובחר למעלה מן הפרסא וניזון ממנה המוח והלב והוא בחי' מ\"ן, והבישול הוא ע\"י הגבורות שביסוד דנוק' שהוא אהוי\"ר שכל הבירורים הוא ביסוד דנוקבא. וזהו ויעש דוד שם דוד הוא שהמשיך האורות בתוך הכלים איהו וגרמוהי הד כו'. וזהו וכל קרבי את שם קדשו קרבי הוא הקיבה ששם נתבשל ונתברר מהפסולת היוצאים לחוץ והמובחר עולים בבחי' מ\"ן והם תמכין דאורייתא המ[ח]זיקים לומדי תורה ומקיימין אותה. וזהו העולם נתן בלבם מבלי שימצא וגו' שהראש מקבל מן הסוף ונעוץ תחלתן בסופן וסופן בתחלתן כנ\"ל, והוא עולם התיקון שזה צריך לזה וזה לזה הגדול צריך לקטן וכו' משא\"כ בעולם התהו שהיו זה תחת זה כל א' בפני עצמו והי' הראש מופרד מסוף שלא הי' מוכרח להראש לקבל מן הסוף ולכן הי' שבירת הכלים. ובגוים כתיב רם על כל גוים ה' על השמים כבודו שאצלם הוא רם ונשגב ואינו מתלבש בתוכם מפני היות השמים שהוא הרקיע פרסא מחיצה מפסקת בינם ובין הקדושה. אבל בישראל כתיב ויהי קול מעל לרקיע כו' קול הוא המשכה להמשיך מרוחני לגשמי לחברם כמו ענין הקול שיוצא מן הלב שללב בא מן המחשבות המוח בבחי' רוחני ומן הלב דרך הקנה בהצטרפות אר\"מ ונעשה קול גשמי שממנו מתחלק הדבור הגשמי נמצא הוא מחבר רוחניות לגשמיות, והתורה נתנה בה' קולות ה' המשכות הה\"א מדות כו' (כי יסוד כלול מכולם) מאור א\"ס ב\"ה המקיף כל העולמות. וזהו קול ה' על המים שהיא התורה. בעמדם תרפנה כנפיהם שהחיות דיצירה ועשי' הם רק המדות אהוי\"ר ובראותם בחי' הגבוה מהם שהוא קול ההמשכה מבחי' סכ\"ע שנעשה ע\"י העלאת מ\"ן של ישראל במצותם שעושים רצונו של מקום תרפנה כנפיהם מתבטלים מעבודתם אהוי\"ר הנק' גדפין, אבל לישראל אמר להם משה אל תיראו אינכם צריכים לכך לעבודת יראה זו שהיא רק שער ופתח כמשארז\"ל לעולם יכנס אדם שיעור ב' פתחי' כו', כי לבעבור נסות אתכם בא להגבי' אתכם האלהי' בבחי' ביטול לגמרי שאין מי שיאהוב כ\"א יראתו תהי' על פניכם רק לבלתי תחטאו לצורך יראת חטא שלא יפול בבחי' חטא שהוא גרוע מן כו'. ואף בתפלת ישראל ע\"י העלאת מ\"ן שלהם באהוי\"ר אף שלהם קטן מאהוי\"ר של המלאכים עכ\"ז בהתעוררות שורש נשמותיהם למעלה מקור חוצבם למעלה מהמלאכים שם אהוי\"ר שלהם גבוה מן המלאכים. וסיבת הדבר הזה שישראל יוכלו להגיע למדריגה גבוה מן המלאכים הוא מפני היות שהם המעט מכל העמים שממעטים עצמם מפני שהם בבחי' אין מאוה\"ע, כי לי כל הארץ מי הוא בחי' לי וביטול לא\"ס ב\"ה כל הארץ מי שהוא בתכלית השפלות בבחי' ארציות וכו'. וזהו ואביא אתכם אלי למעלה מן אהוי\"ר כו' ע\"י שאני נושא אתכם על כנפי נשרים\"."]]],[300010747,"רכג\n\n<b>עבודת השם</b>\n<b>דער</b> בעש\"ט נ\"ע האָט געזאָגט<sup data-n=\"1\">455</sup> אַז אַלץ וואָס אַ מענטש זעט און אַלץ וואָס אַ מענטש הערט<sup data-n=\"2\">456</sup> דאָס איז אַ אָנזאָג און אַ געוויסע הוראה מן השמים אין עבודת השי\"ת<sup data-n=\"3\">457</sup>, נאָר מען באַדאַרף פאַרשטיין וואָס מען זעט און וואָס מען הערט, און חלילה ניט האָבן קיין טעות אין דעם מיין פון דעם וואָס מען האָט געהערט און פון דעם וואָס מען האָט געזען. און דער ריכטיקער פאַרשטאַנד אין דעם מיין פון דעם וואָס מען הערט און זעט קומט דורך דעם נשמת אדם תלמדנו.\nנשמת אדם תלמדנו איז דער ענין וואָס באַ דעם מענטשן ווערט ליכטיק דער שכל און אים פאַלט אַריין פאַרשידענע ערקלערונגען אויף דעם וואָס עס קען מיינען אין עבודה אָט דאָס וואָס ער האָט געזען און געהערט, און אַזוי אַרום קומט דער מענטש צו פאַרשטיין די הוראה מן השמים אין עבודת ד'.\nדער בעש\"ט נ\"ע זאָגט אַז דער זיכערסטער וועג, צו דעם נשמת אדם תלמדנו, איז: א) אַ פלאַם האַרציקער קאַפּיטל תהלים, ב) טאָן אַ אידן אַ טובה דורך אַ טרחה בגופו ניט נאָר בממונו, און דורך ג) אהבת ישראל מיט אַ מסירת נפש.\nדער בעש\"ט נ\"ע זעט דעם גילוי פון נשמת אדם תלמדנו אין די תהלים זאָגער מער ווי אין די תלמידי חכמים, וואָס זיינען מחדש חידושים און פּלפּולים בתורה.\nדער בעש\"ט נ\"ע זאָגט אַז אַ האַרציקער קאַפּיטל תהלים, אַ טרחה צוליב טאָן אַ טובה אַ אידן אין גשמיות אָדער אין רוחניות און אהבת ישראל זיינען שליסעלעך וואָס פּאַסן זיך צו צו אַלע שלעסער פון די היכלות הרחמים רפואה ישועה און פּרנסה טירן<sup data-n=\"4\">458</sup>.",[["1","455","ראה ספר השיחות קייץ ה'ש\"ת ע' 11."],["2","456","ראה לקו\"ש ח\"ח ע' 338 בהערה: <i>שאדם רואה</i> <i>. .</i> <i>שומע</i>: להעיר מנדרים (סד, ב) דסומא חשיב כמת ומב\"ק (פה, ב) חירשו נותן לו דמי כולו. ולהעיר מלקו\"ת ד\"ה להבין ענין יו\"ט שני (דברים צא, ג ואילך)."],["3","457","ראה לקוטי שיחות חל\"ד ע' 166: והנה ע\"פ מחז\"ל זה ד\"לא קאי איניש אדעתי' דרבי' עד ארבעין שנין\" יש למצוא מקור בתושב\"כ לתורת הבעש\"ט . . שהיא מיסודי תורת החסידות – ש\"כל דבר ודבר אשר האדם רואה או שומע הוא הוראת הנהגה בעבודת השם, וזהו ענין העבודה, להבין ולהשכיל מכל – דרך בעבודת השם\".\nונמצא, שכל דבר שקורה לאיש ישראל צריך \"ללמוד\" אותו (ע\"ד שלומד ענין כביכול בתורה), עד שיוכל להוציא מזה הוראה בעבודתו לקונו.\nודבר זה מפורש במחז\"ל הנ\"ל, שלמדים הא ד\"לא קאי איניש אדעתי' דרבי'\", ממה שנאמר \"אתם ראיתם גו' ולא נתן ה' לכם לב לדעת גו' עד היום הזה\". דלכאורה, בנוגע לדברי תורה מובן שצ\"ל שהיית זמן עד שעומדים \"על דעת רבו\", מצד העומק לפנים מעומק הטמון בד\"ת שמלמד הרב עם תלמידו; אבל בנוגע ל\"המסות הגדולות\" ו\"האותות ומופתים\", שהם דברים הנראים בחוש, הרי בעת ראיית הנסים בפעם הראשונה, כבר \"תפס\" הכל, ומה שייך לומר בזה \"לא קאי איניש אדעתי' דרבי' עד ארבעין שנין\"?\nועכצ\"ל, שבנסים אלו היו טמונות הוראות בעבודת ה', וזוהי תכלית כוונת הקב\"ה בעשיית נסים הללו (שמהם ילמדו בנ\"י \"ויקחו\" חיזוק בעבודתם לקונם), ופרטי הוראות אלו יכולים להתעמק בהם יותר ויותר, עד שלאחרי ארבעים שנה עומדים על \"סוף דעתו\" של הקב\"ה כביכול בעשיית נסים אלו.\nאלא שלזה צריכים להתעמק בפרטי הנסים וכו' . . שאז, לאחרי מ' שנה עומדים על עומק הכוונה וההוראות שבזה.\nוכן הוא בכל דבר ודבר שהאדם רואה או שומע, שהם מהווים הוראה ולימוד (כמו דברי תורה), שצריך להתבונן בהם, ללמוד אותם ולדייק בהם, באופן, שלאחרי מ' שנה נתעצם אצלו הענין, \"קם אדעתי' דרבי'\"."],["4","458","ספר השיחות קייץ ה'ש\"ת ע' 73."]]],[300010748,"רכד\n\n<b>מורנו</b> הבעש\"ט אמר: כל דבר ודבר אשר האדם רואה או שומע, הוא הוראת הנהגה בעבודת השם, וזהו ענין העבודה, להבין ולהשכיל מכל דרך בעבודת השם<sup data-n=\"1\">459</sup>.",[["1","459","\"היום יום\" ט אייר מאגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' רפט.\nובספר המאמרים תש\"ה ע' 30: וכמאמר מורנו הבעש\"ט נ\"ע דכל מה שהאדם רואה ושומע הוא הוראה מלמעלה בענין עבודתו בסור מרע ועשה טוב.\nוראה גם בשם הבעש\"ט – אגרות-קודש אדמו\"ר מהוריי\"צ ח\"א ע' קמח. ח\"ב ס\"ע תקלז ואילך. ח\"ג ע' שצח. ח\"ד ע' תכז. ח\"ו ס\"ע סא ואילך. ע' שכז. ח\"ז ע' מד. חי\"ד ע' פז. לקוטי דיבורים ח\"א קעא, ב. ח\"ד תרמה, ב. ספר השיחות תרפ\"ז ע' 213. תרצ\"ו ע' 6. לקוטי שיחות ח\"ב ע' 633. ח\"ו ע' 284. ועוד.\n– מאמר זה הובא בכ\"מ באו\"ת ולקו\"א להרב המגיד (לא בשם הבעש\"ט) – נסמן במפתחות לשם ע' נג (וכל מה שאדם וכו')."]]],[300010749,"רכה\n\n<b>מורנו</b> הבעש\"ט האָט געזאָגט די תלמידים אַז דער דרך אמיתי איז, אַז דאָס וואָס אַ מענטש זעט און הערט איז ניט קיין צופעליקע זאַכן נאָר אַ הוראה מן השמים. מען באַדאַרף מעורר רחמי שמים זיין אַז מען זאָל זוכה זיין צו פאַרשטיין דאָס וואָס מען זעט.\nדי עבודה אמיתית איז צו זען דעם אמת אַז יעדער איד איז אַ שליח אויף מגלה זיין געטלעכקייט, און די פּשוט'ע אידן מיט זייער תמימות זיינען אמת'ע עבדי ה'<sup data-n=\"1\">460</sup>.",[["1","460","ספר השיחות קייץ ה'ש\"ת ע' 133. וממשיך שם: און האָט געהייסן די תלמידים זיי זאָלן זיך צוקוקן צו ר' פסח דעם וואַסערטרעגער ווען ער באַדאַרף אַריינגיין אין בית הכנסת דאַוונען.\nדי תלמידי הבעש\"ט האָבן זיך צוגעקוקט צו ר' פּסח'ן איידער ער באַדאַרף אַריינגיין אין ביהכ\"נ דאַוונען מנחה, ווי ער וואַשט די הענט עטלעכע מאָל און אָפּגעווישט מיטן בגד, און ווען ער האָט געעפנט די שול טיר און אַריין אין בית הכנסת האָט זיך זיין פּנים פאַרענדערט מצד היראה, און אַז ער האָט געקוקט אויף דעם ארון הקודש און געזאָגט דעם פּסוק שויתי ה' לנגדי תמיד האָט זיך באַ אים געביטן דער פּנים אין פאַרשידענע פאַרבן."]]],[300010750,"רכו\n\n<b>חיי</b> האדם ע\"פ האדמה חתומים וכמוסים בתעודה מוגבלה לצורך הנשמה והעולם בזמן ומקום מכוון ליודע נעלמות, ולזאת הנה כל מה שהאדם רואה ושומע גם בעניני העולם השפל עולם ההמי' והצלצל המחי' והכלכלה, שני דרכים לפניו, האחד מובילו לשאול תחתית אפל וצלמות, והשני למקום אורה וחביון עוזו ית' וית', והבחירה חפשית הוא ביד האדם לבחור בטוב ולמאוס ברע<sup data-n=\"1\">461</sup>.",[["1","461","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"א ע' תצא."]]],[300010751,"רכז\n\n<b>עצם</b>\n<b>וכמו</b> שאמר הבעש\"ט ז\"ל שכשאתה תופס במקצת מן העצם אתה תופס בכולו כו'<sup data-n=\"1\">462</sup>.",[["1","462","המשך תרס\"ו ע' תקכב. וראה המשך תער\"ב ח\"א ע' תקנג. ספר המאמרים תרע\"ח ע' שכ. לקוטי שיחות ח\"ב ע' 435. ע' 499. ח\"ד ע' 1208 ואילך.\nוראה הערת כ\"ק אדמו\"ר זי\"ע בספר השיחות תש\"א ע' 32: בספר תולדות יעקב יוסף יתרו מצות אנכי: שכתבו הראשונים כו' בכל מקום שאני תופס ואוחז בקצה וחלק מחלק האחדות הרי אני תופס כולו וכן שמעתי ממורי, ובפ' חיי שרה [עה\"פ כד, א]. מפירוש היעבץ לאבות פ\"ד מ\"ב: התופס מקצת מן האחדות תופס כולו.\nוראה שיחת יום שמחת תורה תשי\"ב (תורת מנחם – התוועדויות ח\"ד ע' 90 ואילך): \"העצם כשאתה תופס במקצתו אתה תופס בכולו\", משום שהעצם בלתי מתחלק, ובמילא כשתופס במקצתו ה\"ה תופס בכולו – דלכאורה אינו מובן: כיון שהעצם אינו מתחלק, איך שייך המושג של מקצת של העצם, שנוכל לומר שע\"י התפיסא בהמקצת תופס בכולו? – אלא הכוונה היא להעצם כפי שנמשך ובא בשינויים גם בבחי' מקצת, שכיון שהעצם הוא זה שבא בהמקצת, לכן, יש בו הכל, ובמילא, התופס במקצתו תופס בכולו."]]],[300010752,"רכח\n\n<b>עשירות</b>\n<b>עשירות</b> איז באַ איינעם אַ גן עדן און ביים צווייטן אַ גיהנם<sup data-n=\"1\">463</sup>.",[["1","463","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ז ע' נח. וממשיך שם: האָט דער אלטער רבי דאָס אויסגעטייטשט אַז באַ דעם וואָס נוצט די עשירות צוליעב צדקה און תורה ומצות איז די עשירות אַליין אַ גן עדן און באַ דעם וואָס ניצט די עשירות פאַר זיך אויף עניני עולם אָדער ער האַלט דאָס ווי אַ אוצר, איז די עשירות אַליין אַ גיהנם."]]],[300010753,"רכט\n\n<b>פגישה</b>\n<b>שמעתי</b> מכ\"ק מו\"ח אדמו\"ר פתגם בשם הבעל שם טוב, שכשנפגשים פעם אחת בטח יפגשו שנית<sup data-n=\"1\">464</sup>.",[["1","464","אגרות-קודש כ\"ק אדמו\"ר זי\"ע חי\"ז ע' נא. וראה ד\"ה אל יפטר תשכ\"א (ספר המאמרים תשכ\"א ע' 204): וכמאמר הבעש\"ט הידוע שבכל מקום שהי' האדם פעם אחת, מוכרח לבוא שמה שנית (ראה ספר בעש\"ט עה\"ת פ' לך לך אות כג)."]]],[300010754,"רל\n\n<b>פסקי הלכות</b>\n<b>לומדי</b> תורה בכלל ומורי הוראה – המבררים בדבור ובכתב פסקי הלכות – בפרט, צריכים עבודה מרובה בתפלה ותחנונים לפני המקום שיכוונו אל האמת<sup data-n=\"1\">465</sup>.",[["1","465","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ט ע' שלב."]]],[300010755,"רלא\n\n<b>ציצית</b>\n<b>וכל'</b> הזה אמר הבעש\"ט ז\"ל אפי' מלאך מיכאל הגדול שבמלאכים הי' נותן כל עבודתו והשגתו באלקות אפי' רק עבור מצות ציצית אחת מד' ציציות<sup data-n=\"1\">466</sup> שיש לכל א' מישראל.\nכי השגת מיכאל הוא בחי' שבאה בהשתל' בעולם הבריאה שהוא בחי' גבול משא\"כ בחי' הציצית הן בחי' שער רישי' כעמר נקי<sup data-n=\"2\">467</sup> שהוא בחי' המשכת אוא\"ס ב\"ה שלמע' מהשתל' וכן כיוצא בזה בכל המצות וזהו הנק' שמחה של מצוה שהוא עיקר עבודת האדם בעוה\"ז וע\"ז נא'<sup data-n=\"3\">468</sup> תחת אשר לא עבדת את ה\"א בשמחה ובטוב לבב כו' כי מאד צ\"ל שמחה וטוב לבב בשמחה עזה מהמשכת עצמי' אוא\"ס ב\"ה ע\"י המצות שאין כל העולמות ערך אליו כלל כו' ולכן אף שיהי' בעיניו כרשע וידע שיקבל עונש בגיהנם עבור זה או יסורי עוה\"ז אעפ\"כ יהי' שמח וטוב לב משמחה של מצוה הנ\"ל כי הרי כל יסורי גיהנם כדאי אפי' נגד קורת רוח שעה א' בג\"ע התחתון אצ\"ל בג\"ע העליון כו' עאכו\"כ נגד המשכת עצמי' אוא\"ס ב\"ה על כל מצוה שאין כל התענוגים עליונים גם מה שלמע' מעלה מג\"ע העליון לא יעריך אליו כלל וכלא ממש חשיבי' ולכן צ\"ל שמח וטוב לב ואעפ\"כ יהי' כרשע בעיניו מצד חסרון היראה כנ\"ל ושגם ידע כי מגיע מזה עונש לנה\"ב אבל שמחה תקיעא בלבאי מסטרא דא ואינם תרתי דסתרי כלל כו' וד\"ל<sup data-n=\"4\">469</sup>.",[["1","466","בהערות כ\"ק אדמו\"ר זי\"ע לקיצורים והערות לתניא (ע' קמט): <i>מצות ציצית אחת מד' ציציותיו</i>. כן הוא בכת\"י 7. אבל בכת\"י 8, 9 אין התיבה <i>מצות</i>.\nויש להעיר ממנחות (כח, א) ד' ציציות . . שארבעתן מצוה א' ר' ישמעאל אומר ארבעתן ד' מצות. – ומה שתפס לדוגמא מצות ציצית דוקא י\"ל א) משום דבפועל מצינו מלאך מחמיר ומקפיד במצות ציצית דוקא, אף דלמדין מזה לשאר עשה ג\"כ (מנחות מא, א). אבל זה גופא טעמי בעי. ב) מעניני וטעמי מצות ציצית שתכלת דומה כו' לרקיע כו' לכסא הכבוד, וא\"כ יש מקום לומר שמלאכים שהם ברקיע ולפני כסה\"כ (ראה במדב\"ר פ\"ב, ו שמיכאל סובב לכסא) אין זקוקים כלל להזכרה דציצית. ואדרבה הם הרי רואים בתמידיות את העיקר ולא את הדומה לדומה. ולכן אומר דאפילו בזה הרי עבודה למטה בדומה לדומה היא באין ערוך לההשגה למעלה בכה\"כ עצמו. – ובזה מובן ג\"כ שדוקא בציצית הקפיד מלאך, דכל מי שיתמיד בעבודה פרטית ותגדל פשיטותה אצלו, וכמו זכירת הרקיע במלאך, תגדל אצלו התמי' בהעדרה, ואפילו אצל אחר, מפני רגילותו בה. ג) ד' ציציות הם כנגד ד' חיות המרכבה, והמתעטף בציצית, \"<i>כאילו</i> מתקין כורסי' לקוב\"ה\" (ת\"ז סוף תי' יו\"ד באריכות). והנה מלאך מיכאל הוא, בתמידיות, אחד מחיות המרכבה (זח\"ג רט\"ז, א' ועוד). ואומר שאעפי\"כ הי' נותן כל עבודתו כו'. – ובזה מדויק ג\"כ מה שאמר <i>אחת</i> מד' ציציות, כי אינו אלא אחת מחיות המרכבה. ד) שמעלת המצות למטה מבאר בפנים שהיא מה שזהו למעלה מהשתל'. ואומר שאפילו ציצית שענינה המשכה בדרך דילוג צמצום ושערות, בכ\"ז הי' נותן כל עבודתו כו', כי דוקא עי\"ז נמשך מלמעלה מהשתלשלות. וכמבואר בארוכה בדא\"ח בדרושי ציצית ומחלוקת קרח (וראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"ב ע' שעז ואילך. לקוטי שיחות חי\"ג ע' 199-198. ר\"ד ד' תמוז תש\"מ)."],["2","467","דניאל ז, ט."],["3","468","תבוא כח, מז."],["4","469","קיצורים והערות לתניא ע' מו. מאמרי אדמו\"ר הזקן ענינים ע' ריא ואילך.\nובאוה\"ת שה\"ש ח\"ג ע' תתקו: ומעשה דבעש\"ט שמיכאל הי' נותן קדוש שלו עבור א' מד' ציצי', כי ע\"י ציצי' נמשך אה\"ר מלמעל' למטה מרכבתא עילא' דאצי' שאין אהבת מיכאל ערוך כו'."]]],[300010756,"רלב\n\n<b>קל-וחומר, גזירה שוה והלכה למשה מסיני</b>\n<b>האָט</b> דער רבי זיי געזאָגט אַ תורה פון מגיד בשם הבעש\"ט:\nקל וחומר וגזירה שווה. קל וחומר מיינט אַז אַ דבר קל זאָל זיין חמור. גזירה שווה – אַ גלייכער שניט. דאָס קען נאָר זיין אלא אם כן קבלה מרבו ורבו מרבו הלכה למשה מסיני.\nהלכה למשה מסיני, משה האָט ניט געוואָלט אַוועקגיין פון סיני אין וועלט. הגם משה האָט זיך געקענט ספּראַווען מיט זיין גוף, אָבער ער האָט ניט געוואָלט אַוועקגיין מסיני. משה איז חכמה, חכמה דאצילות בעלייתה אל הכתר, וויל זי ניט זיין די ערשטע ספירה, אָבער מצד פּנימיות החכמה ווען זי איז עולה אין פּנימיות הכתר דערהערט מען די כוונה פּנימיות אַז דער עיקר איז דאָ למטה. –\nדאָס איז הלכה למשה מסיני, הלכה לשון מוליך, ער האט מוליך געוועזן משה'ן ער זאָל וועלן אַוועקגיין מסיני למטה, ביז ולא ידע איש את קבורתו<sup data-n=\"1\">470</sup>, וואו משה האָט באַהאַלטן זיין גוף, אַז ער האָט עולה געווען אין פּנימיות<sup data-n=\"2\">471</sup> החכמה<sup data-n=\"3\">472</sup>.",[["1","470","ברכה לד, ו."],["2","471","להעיר ממרז\"ל (סוטה יד, א) לעליונים כו' לתחתונים כו' ונתבאר בלקו\"ת במדבר ד\"ה מעט תוספות ביאור על ענין וספרתם. סד\"ה כי ישאלך בנך ש\"ת."],["3","472","ספר השיחות תש\"ט ע' 291. ושם לפנ\"ז: ווען דער רבי איז צוריקגעקומען פון מעזריטש האָט ער באַדאַרפט האָבן אַ התנצלות פאַר זיינע תלמידים פאַר דעם שינוי הדרך.\nכידוע אַז יעמולט זיינען די בני תורה געוועזן מובדל פון אנשים פּשוטים. מ'האָט געהאַט אַן אייגן מנין, און מ'האָט זיי ניט צוגעלאָזט צום עמוד אפילו ביי אַ יא\"צ, קומענדיק אָבער פון מעזריטש, האָט דער רבי משנה געווען דעם דרך.\nדי תלמידים פון אַלטן רבי'ן האָט מען ניט געקענט אָפּקומען מיט זיי מיט פּשט'לאַך. זיי האָבן געוואוסט, חב\"ד איז חב\"ד, חג\"ת איז חג\"ת. [ההמשך בפנים]."]]],[300010757,"רלג\n\n<b>רמב\"ם</b>\n<b>דער</b> רמב\"ם איז געווען אַ גרויסער מקובל<sup data-n=\"1\">473</sup>.",[["1","473","ספר השיחות קייץ ה'ש\"ת ע' 41. ושם לפנ\"ז: דער זיידע – אדמו\"ר מהר\"ש – האָט אין איינעם פון די שיעורי לימוד וואָס ער האָט געלערנט מיטן פאָטער דעם מורה נבוכים געזאָגט, אַז ער האָט בקבלה רבי מרבי ביז מורנו הבעש\"ט אַז [ההמשך בפנים].\nובהערת כ\"ק אדמו\"ר זי\"ע שם: לכאורה צ\"ע ממ\"ש בשער הגלגולים הקדמה ל\"ו ומהר\"ש אלקב\"ץ בפירושו לשיר השירים אשר הרמב\"ם לא למד חכמת האמת. וראה שם הגדולים להחיד\"א מערכת רמב\"ם.\n– כתבו על הרמב\"ם שבסוף ימיו עסק בקבלה: מגדול עוז הל' יסוה\"ת פ\"א ופ\"ב. שו\"ת מהר\"ם אלשקר סי' קיז. עבודת הקודש ח\"ב פי\"ג. הלבוש בלבוש פנת יקרת ח\"א פנ\"ג. וראה שומר אמונים ויכוח א ס\"ק יג, פי' הר\"מ בוטריל לספר יצירה פ\"ד מ\"ג."]]],[300010758,"רלד\n\n<b>שמחה</b>\n<b>מקובל</b> מאת מורנו הבעל שם טוב נ\"ע כי השמחה בישועת השי\"ת היא עצמה היא אסותא<sup data-n=\"1\">474</sup>.",[["1","474","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ז ס\"ע רצ ואילך."]]],[300010759,"רלה\n\n<b>תיקון המדות</b>\n<b>עיקר</b> החסידות איז תיקון המדות<sup data-n=\"1\">475</sup> און מייקר זיין אַ פּשוט'ן אידן, וואָס די עבודות זיינען די עלי'-טרעפּ אין דעם דרך החיים און צו גיין אויף טרעפּ באַדאַרף מען האָבן אַ סיוע פון אַן עלטערן און דאַן איז דאָס אַ הילוך מסודר<sup data-n=\"2\">476</sup>.",[["1","475","ראה אגרות-קודש אדמו\"ר הצמח צדק ח\"ב ע' קה. ספר השיחות תורת שלום ע' 48. שיחת שמע\"צ ושמח\"ת תרצ\"ד (לקו\"ד ח\"א נו, א). אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' תנח."],["2","476","לקוטי דיבורים ח\"ג תקו, ב. ספר השיחות תש\"ט ע' 297, ושם לפנ\"ז: אדמו\"ר הזקן האט דאַן מקבל געווען אַ תורה מכ\"ק דודו הנסתר הגאון הצדיק הר\"ר יוסף יצחק וואָס ער וגיסו הצדיק הנסתר הר\"ר ברוך האָבן געהערט ממורנו הבעש\"ט בתחלת התגלותו [ההמשך בפנים]."]]],[300010760,"רלו\n\n<b>אין</b> מעזריטש האָט דער רבי געזאָגט בשם מורו הבעש\"ט אַז דרכי עבודת תיקון המדות והכשרת כלי המוח בדרכי החסידות איז צו מאַכן פון דעם חסרון אַ מעלה<sup data-n=\"1\">477</sup>.",[["1","477","ספר השיחות ה'שי\"ת ע' 400. ושם:\nעס זיינען פאַראַן צוויי דרכי עבודה: די עבודה פון געפינען אין זיך דעם חסרון און אים מתקן זיין, וואָס ביידע זאַכן, הן דער געפינען דעם חסרון און הן דער מתקן זיין אים, דאַרפן זיין על פּי דרכי התורה. [ההמשך בפנים. ולאח\"ז ממשיך:]\nאויף דעם יסוד התורה ודרכי העבודה דערציילט הוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק להוד כ\"ק בנו אאזמו\"ר הרה\"ק מוהר\"ש, האָט דער זיידע – רבינו הזקן – אַוועקגעלייגט זיינע כחות עצמיים בערך דרייצן יאָר."]]],[300010761,"רלז\n\n<b>תשובה</b>\n<b>תשובה</b> איז שבת ו\"ה, שם הוי' י' חכמה ה' בינה ו' מדות ה' מלכות, י\"ה הנסתרות לה' אלקינו, ו\"ה נגלות, ובשבת העבודה במוחין, וזהו תשובה שבת ו\"ה<sup data-n=\"1\">478</sup>.\n**********",[["1","478","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' ריב. ושם, שהבעש\"ט אמר ג\"כ \"תשובה איז בושת ה', ה' איז מעשה\"."]]],[300010762,"רלח\n\n<b>מנהגי והנהגות הבעל שם טוב</b>\n<b>מלוקט מספרי רבותינו נשיאנו הקדושים</b>\n<b>אהבת ישראל</b>\n<b>דער</b> ענין פון אהבת ישראל וואָס איז געווען ביי מורנו הבעש\"ט איז געווען אין להעלות, אָן אַ שיעור. דער בעש\"ט האָט ליב געהאַט אידן און ער איז געווען מופלא אין דעם. ביז'ן יאָר תקט\"ו האָט דער בעש\"ט גערופן זיינע תלמידים מיטן נאָמען: אוהבים, ידידים, חברה אהובים, חברה ידידים, און אַזוי געפינט זיך אין זיינע בריוו, – נאָר די מתנגדים האָבן זיי געגעבן דעם נאָמען חסידים<sup data-n=\"1\">1</sup> – דאָס האָט גענומען בערך איין און צוואַנציג<sup data-n=\"2\">2</sup> יאָר<sup data-n=\"3\">3</sup>.",[["1","1","ראה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ח ע' תקד. לקוטי שיחות ח\"ב ע' 461."],["2","2","הבעש\"ט נתגלה בשנת תצ\"ד."],["3","3","ספר השיחות תש\"א ע' 32."]]],[300010763,"רלט\n\n<b>אַ</b> בעל חוש קען פאַרשטיין און זיך מצייר זיין די אהבת ישראל פון מורנו הבעש\"ט.\nמורנו הבעש\"ט האָט מתפּלל געווען און געמאַכט אַ פּ\"נ ווען איינער איז געווען שרוי בצער, און ניט נאָר במכירו נאָר ער האָט געהערט אַ אידנס קרעכץ אפילו ער איז געווען אין עק וועלט.\nמורנו הבעש\"ט האָט זיך מוסר נפש געווען אויף אהבת ישראל אפילו צו דעם וועלכן ער האָט גאָרניט געקענט<sup data-n=\"1\">4</sup>.",[["1","4","ספר השיחות קייץ ה'ש\"ת ע' 115."]]],[300010764,"רמ\n\n<b>אור</b>\n<b>הצ\"צ</b> סיפר: דער בעש\"ט האָט זייער האָלט געהאַט ליכטיקייט ואמר: אור בגימטריא רז<sup data-n=\"1\">5</sup>, דער וואָס ווייס דעם סוד וואָס אין יעדער זאַך קאָן ליכטיק מאַכן<sup data-n=\"2\">6</sup>.",[["1","5","תקו\"ז תי\"ט (לט, ב). זח\"ג כח, ב ברע\"מ. וראה לעיל סימן לז."],["2","6","ספר השיחות קייץ ה'ש\"ת ע' 174 (הועתק ב\"היום יום\" ו אלול). וממשיך שם: איינמאָל האָבן די תלמידי הבעש\"ט מער ניט געהאַט ווי איין ליכט און דער בעש\"ט האָט באַדאַרפט אַריינקומען, האָבן זיי געהאַט צער, וויסנדיק אַז דער בעש\"ט האָט ליב עס זאָל זיין ליכטיק, און האָבן ניט געוואוסט וואָס צו טאָן. ווען מורנו הבעש\"ט איז אַריין האָט ער געזאָגט באַ אידן באַדאַרף זיין ליכטיק, מיין עבודה איז ליכטיק מאַכן באַ אידן. די תלמידים האָבן געענטפערט אַז זיי האָבן מער ווי איין ליכט ניט געקענט קריגן, האָט מורנו הבעש\"ט געהייסן אַראָפּנעמען פון דאַך די אייז ליכטלעך און זיי אָנצינדן. האָבן די תלמידים אַזוי געטאָן און עס האָט געברענט.\nדער רבי צמח צדק האָט געזונגען בדביקות און געזאָגט: באַ חסידי ותלמידי מורנו הבעש\"ט האָבן אייז ליכטלעך געברענט און געלויכטן און באַ איצטערדיקע חסידים איז פינסטער און קאַלט. וראה ספר השיחות תש\"ו ע' 40 ואילך. לקוטי שיחות חט\"ו ע' 384. אגרות-קודש כ\"ק אדמו\"ר זי\"ע חי\"ט ע' מא. תורת מנחם – התוועדויות תש\"כ ח\"א ע' 154."]]],[300010765,"רמא\n\n<b>אמירת תורה</b>\n<b>הבעש\"ט</b> ז\"ל הי' אומר ד\"ת בל\"א<sup data-n=\"1\">7</sup> ולא בלה\"ק<sup data-n=\"2\">8</sup>.",[["1","7","בל' אשכנז – ולהעיר מקונטרס המענה להצ\"צ (בקונטרס \"הצ\"צ ותנועת ההשכלה\" ע' 48) בנוגע ללשון בנ\"י ברוסיא \"אין יודעים שפת אשכנזית נקי' רק שפה המדוברת\". ובפוקח עורים בתחלתו \"טייטש\". – לקוטי שיחות חלק כא ע' 448 הערה 15. ובספר השיחות תשנ\"ב ח\"א ע' 38 הערה 22 בשוה\"ג: \"בלשון אידיש\" (ולא \"בלשון אשכנז\")."],["2","8","תניא אגה\"ק סכ\"ה (קמא, א).\nובלקוטי שיחות חלק כא שם: וידוע אַז אַזוי איז אויך געווען די הנהגה פון תלמידו הרב המגיד, פון כ\"ק אדמו\"ר הזקן און פון די רביים שלאחריו ביז כ\"ק מו\"ח אדמו\"ר – אַז זיי פלעגן זאָגן חסידות \"בל\"א\", אין אידיש.\nאון נאָכמער: בכדי צו פאַרשטיין די אמיתית הכוונה פון די \"דברי תורה\" פון רבותינו נשיאינו איז ניט מספיק לערנען זיי ווי זיי זיינען איבערגעזעצט געוואָרן אין לשון קודש דורך אַנדערע*, און מען מוז אָנקומען צו די ווערטער וואָס זיי האָבן געזאָגט אין אידיש, כמובן מאגה\"ק שם.\nוראה גם לקוטי שיחות חי\"ד ע' 323. חכ\"ט ע' 295.\n-----שולי הגליון-----\n*) <i>משא\"כ הענינים שנכתבו בלה\"ק ע\"י רבותינו</i>."]]],[300010766,"רמב\n\n<b>זמני ומועדי השנה</b>\n<b>גוט יום טוב</b>\n<b>ביים</b> בעש\"ט איז געווען דער מנהג ר\"ה און מוצאי יוכ\"פ צו זאָגן גוּט יו\"ט (בהברת שורוק), גוט איז בגימטריא ח\"י, ממשיך זיין חיות אין ימים ושנים און אַלע מועדים, און אין אַנדערע ימים טובים איז געווען דער מנהג צו זאָגן גיִט – בהברת חיריק – יו\"ט כיבוד, ד. ה. אַז דאָס וואָס דער יו\"ט האָט זיי מכבד געווען זאָלן זיי געבן אויך צו אַנדערע<sup data-n=\"1\">9</sup>.",[["1","9","ספר השיחות תש\"ה ע' 8. ושם לפנ\"ז: דעם ערשטן ר\"ה וואָס הוד כ\"ק רבינו הזקן איז געווען אין מעזריטש, האָט ער געזאָגט: גוט – בהברת שורוק – יו\"ט, האָבן זיי דאָרטן ביי אים געפרעגט, פון וואַנען ווייסט איר אַז מען דאַרף זאָגן גוט יו\"ט – בשורוק – האָט ער זיי געענטפערט: ביי אונז זאָגט מען אַלע יו\"ט אַזוי.\nהאָבן זיי אים געזאָגט, אַז [ההמשך בפנים]."]]],[300010767,"רמג\n\n<b>אלול – תשרי</b>\n<b>באַ</b> מורנו הבעש\"ט איז געווען אַ סדר מיוחד אין זיינע הנהגות בכל משך השנה, בחול, בשבת ובמועדים.\nדער סדר פון חדש תשרי האָט זיך באַ מורנו הבעש\"ט אָנגעהויבן פון דער הכנה אין חדש אלול בכלל און ימי הסליחות בפרט. די מ' יום וואָס משה רבינו ע\"ה איז געווען בשמים להתפּלל על חטא העגל און לקבל את התורה, וואָס מיט דעם האָט ער מעורר געווען דעם גילוי פון די י\"ג מדות הרחמים, איז עבודתו של מורנו הבעש\"ט געווען אַז דער קו היראה איז אין די דאָזיקע טעג געווען בהתגלות, און פון מוצאי יום הכפּורים ביז נאָך שמחת תורה איז אין עבודת מורנו הבעש\"ט געווען דער קו השמחה בהתגלות<sup data-n=\"1\">10</sup>.",[["1","10","ספר השיחות תש\"ה ס\"ע 127 ואילך."]]],[300010768,"רמד\n\n<b>כשהי'</b> הצמח צדק בן תשע שנים אמר לו רבינו הזקן: קבלתי ממורי (הרב המגיד ממעזריטש) שקבל ממורו (הבעש\"ט) בשם מורו הידוע אשר מיום שני דר\"ח אלול עד יום הכיפּורים, יאמרו בכל יום ויום במשך היום שלשה קאַפּ' תהלים, וביום הכיפּורים שלשים וששה קאַפּ': ט' קודם כל נדרי, ט' קודם השינה, ט' אחר מוסף, ט' אחר נעילה. ומי שלא התחיל ביום ב' דר\"ח, יתחיל באותו יום שהוא עומד בו, ואת אשר החסיר ישלים<sup data-n=\"1\">11</sup>.",[["1","11","\"היום יום\" א אלול. קובץ מכתבים בסו\"ס תהלים אהל יוסף יצחק ע' 208. ומוסיף שם: אבל לא יותר משלשה קאַפּיטלעך בכל יום."]]],[300010769,"רמה\n\n<b>סוכות</b>\n<b>מורנו</b> הבעש\"ט האָט געהאַט אַ געבויטע וואַרעמע סוכה<sup data-n=\"1\">12</sup>.",[["1","12","ספר השיחות תש\"ו ע' 3.\nע\"ד סוכתו של הבעש\"ט – ראה שיחת יום ב' דחג הסוכות תשכ\"ה. תשכ\"ז."]]],[300010770,"רמו\n\n<b>אתה הראת</b>\n<b>דער</b> בעש\"ט פלעגט בעת די הקפות שמע\"צ און שמח\"ת זאָגען אַליין פיל פון די פּסוקים אתה הראת, אמאל פלעגט ער אויך מבאר זיין די פסוקים, און א טייל פון די פסוקים פלעגט ער מכבד זיין צו זאָגן די חברי' קדישא הן שמע\"צ און הן שמח\"ת<sup data-n=\"1\">13</sup>.",[["1","13","ספר השיחות תש\"ד ע' 31."]]],[300010771,"רמז\n\n<b>פסח</b>\n<b>ביים</b> בעש\"ט איז געווען אַ מנהג, אַז אויף פּסח פלעגט מען קויפען אַ סך נייע כלים און צווישן זיי אויך אַ סך כוסות וועלכע מען פלעגט טובל'ען. די כוסות פלעגט מען רופן מיט תורה נעמען, אַ רביעית-כוס וכדומה. דער בעש\"ט פלעגט דאַן אַריינקוקען אין די כלים און פלעגט זאָגען, אַז די כלי זאָל מען שטעלען אויפן טיש און די כלי זאָל מען ניט אַרויפשטעלן אויפן טיש, קיין טעמים אויף דעם פלעגט דער בעש\"ט ניט זאָגען<sup data-n=\"1\">14</sup>.",[["1","14","ספר השיחות תש\"ב ע' 110."]]],[300010772,"רמח\n\n<b>פסח – אחרון של פסח</b>\n<b>דער</b> בעש\"ט האָט גערופן די סעודה פון אחרון של פסח \"משיח'ס סעודה\"<sup data-n=\"1\">15</sup> . . ביי דער דאָזיגער סעודה איז געווען דער מנהג, אַז די טיר איז געווען אָפען פאַר אַלעמען, און אַלע די וועלכע האָבן זיך געפונען אין בעש\"ט'ס הויז האָבן טועם געווען פון די אחש\"פּ סעודה<sup data-n=\"2\">16</sup>.",[["1","15","וממשיך בהשיחה: כשם ווי עס איז פאַראַן נעמען צו די סעודות שבת ויום טוב, עתיקא קדישא זעיר אנפין וכו', אָט אַזוי האָט מען ביים בעש\"ט גערופן די סעודת יום טוב אחרון של פּסח \"משיח'ס סעודה\" [ההמשך בפנים]."],["2","16","ספר השיחות תש\"ב ע' 109 ואילך. ומסיים שם ע' 110: אחרון של פּסח איז משיח'ס סעודה, ווייל אחרון של פּסח איז מאיר דער גילוי הארת משיח צדקנו. וראה \"היום יום\" כב ניסן. ספר השיחות תרפ\"ו ע' 104. תרצ\"ז ע' 236. וש\"נ. לקוטי דיבורים ח\"ג תסא, ב. ספר השיחות תש\"ג ע' 118. וראה גם לקוטי שיחות ח\"ב ע' 545 ואילך. ח\"ד ע' 9-1298. ח\"ו ע' 272 ואילך."]]],[300010773,"רמט\n\n<b>שבועות</b>\n<b>מורנו</b> הבעש\"ט האָט זייער מחבב געווען דעם צווייטן טאָג שבועות. תיכף נאָך די התגלות פון מורנו הבעש\"ט, וואָס דעמאָלט איז געווען די התנהגות בזריזות און עפּ\"י שו\"ע, קבלת שבת בזמנה וכו', איז געווען דער סדר דעם צווייטן טאָג שבועות צו דאַוונען בהשכמה און מאַכן אַ סעודה קלה ביי וועלכע עס זיינען געווען אַ מנין תלמידים כדי צו בענטשן אויף אַ כוס של ברכה. שפּעטער אין מיטן טאָג איז געווען אַ סעודה גדולה און מורנו הבעש\"ט פלעגט אַ סך פאַרברענגען, אַזוי פלעגט זיך מורנו הבעש\"ט מתנהג זיין ביז יום הסתלקותו<sup data-n=\"1\">17</sup>.",[["1","17","ספר השיחות תש\"ד ע' 135. ומוסיף שם:\nדער מעזריטשער מגיד האָט מבאר געווען דעם טעם דערפון, ווייל דאָס איז דאָך די ערשטע 24 שעה ווי אידען האָבען מקבל געווען די תורה, מילא דאַרף מען זייער מחבב זיין דעם טאָג און בפרט לדעת ר' יוסי שבז' בסיון ניתנה התורה, וואָס דאָס איז אַ מעלה נפלאה. – נתבאר בארוכה בלקוטי שיחות ח\"ד ע' 1027 ואילך. לקוטי שיחות ח\"ח ע' 27 הערה 42 בשולי הגליון (הב'). הועתק לקמן בשולי הגליון לסימן שיח)."]]],[300010774,"רנ\n\n<b>מים</b>\n<b>אַז</b> מ'באַגעגענט וואַסער זאָגט דער בעש\"ט: אַז מ'באַגעגענט וואַסער זאָל מען זאָגן, אַז דער בעל שם זאָגט, אַז דאָס איז אַ סימן ברכה<sup data-n=\"1\">18</sup>.",[["1","18","\"היום יום\" כא טבת. נתבאר בשיחת ליל א' דחג הסוכות תשמ\"ג (התוועדויות תשמ\"ג ח\"א ס\"ע 162 ואילך)."]]],[300010775,"רנא\n\n<b>מנגן</b>\n<b>דער</b> בעש\"ט אַליין איז געווען אַ גרייסער מנגן און האָט גיהאַט אַ זעלטענע שטימע וואָס ער – דער בעש\"ט – פלעגט קאָנען אומבאַייטין די שטימע אין גאָר פערשידענע קולות – באַ די זינגער און חזנים איז פראַן אויף דעם אַ נאָמען ווי עס הייסט אַזאַ שטימע – און האָבענדיק אַ גרייסין חוש אין נגינה האָט ער אָפט געזונגען, דער זינגען איז אין מורנו הבעש\"ט [אַ] דרך א[ין] עבודה<sup data-n=\"1\">19</sup>, נגינה רירט אָן נפש, בריינגט צו שפיכת הנפש<sup data-n=\"2\">20</sup>.",[["1","19","ראה לעיל סימן ריט."],["2","20","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' ריט."]]],[300010776,"רנב\n\n<b>מנהגים</b>\n<b>די</b> מנהגים וואָס מורנו הבעש\"ט האָט זיך נוהג געווען זיינען הלכה למשה מסיני.\nווען משה רבינו איז געגאַנגען מיט די לוחות איז ער געגאַנגען דורך די ד' עולמות אצילות בריאה יצירה עשי' הרוחניות און זיי געבראַכט אין עולם התחתון, איז די ספירות און מלאכים וואָס בכל עולם ועולם האָבן געשיינקט מתנות צו משה רבינו מדות און מנהגים כלליים ופּרטיים.\nגעוויסע מנהגים האָט מורנו הבעש\"ט קובע געווען באַ אידן, און ער האָט געהאַט מסירות נפש אַז די מנהגים וואָס זיינען שייך לכלל ישראל זאָלן זיך איין פלאַנצן אין אַלע חסידישע הייזער לדורותיהם און מיט די מנהגים זאָלן אידן מקבל זיין משיח צדקנו<sup data-n=\"1\">21</sup>.",[["1","21","ספר השיחות תש\"ח ע' 231."]]],[300010777,"רנג\n\n<b>אין</b> דער תחלת ההתגלות פון מורנו הבעש\"ט האָבן די תלמידי הבעש\"ט שטאַרק מהרהר געווען צי זיי דאַרפן אָפּהיטן די מנהגי מורם ורבם הבעש\"ט.\nאָט דער הרהור וואָס די חבריא קדישא האָט מהרהר געווען איז דאָס ניט ח\"ו בכלל המאמר<sup data-n=\"1\">22</sup> המהרהר אחר רבו, נאָר זיי האָבן זיך בודק געווען צי זיי זיינען שוין אין דער דרגא וואָס זיי קאָנען זיך מתנהג זיין אין דעם דרך הקדש פון בעש\"ט און עס זאָל ניט הייסן נאָכטאָן ווייל דער רבי טוט אַזוי.\nדי מקושרי הבעש\"ט מאנשים פּשוטים האָבן גלייך מקבל געווען דעם בעש\"ט'ס מנהגים אין אַ בפּועל ממש, אָן קיינע חקירות און גריבלען זיך, צי זיי האַלטן באַ דער דרגא אַז זיי דאַרפן זיך מתנהג זיין ווי דער בעש\"ט פירט זיך צי ניט. זיי האָבן געוואוסט אַז דער בעש\"ט פירט זיך אַזוי האָבן זיי זיך אויך אַזוי מתנהג געווען.\nאָט דאָס איז דער יתרון על פּי שיטת מורנו הבעש\"ט אין דער עבודה פון אנשים פּשוטים וואָס טוען אַלע עניני המצות ניט על פּי הטעם נאָר מיט קבלת עול פון אמונה. אָבער צדיקים בעלי עבודה, וואָס עבודתם בתורה ומצות איז מתוך ידיעה והכרה, באַדאַרפן פריער וויסן דעם ענין על בוריו און האַלטן באַ דער מדריגה. דערפאַר האָבן די חבריא קדישא אויף יעדער מנהג פון מורם ורבם הבעש\"ט חוקר געווען און זיך מתבונן געווען צי זיינען זיי שוים אין דער דרגא וואָס זיי דאַרפן אויך אַזוי זיך נוהג זיין<sup data-n=\"2\">23</sup>.",[["1","22","סנהדרין ק, ב."],["2","23","ספר השיחות קייץ ה'ש\"ת ע' 82."]]],[300010778,"רנד\n\n<b>מקוה</b>\n<b>בשם</b> מורנו הבעש\"ט אַז ערב שבת, ערב יום טוב ווי אויך שבת ויום טוב אין דער פרי גייט מען אין מקוה<sup data-n=\"1\">24</sup>.",[["1","24","ספר השיחות תש\"ב ע' 19. ושם לפנ\"ז: חסידים זיינען זיך נוהג טובל זיין זיך קודם תפלת שחרית די\"ט כסלו כמנהג המקובל מחסידים הראשונים [ההמשך בפנים. וממשיך שם:] די טבילה במקוה שבת פאַרן דאַוונען האָבן חסידים הראשונים געהאַלטן פאַר אַ סגולה צו דאַוונען בהתבוננות והתעוררות של דבקות."]]],[300010779,"רנה\n\n<b>נסיעות</b>\n<b>מההפרש</b> בין הנהגת הבעש\"ט להנהגת המגיד, כי הבעש\"ט הי' עסוק בנסיעות שונות, והמגיד ישב בביתו<sup data-n=\"1\">25</sup>.",[["1","25","\"היום יום\" ג כסלו (מאגרות-קודש אדמו\"ר מהוריי\"צ ח\"ג ע' תג). וראה שיחת יום ב' דחג השבועות תש\"מ."]]],[300010780,"רנו\n\n<b>עבודתו</b> של הבעש\"ט היתה להמשיך אלקות מלמעלה למטה. ולכן בהיותו נסתר הי' מסבב מעיר לעיר ומכפר לכפר, וגם לאחר התגלותו עשה כמה מסעות – בכדי לגלות ולפרסם אלקותו ית' גם לאנשים פשוטים, ועד שהי' מקרב גם אינם יהודים ופחותי הערך שבהם [כידוע שהראה קירוב ואהבה לגזלנים], ויתירה מזו: שאהבתו היתה גם לחי וצומח<sup data-n=\"1\">26</sup>.",[["1","26","שיחת יום ב' דחג הסוכות תשכ\"ג."]]],[300010781,"רנז\n\n<b>אין</b> דער תחלת ההתגלות פון מורנו הבעל שם טוב פלעגט ער מאַכן אָפטע נסיעות אין פאַרשידענע ערטער, גרויסע שטעט און קליינע שטעטלעך און אין פאַרשידענע ישובים, דערפער און קרעטשמעס.\nדעם בעש\"ט'ס נסיעות זיינען געווען צוליב דריי אָנגעלעגענהייטן: א) פּדיון שבוים. די ישובניקעס און קרעטשמערס וואָס האָבן ניט געהאַט מיט וואָס צו באַצאָלן די ארענדע געלדער צו די בעלי אחוזות, און די בעלי אחוזות פלעגן זיי פאַרהאַלטן. ב) מעורר זיין אידן צו לימוד התורה און אהבת ישראל. ג) מגלה זיין פאַר בני תורה פּנימיות התורה<sup data-n=\"1\">27</sup>.",[["1","27","ספר השיחות קייץ ה'ש\"ת ע' 83."]]],[300010782,"רנח\n\n<b>כ\"ק</b> מו\"ח אדמו\"ר האָט אַמאָל געזאָגט<sup data-n=\"1\">28</sup>, אַז די נפקא מינה פון דעם בעל שם טוב מיט די גדולים אין נגלה דתורה וואָס זיינען געווען דעמאָלט, איז דאָס וואָס ביי די גדולים פון נגלה דתורה איז געווען דער סדר אַז מען פלעגט קומען צו זיי לערנען, דאַקעגן דער בעל שם טוב מיט זיינע תלמידים פלעגן ניט וואַרטן אַז מען זאָל קומען צו זיי, נאָר זיי פלעגן פאָרן אין שטעט און מושבים וואו אידן געפינען זיך.\n– עס איז פאַראַן אַ ביאור פון אַלטן רבי'ן און פון מיטעלן רבי'ן<sup data-n=\"2\">29</sup> אויף דער נפקא מינה פון די גדולים בנגלה דתורה ביז דעם בעש\"ט. דאָס איז שוין געדרוקט<sup data-n=\"3\">30</sup>.",[["1","28","ראה ספר השיחות שם ע' 84. וראה אגרות-קודש כ\"ק אדמו\"ר זי\"ע ח\"ד ע' תסג."],["2","29","ראה ספר השיחות קייץ ה'ש\"ת שם. וראה ספר השיחות תש\"ג ע' 100."],["3","30","לקוטי שיחות חלק ב ע' 367."]]],[300010783,"רנט\n\n<b>סעודות הבעל שם טוב</b>\n<b>ביי</b> מורנו הבעש\"ט זיינען געווען סעודות ברבים און סעודות ביחידות, מען מיינט ניט פאַר זיך. נאָר אַז די מסובים זיינען געווען פון די נבחרים און דער עולם איז געשטאַנען אַרום. די מסובים ביים טיש האָבן געמוזט קענען כתבי האריז\"ל<sup data-n=\"1\">31</sup>.",[["1","31","ספר השיחות תש\"ד ע' 19."]]],[300010784,"רס\n\n<b>ספירת העומר</b>\n<b>מורנו</b> הבעש\"ט און הרב המגיד איז געווען דרכם בקדש, אַז ספירת העומר פלעגט יעדער פון זיי, בזמן נשיאותו, סופר זיין בתור עובר לפני התיבה בבית הכנסת<sup data-n=\"1\">32</sup>.",[["1","32","ספר השיחות תש\"ו ע' 20."]]],[300010785,"רסא\n\n<b>\"קולות\"</b>\n<b>ענין</b> המעשה דר' וואָלף קיצעס תלמיד הבעש\"ט ז\"ל שלא אכל מבשר שלו שלא הוכשר בעיניו המליחה עצהיו\"ט והי' מחמיר ע\"ע<sup data-n=\"1\">33</sup>. ולכאו' יתמה מאד שיוכל להרהר אחר רבו ח\"ו כו'. אך הטעם בזה שמגדולים בהנהגתם אין למדין אלינו בדינים הנגלות לנו באו\"ה כשר ופסול. כי נודע מה שהעיד הה\"מ דמעזריטש ז\"ל עליו שאם הי' בימי התנאים הי' פלאי ממיוחדים שבתנאים כי רוב תנאים בבריאה<sup data-n=\"2\">34</sup> כי משנה ביצירה<sup data-n=\"3\">35</sup> והתנא בעל משנה מבריאה ולו הי' נשמה מאצי' כמו המיוחדים שבתנאים, וכמש\"א בעצמו שמי שאין לו נשמה מאצי' אינו יכול להשיג רק עד בחי' חכ' בלבד כי בכל הנפשות יתואר ד\"מ התפיסה והשגה בבחי' חכ' שבנפש לבד שזו בהרגשה ולא ביותר כי החכ' מאין תמצא<sup data-n=\"4\">36</sup> ולא נמצא בו פרצוף אדם שלמטה בהארת גילוי יותר. אך מי שנשמתו שלימה מבחי' אצי' יוכל להשיג השגות שלמעלה מן החכ' פי' שיכול לשער בנפשו ד\"מ במדריגות שלמעלה מן החכ' פי' יש לו בהן הרגשה וזהו המופת כי נשמתו שלימה וד\"ל. וי\"א שיש לו שייכות בשרש דרשב\"י שאמר ברירנא לי דוכתאי בדוכתי' דאחי' השילוני<sup data-n=\"5\">37</sup> כו'. ולזאת לא למד ממנו בהוראה לעצמו והחמיר ביותר ע\"ע. והיינו כי כללות התורה הנגלות לנו באיסור והיתר כשר ופסול ולהבדיל בין הטמא<sup data-n=\"6\">38</sup> כו' הכוונה בזה הוא בירורים לברר האוכל מפסולת הטוב מהרע שהכשר והטהור והמותר יש להן תקנה ועלי' בקדושה משא\"כ הטמא והפסול והאסור כידוע. אך ענין ס' הבירורים משתנה לפי העולם והמדרגה ההוא כי אינם דומים הבירורים דבריאה ליצי' ודיצי' לעשי' בב' אופנים הן בסדר הדרגתן מלמעלמ\"ט והן מלמטלמ\"ע כמבו' במ\"א ע\"פ<sup data-n=\"7\">39</sup> בני אמי נחרו בי פי' מלמעלמ\"ט בהשפעה היורד מאצי' לבריאה מתברר המובחר שבה להתפשט בבריאה בכלים דבריאה המוכשרים לקבלה והפסולת שבה [מחנה דבריאה ליצי' כי ביצירה אפשר לה להיות נחשב לטוב ומובחר עד סוף העשי', והפסולת הגסה] נדחית חוץ למחנה דקדושה בקליפה דעשי' ואין לה תקנה עד שיבולע המות כו'. ומלמטלמ\"ע הוא בהיפוך בהעלאת המ\"ן דמתבררים אזי המובחר דעשי' כשעולה ליצי' נחשב לפסולת ומתברר ממנה המובחר דמובחר וכן בבריאה בירור אחר בירור כו'. ולפי שזה בב' בחי' אופנים אלו יש שינוי באופן הבירור במעלתו ומדריגתו בכל עולם לפ\"ע בדקות המעלה ובסגנון אחר. לכן נק' בשם הלכה הליכות עולם לו<sup data-n=\"8\">40</sup> שהוא הילוך והמשכה מלמעלמ\"ט מעולם ועד עולם וכן מלמטלמ\"ע הליכות עולם לו המתבררים ילכו מחיל אל חיל<sup data-n=\"9\">41</sup> כו'. ולכך מי ששרש נשמתו מעולם עליון אופני הבירורים שלו באופן אחר אם להקל או להחמיר. ובד\"כ המיקל שבתנאים שרשו מעולם העליון ששם אין הפסד והיזק מיניקת החיצונים כ\"כ כמו למטה שמצטרכים לגדור ביותר וכנראה מניקב<sup data-n=\"10\">42</sup> הריאה משהו טרפה וגם הסירכא טריפה לגבינו דבעקביים אנחנו כו' ורש\"א עד שתינקב לבית הסמפונות דבמקומו ושרשו אין הריאה נטרפה בנקיבה עד שתינקב לבית הסמפונות, ולכן אמר כן כפי מקומו, ומ\"מ אין הלכה כמותו כי אחרי רבים להטות<sup data-n=\"11\">43</sup> כתי' כי רוב הדור מעולם שלמטה ושם הלכה דבירורים באופן אחר. וע\"פ רוב הנשמות הגבוהות דמאד נעלה שבתנאים אין הלכה כמותו כמו ר\"מ ור\"א ורשב\"י חוץ ממוקצה דהלכה כמותו<sup data-n=\"12\">44</sup> כו' כמבואר במ\"א. ובזה יתורץ מה שר' וואָלף החמיר ע\"ע במליחה ולא רצה לאכול אף שהי' תלמידו כו' וד\"ל<sup data-n=\"13\">45</sup>.",[["1","33","ראה הנסמן בספר מגדל עז (כפ\"ח, תש\"מ) ע' שעה הערה 34."],["2","34","ראה גם הנסמן שם ע' שסז-שסח."],["3","35","תקו\"ז בהקדמה (יד, א). ע\"ח שער ק\"נ פ\"ה. שער המצוות וטעמי המצוות פ' ואתחנן. פרי עץ חיים שער הנהגת הלימוד."],["4","36","איוב כח, יב."],["5","37","ראה זח\"ג שט, א. זוהר חדש יט, א – הובא בנצו\"א לזח\"ג רפז, ב."],["6","38","שמיני יא, מז."],["7","39","שה\"ש א, ו."],["8","40","חבקוק ג, ו."],["9","41","תהלים פד, ח."],["10","42","חולין מב, א."],["11","43","משפטים כג, ב."],["12","44","ראה שבת קנו, ב."],["13","45","מאה שערים ע' 78. מאמרי אדמו\"ר הזקן הקצרים ע' תקלא ואילך."]]],[300010786,"רסב\n\n<b>קידוש</b>\n<b>דעם</b> בעש\"ט'ס קידוש איז דאָך אַ קידוש ביז איבער אַ יאָר ערב ראש השנה, וואָרום וואָס איז דעם בעש\"ט'ס קידוש, אויף לקדש את העולם<sup data-n=\"1\">46</sup>.",[["1","46","ספר השיחות תרפ\"ו ע' 104 ואילך. ושם לפנ\"ז: אצל הבעש\"ט הי' נהוג קידוש באחרון של פסח . . סיפר אחד שבמקומם אצל החסידים דפולין ג\"כ נהוג הקידוש והוא נמשך עד השעה השמינית בלילה. ואמר כ\"ק אדמו\"ר: מערניט ביז אַכט אַזייגער באַיי דער נאַכט? [ההמשך בפנים]."]]],[300010787,"רסג\n\n<b>קירב אנשים פשוטים</b>\n<b>הבעש\"ט</b> קירב מאד את אנשים פשוטים, והרב המגיד אמר כי לו ידע הבעש\"ט בהיותו בעלמא דין מה שפועל בקירובו את אנשים פשוטים כמו שיודע עתה, הי' הקירוב שלו באופן אחר. ובאמת הי' הקירוב של הבעש\"ט לאנשים פשוטים באופן שלמעלה מהשכל<sup data-n=\"1\">47</sup>.",[["1","47","ספר השיחות תרצ\"ו ע' 148."]]],[300010788,"רסד\n\n<b>מורנו</b> הבעש\"ט הי' מייקר ומחבב את האנשים הפשוטים ולפעמים הי' נותן להם יתרון גם על בני תורה גדולים באמרו כי הידיעה והשכל [מכהה] את הרצון הפנימי והעצמי שישנו בכל אחד מישראל לאלקות ומכסה עליו, לא כן האנשים הפשוטים הנה אמונתם הפשוטה בה' ויראתם את ה' חיבתם לתורה וזהירותם בקיום מצות מעשיות תפלתם ואמירתם תהלים והכל בתום לב, הנה לא זו בלבד שאינו מכסה על הרצון העצמי והפנימי לאלקות אלא אדרבא גורם התגלותו והתפשטותו וזה יקר וחביב מאד מאד למעלה, ומורנו הבעש\"ט נ\"ע הי' שולח את תלמידיו הק'<sup data-n=\"1\">48</sup> לכמה וכמה מהאנשים הפשוטים – מקושריו – היושבים בכפרים וישובים להתלמד מהם תמימות דיראת שמים, מדות טובות ומדת האמונה והבטחון<sup data-n=\"2\">49</sup>.",[["1","48","ראה גם לקמן סימן שסב."],["2","49","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ו ע' שצט."]]],[300010789,"רסה\n\n<b>תהלים המתאים למספר שנותיו</b>\n<b>וידוע</b> המנהג שקיבל אדמו\"ר הזקן . . . רבו בשם רבו מורנו הבעש\"ט, לאמר הקאַפּיטל תהלים המתאים למספר שנותיו<sup data-n=\"1\">50</sup>, אחר תפלת שחרית קודם אמירת השיעור תהלים בכל יום כנהוג<sup data-n=\"2\">51</sup>.",[["1","50","פירושו כשנמלאו לו, לדוגמא, יג שנה מתחיל קאַפּיטל יד."],["2","51","קובץ מכתבים לתהלים בסו\"ס תהלים אהל יוסף יצחק ע' 214. אגרות-קודש אדמו\"ר מהוריי\"צ ח\"י ע' נג. וראה \"מאמר מאדמו\"ר שנ\"ז ז\"ל לומר הקאַפּיטל שלו\" – ד\"ה דוד מלך ישראל – נדפס במאמרי אדמו\"ר הזקן הקצרים ע' שמא. ד\"ה הנ\"ל תשכ\"א (ספר המאמרים תשכ\"א ע' 230 ואילך). אגרות-קודש אדמו\"ר מהוריי\"צ ח\"א ע' לא. ספר השיחות תש\"ד ע' 162."]]],[300010790,"רסו\n\n<b>תפילה</b>\n<b>מורנו</b> הבעש\"ט נ\"ע בעת תפילתו הי' רגיל לומר, \"אף, אף, אף\"<sup data-n=\"1\">52</sup>.",[["1","52","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ב ע' שסג. ושם לפנ\"ז: בהמלשינות הידועה הלשינו לאמר כי מורנו הבעש\"ט [ההמשך בפנים. וממשיך שם:] ופירש המלשין כי התפלל אשר יוריד השי\"ת אף וחרון על הממשלה, ואשר ככה נוהג גם רבינו הגדול.\nוכשנשאל רבינו הגדול בטאיינע סאויעט על דבר זה הי' לו צער גדול, מאשר הי' צריך לגלות כוונתו של מורנו הבעש\"ט נ\"ע ולפרש דרכיו לפני השרים הא\"י, אמנם הי' באפשרו לדחותם בכמה תשובות, אך לא רצה להיות נפרד גם מתנועה אחת של מורנו הבעש\"ט נ\"ע גם לשעה קלה אף למראית עין. ובלקו\"ש חכ\"ה ע' 265 הערה 62 בשולי הגליון: \". . . הבעש\"ט הי' רגיל לומר בתפילתו אוף (קוף) . . ושזוהי דרגת הביטול דלמטה מ\"תולעת\" בהיותו בע\"ח דומה לאדם\". וראה \"רשימות\" חוברת ח ע' 13. ספר השיחות תרצ\"א ס\"ע 235 ואילך). בית רבי ח\"א פט\"ז (לא, ב) ובהערה א שם."]]],[300010791,"רסז\n\n<b>ענין</b> לשון הקודש אשר נשתבש שאין שום אדם שיוכל לדבר בו כמו שהוא בכל האותיות ודקדוקיהם כו' וחלוקיהם בזה שמדינה זו מדברת אותיות אלו בטוב ואותיו' אלו הם משתבשי' ומדינה אחרת להפוך אמנם שיהי' בתכלי' השלימות אין שום מדינה כי גם הבעש\"ט והאריז\"ל לא היו יכולים כל הלשון כמו שהוא כ\"א היו משתבשי' בלשונם וא\"כ לכאורה אינו מובן האיך הי' הבעש\"ט או האריז\"ל מתפלל בשיבוש ח\"ו, אך הענין הוא להיות כי למעלה אינם אותיות גשמיי' ח\"ו כ\"א רוחניי' מאד נעלה מתהווים ונוצצים בכוונתם בתפלה בודאי הי' האותיו' למעלה כתקונם (כי לא הפה והלשון הוא העושה האותיו' וד\"ל) כ\"א כשבא למטה בבחי' גופי' משתבשי' בכאו\"א לפי הכלי שלו<sup data-n=\"1\">53</sup>.",[["1","53","מאמרי אדמו\"ר הזקן תק\"ע ע' נג. ומסיים שם: וכמו בהמגיד של ב\"י שאמר לו פסוק א' שלא כמו שנכתב ובודאי למעלה אין שום שיבוש ח\"ו כ\"א בהכלי שלו הי' נצרך להתגלות אז בגילוי כזה דוקא הגם שגם הב\"י הי' בקי בכל התנ\"ך עכ\"ז בעת זו היה נצרך לגילוי זה דוקא וד\"ל. וראה גם \"סיפורים נוראים\" להר\"י קאדאנער בתחילתו."]]],[300010792,"רסח\n\n<b>סדר הוספה על בית החיים</b><sup data-n=\"1\">54</sup>\n<b>זאת</b> העתקתי מכ\"ק אדמו\"ר הה\"מ והוא מועתק מהבעש\"ט זצלה\"ה זיע\"א וז\"ל הזהב מהבעש\"ט אם צריכים להוסיף על ביה\"ק ר\"ל ככה יתנהגו מקיפים המקום שרוצה להוסיף בשבע הקפות עם עשרה אנשים לא פחות בכל הקפה יאמרו בארבעה קרנות מקום ההוספה בתהלים קאַפּיטול ק\"ג ק\"ד ובישעי' קאַפּיט' מ\"ב מתחיל שירו לד' שיר חדש וגו' ובכל הקפה יתחילו מצד קרן דרומית מזרחית ותיכף בצד אותו קרן יאמר[ו] בתהלים קאַפּיט' ק\"ב ומאותו קרן יקיפו ויאמרו ויהי נועם דרך הקפה עד שיגיעו לקרן מזרחית צפונית ובצד אותו קרן יאמרו קאַפּיט' ק\"ג בתהלים ומאותו קרן יקיפו ויאמרו דרך הקפה ויהי נועם עד שיגיעו לקרן צפונית מערבית ובצד אותו קרן יאמרו בתהלים קאַפּיט' ק\"ד ומאותו קרן יקיפו ויאמרו דרך הקפה ויהי נועם עד שיגיעו לקרן מערבית דרומית ובצד אותו קרן יאמרו בישעי' קאַפּיטול מ\"ב שירו לד' שיר חדש וכו' ובגמר הקפה ראשונה יאמרו אנא בכח ויכוונו השם הראשון בפסוק הראשון וככה יתנהגו בכל הקפה מהשבע הקפות. ואחר גמר כל ההקפות מהשבע הקפות יאמרו אנא בכח ויכוונו שם אחד מהשבע שמות עד שיגמרו השבע שמות בשבע הקפות וכשיתחילו לעשות מחיצות למקום ההוספה לא יתחילו מרוח צפונית וגם לא יתחילו לגדר ברוח צפונית גם לא יתחילו מכהן. ויה\"ר שיבולע המות לנצח במהרה בימינו אמן סלה.\n**********",[["1","54","מבוך כת\"י הכולל מאמרים, שיחות ומכתבים מרבותינו נשיאינו."]]],[300010793,"רסט\n\n<b>אמרות קודש</b>\n<b>מרבותינו נשיאנו הקדושים</b>\n<b>ע\"ד הבעל שם טוב ושיטתו</b>\n<b>חיי הבעל שם טוב</b>\n<b>לידתו</b>\n<b>דעם</b> רבי'נס<sup data-n=\"1\">1</sup> עלטערן<sup data-n=\"2\">2</sup> זיינען געווען עקרים מלידה, זיי האָבן געוואוינט אויף אַ ישוב און האָבן געהאַט פרנסה בשופי, און פון זיין פרנסה פלעגט ער נאָר פאַרנוצן אַ קליינער טייל, און די איבעריקע פלעגט ער אויסגעבן אויף הכנסת אורחים, יעדן שבת פלעגן באַ אים עסן 20-30 אורחים.\nאיין מאָל שבת בייטאָג איז נאָך דער צווייטער סעודה געקומען אַן אורח, כאָטש עס איז געווען אַ וואונדער, דאָס אין אַזאַ קליינעם ישוב זאָל קומען אַן אורח אין מיטן שבת, דאָך האָט ער באַ אים ניט געפרעגט ווער ער איז און פון וואַנעט ער קומט, ער האָט אים בלויז געפרעגט צי האָט ער געמאַכט קידוש, און אַז ער האָט אים געענטפערט אַז ניט, האָט ער אים געגעבן קידוש מאַכן, ווי אויך עסן, און האָט אים מכבד געווען ווי אַלע איבעריקע געסט.\nדי אורחים צוזעענדיג דאָס, האָבן זיי דעם בעל הבית מצער ומקנטר געווען, סטייטש אַזאַ וועלכער איז זיכער געקומען אום שבת מחוץ לתחום גייט ער אים מכבד זיין? אברהם אבינו וואָס איז געווען דער גרויסער מכניס אורח שטייט אין מדרש<sup data-n=\"3\">3</sup> אַז נאָכן עסן פלעגט ער הייסן די אורחים בענטשן, און אַז זיי האָבן ניט געוואָלט, האָט ער זיי איינג געמאַכט.\nדעם בעל הבית איז געוואָרן איינג פון זייערע טענות, איז ער אַריין אין צימער און האָט געוויינט, ער האָט זיך גלייך דערמאָנט, אַז דורך זיין אַוועקגיין וועט דאָך ווערן שווער און איינג דעם אורח, האָט ער זיך צוריקגעקערט צום אורח, און האָט אים מכבד געווען נאָך מער ווי פריער, אַזוי איז געווען באַ שלש סעודות.\nער האָט זיך געפירט אַז אַלע אורחים וואָס פלעגן באַ אים זיין שבת פלעגן בלייבן ביי אים ביז זונטאָג נאָך מיטאָג. אַזוי האָט ער זיך געפירט מיט דעם אורח, ער האָט אים געגעבן אַ גוטן געלעגער, זונטאָג נאָך מיטאָג אַז דער אורח האָט געדאַרפט אַוועקגיין האָט ער אים באַגלייט, אין וועג רופט זיך צו אים אָפּ דער אורח אַז ער איז אלי' הנביא, און אַז מן השמים האָט מען אים געשיקט פּרואוון אים ווי אַזוי וועט ער אים מכניס אורח זיין, און ער האָט אים געזאָגט אַז ער איז בייגעשטאַנען דעם נסיון, און פאַר זיין הכנסת אורחים וועט ער זוכה זיין צו האָבן אַ זון, און האָט אים געזאָגט איך וועל דיר זאָגן אַ תורה, און אַז דער זון וואָס דו וועסט האָבן וועט אַלט זיין צוויי און אַ האַלב יאָר זאָלסטו אים איבערזאָגן די תורה: הוי' אלקים אלקי השמים והארץ ממנו תירא ומשום בריאה בעולם לא תירא מבלעדו ית', און דער אורח האָט זיך מיט אים געזעגנט. אין אַ צייט אַרום איז ביי דעם אידן געבאָרן געוואָרן דער בעל שם טוב<sup data-n=\"4\">4</sup>.",[["1","1","הבעש\"ט."],["2","2","ר' אליעזר ושרה."],["3","3","ב\"ר פמ\"ט, ד."],["4","4","ספר השיחות תרצ\"ז ע' 161 ואילך. וראה ספר השיחות תש\"א ע' 43 ואילך."]]],[300010794,"ער\n\n<b>חסידי</b> כ\"ק הרה\"ח רמ\"מ מוויטעבסק ששמעו מפי קדשו אשר שנת תנ\"ח הנה סימנו נח\"ת וחת\"ן אשר בשנה ההיא נולד מורנו הבעש\"ט. חד משמי שמיא נח\"ת שזה חת\"ן נחות דרגא, ובזה נחת רוח למטה שנחת רוח חדשה בעולם זה, כלומר דרך בעבודה איך לעשות נחת רוח לו ית'<sup data-n=\"1\">5</sup>.",[["1","5","לקוטי דיבורים ח\"א לא, ב."]]],[300010795,"רעא\n\n<b>מורנו</b> הבעש\"ט איז געבוירן געוואָרן אין יאָר תנ\"ח און דער סימן איז נח\"ת. ער האט געברענגט נחת צו הקב\"ה פון יעדן איד, אפילו פון אנשים פּשוטים. ס'איז ידוע די נסיעות וואָס דער בעש\"ט פלעגט אַרומפאָרן אין די ישובים און דערפער, צונויפרופן אנשים נשים וטף און זיי פרעגן וואָס זיי מאַכן אין געזונט, אין פּרנסה א. ד. ג. און פלעגט אַזוי מאַכן, אַז זיי זאָלן ענטפערן, געלויבט איז דער אויבערשטער, וואָס דורכדעם האָט ער אַרויסגערופן די אמונה פּשוטה ביי אַלע אידן און האָט גורם געווען אַ גרויסן נחת רוח למעלה<sup data-n=\"1\">6</sup>.",[["1","6","ספר השיחות תש\"ד ע' 163. וראה ספר השיחות תש\"ג ע' 167 ואילך שסיפר הבעש\"ט: אין דעם יום ההולדת שלי ח\"י אלול תע\"ד בין איך געווען אין אַ קליינעם ישוב. דער אַרענדאַר פון דער קרעטשמע איז געווען זייער אַ פּראָסטער מענש, קוים געקענט דאַוונען, אָבער די טייטש פון די ווערטער האָט ער ניט געוואוסט. ער איז געווען אַ גרויסער ירא שמים און איז געווען מורגל צו זאָגען אויף יעדער זאַך און אין יעדער צייט \"ברוך הוא ומבורך לעולם ועד\" און די אַרענדאַרקע פלעגט כסדר זאָגן \"געלויבט זאָל זיין זיין הייליגער נאָמען\".\nאין דעם טאָג בין איך דאַן געגאַנגען מתבודד זיין זיך אין פעלד, ווי דער סדר מסודר פון קדמונים איז*, אַז אין יום ההולדת זאָל מען זיין אַ געוויסן זמן אין התבודדות. אַז איך האָב זיך מתבודד געווען האָב איך געזאָגט מזמורי תהלים און האָב זיך עוסק געווען אין יחודי שמות הקדושים.\nזייענדיג פערטיפט אין דעם האָב איך ניט געפילט וואָס אַרום מיר טוט זיך. פּלוצים האָב איך דערזעהן אליהו הנביא און אַ שמייכעל איז געווען אויף זיינע ליפּען. איך בין געווען זייער פאַרוואונדערט וואָס זייענדיג אַליין האָב איך זוכה געווען צו גילוי אליהו. באַ הצדיק ר' מאיר, אויך זייענדיג מיט די צדיקים הנסתרים, האָב איך זוכה געווען צו זעהען אליהו הנביא, אָבער זייענדיג גאָר אַליין זוכה זיין צו גילוי אליהו, איז דאָס באַ מיר געווען דעם ערשטן מאָל, בין איך געווען פאַרוואונדערט. אויך האָב איך ניט געקענט אויסטייטשען אליהו הנביא'ס שמייכעל.\nאליהו הנביא זאָגט מיר: דו מאַטערסט זיך בעמל רב אויף צו מכוון זיין די יחודי שמות הקדושים, וואָס זיינען יוצא פון די פּסוקי תהלים וואָס דוד מלך ישראל האָט מסדר געווען, און אהרן שלמה דער אַרענדאַר און זלאַטע רבקה די אַרענדאַרקע ווייסן גאָר נישט די יחודי שמות הקדושים וואָס זיינען יוצא פון דעם \"ברוך הוא ומבורך לעולם ועד\" וואָס דער אַרענדאַר זאָגט און \"געלויבט זאָל זיין זיין הייליגער נאָמען\" וואָס די אַרענדאַרקע זאָגט און די יחודים רעש'ן אין אַלע עולמות, מער ווי די יחודי שמות וועלכע די צדיקים הגדולים זיינען מכוון.\nאליהו הנביא האָט מיר מבאר געווען, דעם גודל הנחת רוח כביכול אין הימל פון דעם שבח ותהלה וואָס אנשים נשים וטף זיינען מהלל ומשבח את הקב\"ה, און בפרט אַז דער הילול ושבח קומט פון פּשוטע מענשען, און בפרטי פרטיות אַז דער הילול ושבח איז אין אַן אופן תמידי – זיינען זיי דאָך תמיד דבוק בהשי\"ת באמונה טהורה ובתמימות הלב.\nפון דאַן האָב איך זיך גענומען אַ דרך אין עבודה – זעהען מאַכען אַז אידן אנשים נשים וטף זאָלן זאָגן לויב ווערטער להשי\"ת, דורך דעם וואָס איך פלעג באַ זיי פאַנאַנדערפרעגן אויף זייער מצב הבריאות, אויף דעם מצב הבריאות פון זייערע קינדער און אויף זייער מצב הפּרנסה, און אַלע פלעגן ענטפערן מיט פאַרשיידענע ג-ט לויבונגס אויסשפּראַכן, יעדער אויף זיין שטייגער**.\nאַ משך פון יאָרן האָב איך אַליין דורכגעפירט דעם דרך עבודה, און אויף אַ געוויסער אסיפה האָט מען אָנגענומען דעם דרך העבודה, וואָס דאָס איז געוואָרן אַ מבוא צו מפרסם זיין די עבודה פון אהבת ישראל.\nוראה לקוטי דיבורים ח\"ג שפה, א. ספר השיחות תש\"א ע' 3-152:\nהיינט, י\"ח אלול, איז דער צוויי הונדערט דריי און פערציגסטער יאָר טאָג, דער יום הזכרון פון דעם אַלגעמיין אידישען ליכטיג הייליגען טאָג, וואָס השי\"ת האָט געטאָן זיך אַליין דעם גרויסען נח\"ת, און אויך דעם כלל ישראל אַ גרויסען נח\"ת, וואָס ער – השי\"ת – האָט מזכה געווען דער אידישער וועלט\nמיט דער גרויסער ליכט זייל – עמוד האור – און דעם גרויסען געטליכען ברען זייל – עמוד האש – דאָס איז די גרויסע הייליגע נשמה פון מורנו איש האלקים כבוד קדושת שם תפארתו מרנא ורבנא ישראל בר' אליעזר נ\"ע בעל שם טוב.\nאין יאָהר תנ\"ח – וואָס איז באַצייכענט באַ דער אַלגעמיינער חסידישער וועלט מיט דעם וואָרט נח\"ת – דער אַכצענטער אלול איז דער אַלגעמיינער אידישער יהי אור, דער געבורטס טאָג פון מורנו הבעל שם טוב.\nי\"ח אלול איז אַ גימטריא וואָרט וואָס אַלע האָבען אים זייער גערן. אויך אפילו די וועלכע זיינען געגען ראשי תיבות און גימטריאות, האָבן אויך גערן די גימטריא פון י\"ח וואָס עס איז ח\"י – לעבען –, נאָר יעדער ניצט אויס דעם חי-געלעבט לויט זיין באַגריעף.\nמורנו הבעל שם טוב איז געבאָרען געוואָרען אין דעם גאָר קליינעם גרעניץ ישוב אקופּ, צווישען טערקיי און וואלאחיע.\n-----שולי הגליון-----\n*) <i>ראה \"היום יום\" יא ניסן</i>.\n**) <i>ראה מאמר ד\"ה ואתה קדוש (נדפס בספר המאמרים אידיש</i>).<i> – נעתק לעיל סימן ס</i>."]]],[300010796,"ערב\n\n<b>מורנו</b> הבעש\"ט נולד בשנת תנ\"ח, וסימנו נחת. בן שלש שנים הכיר את בוראו ושלש ושלשים שנה הי' נסתר. וסימן גל עד<sup data-n=\"1\">7</sup>. וכשהי' בן שלשים ושש נתגלה, ועשרים ושש שנה נהג את החבריא קדישא<sup data-n=\"2\">8</sup>.",[["1","7","ראה לקוטי שיחות חלק ז ע' 338-337, ושם: וי\"ל דהבעש\"ט כל זמן שהי' נסתר, הי' ג\"כ בבחינת לובן העליון דקדושה, וזהו שמבואר ברשימה (שבלקוטי דיבורים המוסג\"פ ע' 29)<sup data-n=\"3\">1</sup> דכשנגמר זמן היותו נסתר והי' צריך להתגלות סימנך הוא גל עד דוקא<sup data-n=\"4\">2</sup>, וידוע מש\"כ הבעש\"ט (נדפס בשיחת כ' כסלו תרצ\"ג ובהתמים ח\"ד יח<sup data-n=\"5\">3</sup>) דכשגמר לימוד התורה עם מורו אחי' השילוני – (ראה בסה\"ד שרשב\"י הוא גלגולו. ועיין ירושלמי ברכות פ\"ט ה\"ב) עד לעיני כל ישראל נתגלה."],["2","8","לקוטי דיבורים ח\"ג תקכז, א. וראה מכתב הבעש\"ט (להרה\"ח וכו' מ' יעקב יוסף הכהן כו' פולנאה, מיום ג' מקץ תקי\"ג) – נדפס ב\"התמים\" חוברת ד' ע' יח (קעד, ב): א\"דש\"ה גי\"ה קבלתי ושמחתי כעל כל הון רב והצדק את כ\"ה כי הבטחתי אותו לגלות לו באיזה יום ובאיזה שנה נתגלה אלי מורי אחי' השילוני ועתה בא העת לגלותו אני ביום מלאות לי ך' וא\"ו שנים ביום ח\"י אלול בשנת ת\"פ\"ד בעיר אקופ כחצות הלילה נגלה אלי איך אין לי רשות הלמוד הראשון הי' פרשה בראשית וכאשר גמרנו התוה\"ק עד לעיני כל ישר\"אל הייתי בן ל' וא\"ו ונגלתי.\nוראה לקוטי דיבורים ח\"א לא, א: עפ\"י הדברים האלה אשר ביום ח\"י אלול תפ\"ד נתמלא למורנו הבעש\"ט נ\"ע כ\"ו שנה, הרי נולד בשנת תנ\"ח ח\"י אלול, והתגלותו של מורנו הבעש\"ט הי' – עפ\"י המכתב הנ\"ל – ביום ח\"י אלול תצ\"ד, וכן בכל המכתבים שישנם, הן מכתבי הרה\"ק ר' אדם בע\"ש למורנו הבעש\"ט במשך ג' שנים תצ\"א-תצ\"ג בדברי תורה וביאורים מאמרי הזהר והתיקונים, ודברי תורה על אשר מסרב להתגלות, ומודיע לו אשר כולם החליטו שיתגלה, והן ממכתב מורנו הבעש\"ט לגיסו הרה\"ק ר\"ג נ\"ע, מוכח כי התגלות מורנו הבעש\"ט הי' בשנת תצ\"ד.\nוראה לקוטי דיבורים ח\"ג תעג, ב ואילך. ספר השיחות תש\"ה ע' 122: ח\"י אלול תנ\"ח איז דער אמת'ער גליקלעכער טאָג ביי אַלע חסידים פון דער גאַנצער וועלט, ווייל דער טאָג איז דער יום הבהיר פון אַלע חסידים אויף דער וועלט, עס איז דער טאָג וואָס מורנו הבעש\"ט איז געבאָרן געוואָרן.\nח\"י אלול תפ\"ד איז דער גרויסער אומשאַצבאַרער גליקלעכער טאָג, ווען מורנו הבעש\"ט איז אַלט געוואָרן זעקס און צוואַנציק יאָר און למעלה האָט מען גע'פּסק'נט אַז אחי' השילוני זאָל נתגלה ווערן צו מורנו הבעש\"ט און זאָל אים מגלה זיין דעם מאור תורה הנגלית והקבלה, ווי מען לערנט אין גן עדן.\nח\"י אלול תצ\"ד איז געוואָרן צען יאָר ווי אחי' השילוני האָט געלערנט און מדריך געווען את מורנו הבעל שם טוב, במשך די צען יאָר האָט מורנו הבעש\"ט אָנגעפירט מיט דער עדת צדיקים הנסתרים און איז אומגעגאַנגען ממקום למקום צווישן די פּשוט'ע מענטשן און פלעגט זיי דערציילן סיפּורים פון מעלת ישראל און מדות טובות און יראת שמים, און ווען עס זיינען נשלם געוואָרן די צען לימוד יאָרן איז – ח\"י אלול תצ\"ד – דער בעש\"ט, על פּי תוקף הוראת ודרישת מורו אחי' השילוני, נתגלה געוואָרן פאַר אַ בעל שם טוב וואָס איז עושה נפלאות און מגלה עמוקות.\n-----שולי הגליון-----"],["3","1","<i>נעתק בפנים כאן</i>."],["4","2","<i>ע\"ד שהי' ברשב\"י</i>,<i> של\"ג בעומר מרומז בקרא במש\"כ גל עד – ראה לעיל בלקוטי שיחות שם</i>."],["5","3","<i>נעתק בהערה הבאה</i>."]]],[300010797,"רעג\n\n<b>הרה\"ח</b> רד\"ץ<sup data-n=\"1\">9</sup> סיפר שהוא שמע מאביו הרה\"ח הרב ר\"פ<sup data-n=\"2\">10</sup> שהוא שמע מהחסיד הישיש ר' יעקב האָראָדאָקער שהי' מקושר להרה\"ק רמ\"מ זצ\"ל והוא שמע מכ\"ק הרה\"ק רמ\"מ זצ\"ל כי הבעש\"ט נולד ח\"י אלול תנ\"ח, וואָס דער סימן פון דעם יאָר איז נח\"ת און חת\"ן, און דעם יאָר וואָס דער בעש\"ט איז געבוירן געוואָרן האָט מען געדרוקט דעם צווייטן מאָל דעם של\"ה הקדוש בעיר אַמשטרדם<sup data-n=\"3\">11</sup>.",[["1","9","הרה\"ג הרה\"ח ר' דוד צבי חן. ראה אודותו – ספר השיחות תרצ\"א ע' 223 הערה 131."],["2","10","הרה\"ג הרה\"ח ר' פרץ חן. ראה אודותו – ספר השיחות שם ע' 221 הערה 111."],["3","11","לקוטי דיבורים ח\"א לה, א. וכ\"ה בספר השיחות תש\"א ע' 132. תש\"ג ע' 146."]]],[300010798,"עדר\n\n<b>מורנו</b> הבעש\"ט איז געבאָרן געוואָרן מאָנטאָג ח\"י אלול אין יאָר תנ\"ח. ווען רבינו הזקן איז געקומען דעם ערשטן מאָל פון מעזריטש האָט ער דערציילט זיינע איבערגעגעבענע יונגע לייט תלמידים, אַז זייענדיק ביים רבי'ן אין מעזריטש האָט אים דער רבי געזאָגט, אַז עס זיינען פאַראַן צוויי סימנים אויף דעם שנת ההולדה פון רבינו הבעל שם טוב: א) שנת נח\"ת נייחא לעליונים און נייחא לתחתונים<sup data-n=\"1\">12</sup>. ב) אין דעם יאָר האָט מען אין אַמשטרדם אָפּגעדרוקט דעם ספר של\"ה באותיות בהירות.\nדער גליקלעכער יום הולדת פון מורנו הבעל שם טוב און דער גליקלעכער יום הולדת פון רבינו הזקן איז ח\"י אלול. ביידע – מורנו הבעש\"ט און רבינו הזקן – האָבן אַריינגעגעבן אין אידן אַ חיות פּנימי אין דער עבודה פון אני לדודי ודודי לי. ביידע – מורנו הבעש\"ט און רבינו הזקן – האָבן געהאַט מסירת נפש אויף צו בריינגען אידן – בלי הבדל בני תורה אָדער אנשים פּשוטים – זיי זאָלן האָבן אַ משיכה צו אַ חיות פּנימי, און האָבן מגלה געווען דעם דרך החסידות וואָס דערמעגליכט אויך אַז אנשים פּשוטים זאָלן לעבן בחיות פּנימי<sup data-n=\"2\">13</sup>.",[["1","12","ראה ג\"כ שיחת כ כסלו תרצ\"ג אות א – נעתק לעיל סימן ער."],["2","13","ספר השיחות קייץ ה'ש\"ת ע' 170-169. וראה ספר השיחות תש\"ג ע' 188. לקוטי שיחות ח\"ד ע' 1353. ח\"ט ע' 337 ואילך. ובלקוטי שיחות ח\"ד שם: ידוע פתגם כ\"ק מו\"ח אדמו\"ר שליט\"א (שיחת ח\"י אלול ה'ש\"ת) אשר הבעש\"ט ואדה\"ז, שניהם המשיכו, בכאו\"א מישראל, חי, חיות פּנימי, בהעבודה דאלו\"ל, אני לדודי ודודי לי.\nובדא\"פ י\"ל שבעבודה זו גופא, פעל הבעש\"ט, בעיקר, מלמעלמ\"ט – מופתים, יסודי תורת הדא\"ח, הליכותיו ונסיעותיו אל המקבל. ואדה\"ז בעיקר בדרך מלמטלמ\"ע, ויש לקשר זה ג\"כ עם שני הענינים שבראש וסוף המאמר*: א) להודיע להבע\"ת אשר עמך הסליחה ב) לפעול שיהי' למען תורא, יראה עצמיית, ואכמ\"ל.\n-----שולי הגליון-----\n*) <i>הכוונה לקונטרס ח\"י אלול תש\"ט (ספר המאמרים תש\"ט ע' 215 ואילך)</i>."]]],[300010799,"ערה\n\n<b>דער</b> בעש\"ט איז געבאָרן געוואָרן ח\"י אלול. דער בעש\"ט האָט מיט חסידות אויף געטאָן אַ חיות אין דער עבודה פון אני לדודי ודודי לי<sup data-n=\"1\">14</sup>.",[["1","14","לקוטי דיבורים ח\"א לד, א."]]],[300010800,"רעו\n\n<b>כ\"ק</b> הרה\"ק ר' מאטעלע טשערנאָבילער (אמר) אַז דער טאַטע האָט געזאָגט (כוונתו על הוד כ\"ק הרה\"ק ר' נחום זצוקללה\"ה) אַז דער בעש\"ט איז גיבאָרען גיוואָרען בגופו בנפשו וברוחו ח\"י אלול, בגופו ווען ער איז גיבאָרין גיוואָרין אין אַ גוף<sup data-n=\"1\">15</sup>, בנפשו וואָס ביום ח\"י אלול<sup data-n=\"2\">16</sup> איז איהם נתגלה גיוואָרין מורו ורבו הק', וברוחו וואָס ער איז נתגלה גיוואָרין<sup data-n=\"3\">17</sup>, און די אַלע דריי מאָהל איז גיווען ח\"י אלול<sup data-n=\"4\">18</sup>.",[["1","15","בשנת נח\"ת."],["2","16","בשנת תפ\"ד – לקוטי דיבורים ח\"א לא, א."],["3","17","בשנת תצ\"ד – לקוטי דיבורים שם."],["4","18","לקוטי דיבורים ח\"א לב, ב. ומוסיף שם בשם ר\"ה מפּאַריטש: איך . . וואָלט קובע זיין ח\"י אלול פאַר אַ יום משתה ושמחה, נאָר אַ קביעות יו\"ט דאַרף מאַכן אַ רבי, און פאַרוואָס מען האָט דאָס ניט קובע געווען אַ יום טוב, איז לדעתי הטעם וויילע כתר איז ניט נמנה עם הספירות."]]],[300010801,"רעז\n\n<b>יום</b> השמונה עשר לחדש אלול – חי אלול – הוא יום הולדת מורנו הבעש\"ט נ\"ע, אשר אצל הוד כ\"ק אבותינו רבותינו הק' זצוקללה\"ה נבג\"מ זי\"ע הי' יום זה יום הילולא פּנימית בסוד אתכסיא, ובו ביום היו אומרים דא\"ח בהצנע, רק לפני בניהם ביחידות. וגמירא מילתא – ע\"פ ספּור מקובל מהוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע – אשר בו ביום – חי אלול – אומר כ\"ק רבינו הבעש\"ט נ\"ע דברי תורה ברבים לפני תלמידיו ותלמידי תלמידיו וכל המקושרים אליהם<sup data-n=\"1\">19</sup>.",[["1","19","ספר המאמרים תש\"ח ע' 292. ספר השיחות תש\"ח ע' 258. וראה לקוטי דיבורים ח\"ג תעד, א ואילך. ספר השיחות תש\"ה ע' 123. ספר השיחות תש\"ג ע' 140 ואילך. לקוטי שיחות ח\"ב ע' 636."]]],[300010802,"רעח\n\n<b>שמעתי</b> מהחסיד ר' חנוך הענדיל נ\"ע ששמע מהרב החסיד ר' זיסקינד קורעניצער נ\"ע שאמר בשם הרה\"ח ר' זלמן זעזמער נ\"ע אַז דער בעש\"ט איז געבאָרן געוואָרן, און נתגלה געוואָרן אין אַ מדינה וואָס זי איז געווען דורך גיווייקט מיט אידישע מסירת נפש בלוט<sup data-n=\"1\">20</sup>.",[["1","20","לקוטי דיבורים ח\"א לא, ב."]]],[300010803,"רעט\n\n<b>ואמר</b> אז<sup data-n=\"1\">21</sup> אאמו\"ר<sup data-n=\"2\">22</sup> כי רבינו הזקן אמר על הבעש\"ט אשר מה שחותם שמו לפעמים ישראל מ\"אקופ\"<sup data-n=\"3\">23</sup>, אין הכוונה כי הי' מעיר ששמה \"אקופ\", רק הי' מטלוסט<sup data-n=\"4\">24</sup> אשר העיר הזאת היא עומדת על הספר, והי' חומה סביבה ומגדל כדרך עיירות הספר, ואח\"כ נחרבה החומה ונשאר רק היסוד חפור בארץ, שנק' בלשון רוסי \"אקאפי\", והוריו של הבעש\"ט היו עניים גדולים ולא הי' להם דירה ודרו שם, ושם נולד הבעש\"ט.\nוסיים אאמו\"ר כי בכח \"אקאפעס\" אלו יכולים לדחות \"אקאפעס\" אחרים, כי כח הבעל שם טוב הוא בלתי נפסק רק צריכים לעמוד בקרב<sup data-n=\"5\">25</sup>.",[["1","21","בשנת תרס\"ד."],["2","22","כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["3","23","ראה מכתבי הבעש\"ט ב\"התמים\" חוברת א (ע' כב [יב, ב]).\nובמכתב הבעש\"ט ב\"התמים\" שם (ע' יט [יא, א]): נולדתי בק\"ק אקופ. ועד\"ז בשיחת כ' כסלו תרצ\"ג (לקוטי דיבורים ח\"א לא, א).\nובספר השיחות תש\"א ע' 153 (הועתק בהערות לסימן רעא): מורנו הבעש\"ט איז געבאָרן געוואָרן אין דעם גאָר קליינעם ישוב אקופ."],["4","24","ראה \"התמים\" שם (ע' יב [ז, ב] ואילך)."],["5","25","ספר השיחות תרצ\"ו ע' 130. נתבאר בארוכה בשיחת ליל ב' דחה\"פ תש\"כ (תורת מנחם – התוועדויות תש\"כ ח\"ב ע' 10 ואילך)."]]],[300010804,"רפ\n\n<b>מורנו</b> הבעל שם טוב איז געבליבען אַ יתום פון זיין הייליגען פאָטער צו פינף יאָר מיט דער קורצער צוואה:\nמיין קינד – זאָגט דער אַלטער גאון וצדיק ר' אליעזר, ליגענדיק אויפן טויטען בעט אין די לעצטע מינוטען פון זיין לעבען אויף דער וועלט, צו זיין פינף יאָריקען בן יחיד – מיין קינד זאָלסט ניט מורא האָבען פאַר קיינעם און פאַר קיין זאַך אויף דער וועלט מער ניט פאַר גאָט אַליין. זאָלסט ליעב האָבען מיט דער גאַנצער טיפעניש פון האַרצען און מיט דעם פלאַם פון דער נשמה יעדען אידען אָן קיין אונטערשייד, ווער ער זאָל ניט זיין און ווי עס זאָל ניט זיין.\nאין דער קורצער צוואה האָט דער הייליגער פאָטער איבערגעגעבען זיין בן יחיד דעם פינף יאָריקען קינד דעם גאַנצען צידה לדרך אויף דעם גאַנצען לעבען.\nדעם פאָטערס קורצע צוואה, יראת השם און אהבת ישראל, איז באַ מורנו בעל שם טוב, די שני לוחות הברית, און דער עץ החיים און עץ הדעת פון זיין הייליגען לעבען. וואו ער גייט און וואו ער שטייט לייכט אים דער עמוד האור פון דעם שויתי ה' לנגדי תמיד<sup data-n=\"1\">26</sup>, און עס ברענט אין אים דער הייליגער עמוד האש פון אהבת ישראל<sup data-n=\"2\">27</sup>.",[["1","26","תהלים טז, ח."],["2","27","לקוטי דיבורים ח\"ג שפה, ב ואילך. ספר השיחות תש\"א ע' 153 ואילך. וראה רשימת כ\"ק אדמו\"ר מהוריי\"צ נ\"ע (ע\"פ רשימת אדמו\"ר הזקן) נדפסה בקובץ יגדיל תורה (ניו יארק) שנה ג' חוברת ו' (לא), וז\"ל:\nבס\"ד יום ג' קדושים\nשמעתי מכ\"ק אאמו\"ר הרה\"ק שליט\"א בשם הישיש מראדמיסעל<sup data-n=\"3\">1</sup>, כי הוא הי' בין אלו שהיו מנקים את הספרים והכתבים קודם הפסח אצל כ\"ק אאזמו\"ר הצ\"צ זצוקללה\"ה, והי' מונח הרבה כתבים. עלים. ואגרות, בשייד. והי' צעטיל א' ארוך כתי\"ק כ\"ק אדמו\"ר הגדול זצוקללה\"ה<sup data-n=\"4\">2</sup>, וזה הי' נכתב בו ממה שזוכר,\nיש פלוגתא בין ר\"א וחכמים על אברהם אבינו ע\"ה, דא' סובר דבן ג' שנים הכיר אברהם את בוראו, וא' סובר בן מ\"ח שנה, ועל הבעש\"ט הכל מודים דבן ג' שנה הכיר, אביו ר\"א הי' בן מאה שנה ואמו שרה היתה בת צ'. ופעם א' גילו לו בחלום שיקדש את עצמו, כי יולד לו בן שיאיר לישראל. והתקדש ונולד הבעש\"ט. ונולד שלא כדרך כל הילדים. בהיותו בן ג' חדשים הי' הולך ומדבר, ובהיותו בן שנה וחצי, הסתלק אביו ר\"א, וקודם הסתלקותו, א\"ל אל תפחד משום אדם, כ\"א מן הקב\"ה בעצמו. לעת היצ\"ט של אביו ר\"א מתה אמו שרה, והוא הי' הולך ברחובות, ומקל בידו, והיו אנשי העיר מחזיקים אותו. והוא לא הי' מתיירא משום דבר והי' הולך ליערות וכו'. בליל שבו נגמר לו ג' שנים, הי' ליל חשך ואפילה וגם שוטף. לקח את המקל והלך לו לילך ליער, א\"ל בני אדם היאך אתה לילך בליל חשך ואפילה כזו. הושיב אין אני ירא משום דבר כ\"א מן הקב\"ה בעצמו. כשבא לעומק היער ראה בית גדול ומפואר והי' בו אור רב, ונכנס לחדר לפנים מחדר, עד שנכנס לחדר שכל הלצים שילוחות דסמא' יושבי' מסובים. א\"ל האיך אין אתה ירא לכנוס לכאן. אמר אין אני ירא משום דבר כ\"א מהקב\"ה בעצמו. א\"ל אינגעלע ועסטו מודה זאיין אַז עזב הוי' את הארץ צעק יתפרדו כל פועלי עון, ונתבטלו כלא הי'. עד י\"ח שנה למד אתו אחי' השילוני. ואח\"כ זכה להיות תלמידו של משיח. בהיותו בן י\"ג שנה למד אותו כל השמות וכינוייהן, לבד שם א' שלא למדו. ושאלו הבעש\"ט מפני מה הושיבו כי השם הזה גם הוא אינו יודע ומסור ביד הס\"מ, כי לא רצה לחרוב את הבית עד שיתנו לו שם זה במשכון, כי בשם זה תלוי הגאולה, והתחיל להתעסק להוציא את השם הזה, ואמרו לו מלמעלה הרבה השתדלו בזה וניזקו. הושיב כי אין אני ירא משום דבר כ\"א מן הקב\"ה בעצמו. עד אשר הביא את הס\"מ, ואמר הס\"מ טפה סרוחה לא הייתי בעוה\"ז עד עתה אלא ב' פעמי' בזמן חורבן בית ראשון ושני (ולי ספר הישיש שהב\"פ א' בזמן עץ הדעת והב' בזמן [. . .<sup data-n=\"5\">3</sup>]) והיאך העזת להביאני. הושיבו אין אני ירא משום דבר כ\"א מן הקב\"ה בעצמו, והוציא בלעו מפיו. (ועוד הי' כתוב שם מה. אך אינו זוכר מה שהי' כתוב, ובסוף הי' כתוב בזה\"ל) כ\"ז זכיתי לשמוע מפי הבעש\"ט בהקיץ.\nומספר הישיש הנ\"ל כי הוא רצה להעתיק זאת וכבר הכין נייר ועט עופרת ונכנס כ\"ד הרב מהרי\"ל זצ\"ל ואמר לו כי אל יעשה זאת, כי כבר העתיק זה הרב ר\"ה מפּאַריץ, ונשרף אצלו עם עוד איזה כתבים שלו. וגם אבא (אמר על כ\"ק הצ\"צ) יקפיד עבור זה, ומשו\"ז מנע את עצמו מלהעתיק.\nוראה גם ספר השיחות תש\"ג ע' 156 ואילך. ושם:\nפינף יאָר אַלט בין איך געבליבן אַ יתום פון מיין פאָטער און מוטער. די לעצטע ווערטער פון מיין הייליגען פאָטער פאַר זיין פּטירה איז געווען זיין צוזאָג: ישראל'יק זאָלסט פאַר קיינעם ניט מורא האָבן נאָר פאַר ג-ט ב\"ה אַליין.\nנאָך מיין פאָטערס צוזאָג פאַר קיינעם ניט צו מורא האָבן נאָר פאַר ג-ט ב\"ה אַליין האָט מיך אָנגעהויבן ציהען צו גיין אין די פעלדער און אין דעם טיפן גרויסן וואַלד וואָס לעבן אונזער ישוב. ווען איך פלעג אַוועקגיין פון חדר פלעג איך גיין אין פעלד און פלעג חזר'ן אויסענווייניג דאָס וואָס איך האָב געלערנט אין חדר. אָפט פלעג איך נעכטיגען אין פעלד אָדער אין וואַלד.\nמיינע אפּוטרופּסים, וועלכע פלעגען השגחה געבן אויף מיר און אויף נאָך עטלעכע יתומים און יתומות, האָבן ניט געדולדעט מיין הנהגה, וואָס איך גיי אין פעלד און אין וואַלד, און האָבן מיר שטאַרק מיצר געווען.\nאַזוי האָט געדויערט צוויי יאָר. ביז איינמאָל קומענדיג נאָך דעם וותיקין מנין אין וואַלד, האָב איך דערהערט אַ מענשליכע שטימע. בין איך געגאַנגען נאָך דעם קול און איך האָב דערזעהען אַ איד שטייט איינגעהילט אין טלית ותפילין און דאַווענט מיט אַזאַ התלהבות, וואָס איך האָב נאָך קיינמאָל ניט געהערט.\nאיך האָב זיך באַהאַלטן הינטער די בוימער און מקבל נחת געווען פון דעם אידענס דאַוונען. איך בין געווען זייער פאַרוואונדערט און האָב געטראַכט, אַז געוויס איז דער הייליגער מאַן איינער פון די ל\"ו\nצדיקים נסתרים, וואָס זיינען אויף דער וועלט. דער צדיק האָט מסיים געווען דעם דאַוונען און האָט אויסגעטאָן דעם טלית ותפילין, דאַן האָט ער געזאָגט תהלים מיט אַ גרויסער מתיקות.\nאַ משך זמן איז דער איד געזעסן און האָט געלערנט מיט אַ גרויסן געשמאַק, דאַן האָט ער צוזאַמענגעלייגט די ספרים און טלית ותפילין אין זיין זאַק, אָנגעטאָן דעם זאַק אויף די פּלייצעס, גענומען דעם שטעקן און גענומען גיין. דאַן בין איך אַרויס פון מיין באַהעלטעניש און געגאַנגען אַנטקעגען דעם אידן.\nווען דער איד האָט מיר דערזעהען האָט ער מיך געפרעגט: ווי קומט אַ קליינער אינגעל זיין אַליין אין וואַלד, וואָס טוסטו אין וואַלד, האָסטו גאָר קיין מורא ניט צו גיין אַליין אין וואַלד. איך האָב אים געענטפערט אַז איך ליעב די פעלד און דעם וואַלד ווייל דאָ אין פעלד און וואַלד זיינען ניטאָ קיין מענשען וואָס זיינען רובא דרובא בעלי גאוה און שקרנים, איך האָב פאַר קיינעם קיין מורא ניט, איך בין אַ יתום אָן אַ מוטער און אַ פאָטער, מיין פאָטער ע\"ה פאַר זיין פּטירה האָט מיר געזאָגט: ישראליק זאָלסט פאַר קיינעם ניט מורא האָבן נאָר פאַר ג-ט ב\"ה אַליין, האָב איך פאַר קיינעם ניט מורא.\nדער איד האָט מיך געפרעגט צו איך בין ר' אליעזר'ס אַ זון. ווען איך האָב געענטפערט אַז מיין פאָטער האָט מען גערופן מיט אַזאַ נאָמען, האָט דער איד אַרויסגענומען אַ גמרא פּסחים און האָט מיט מיר געלערנט אַ משך זמן, און איך בין מיט דעם אידן אַוועק אין וועג ניט וויסענדיג וואוהין מיר גייען און נאָך וואָס מיר גייען.\nאויף אונזער וואַנדער-וועג פלעגן מיר זיך אויפהאַלטן אין פאַרשידענע שטעט און שטעטלעך, דערפער און ישובים, פאַרשידענע צייטן, אַמאָל עטלעכע טעג אַמאָל אַ וואָך און מער. דער נאָמען פון דעם אידן האָב איך ניט געוואוסט. אַלע טאָג פלעגט ער מיט מיר לערנען, ער האָט קיינמאָל באַ קיינעם קיין נדבות ניט גענומען, און ער האָט מיך די גאַנצע צייט געשפּייזט. אַזוי איז געווען דריי יאָר צייט.\nאיינמאָל זייענדיג אין אַ קליין ישוב זאָגט צו מיר דער איד: דאָ ניט ווייט אין וואַלד וואוינט אַ איד אַ ירא שמים און אַ למדן, וועט ער מיך לאָזען באַ אים אויף אַ געוויסען משך זמן, און – כך הוה. דער איד האָט מיך צוגעפירט צו דער הייזיל, האָט מיר איבערגעגעבען צו דעם בעל הבית און איז אַוועק.\nפיר יאָר צייט בין איך אָפּגעווען באַ ר' מאיר'ן אין זיין וואַלד-שטיבל, און די גאַנצע צייט האָט ר' מאיר מיט מיר געלערנט בשקידה עצומה. אַלע טאָג פלעגן מיר גיין אין ישוב דאַוונען תפלה בצבור. קיינער פון די בעלי הישוב האָט נישט געוואוסט אַז ר' מאיר איז אַ גאון אַ צדיק נסתר, פאַר זיי איז ר' מאיר געווען אַ בעל מלאכה אַ סמאָלע ברענער.\nבאַ ר' מאיר'ן האָב איך זיך דערוואוסט פון די צדיקים נסתרים און פון גרויסן גאון וצדיק ר' אדם בעל שם, און דאַן בין איך אַריין אין דער עדת הצדיקים הנסתרים און האָב ווידער אָנגעהויבן וואַנדערן מעיר לעיר פון ישוב צו ישוב אין פאַרשידענע שליחות'ן, וואָס די הנהלה פון עדת הצדיקים האָט אויף מיר אַרויפגעלייגט.\nזייענדיג ניט קיין פולע זעכצן יאָר האָב איך שוין געהאַט אַ היבשע ידיעה אין קבלה און איך האָב מזמן לזמן געדאַוונט ע\"פ קבלת האריז\"ל מיט יחודי השמות, ווי הצדיק נסתר קדוש ונורא ר' חיים ז\"ל האָט מיר געלערנט.\nוראה לקוטי שיחות ח\"ב ע' 594.\n-----שולי הגליון-----"],["3","1","<i>ראה ספר השיחות תרפ\"ט ע' 59 הערה 26</i>."],["4","2","<i>ראה ספר השיחות שם ע' 26</i>."],["5","3","<i>בהצילום שתח\"י</i>,<i> נחתכו מהגליון תיבות אחדות</i>.\n**********"]]],[300010805,"רפא\n\n<b>תקופת היותו צדיק נסתר</b>\n<b>מורנו</b> הבעש\"ט האָט מקבל געווען פון אחי'<sup data-n=\"1\">28</sup> השילוני<sup data-n=\"2\">29</sup>.",[["1","28","ראה ספר השיחות תש\"ח ע' 232 שאחי' השילוני נקרא גם הבעל ח\"י. ובהערה שם (ועד\"ז בלקוטי שיחות חלק ב ע' 512): חי' יחידה – אחי' השילוני. ראה ספר השיחות קייץ ה'ש\"ת ע' 159.\nוהנה, לע\"ע, לא מצאתי בשום מקום ביאור שייכות דהבעש\"ט ואחי' השילוני, שהוא דוקא הי' רבו.\nויש להעיר ממאמר רשב\"י, בעל פנימיות התורה, שיפטר כל העולם מן הדין עד ימות המשיח אם יצטרף אחי' השילוני עמו (כן היא גירסת הירושלמי ברכות פ\"ט ה\"ב. ב\"ר פל\"ה, ב. פסיקתא דר\"כ פיסקא ויהי בשלח).\nויש לבאר זה עפמ\"ש בלקוטים שבסו\"ס הגלגולים להאריז\"ל, כי רשב\"י הי' גלגול אחי' השילוני, ועד ימות המשיח שאז יפקון ישראל מן גלותא ברחמי ע\"י שיטעמו מספר הזהר שהוא חיבורא דילך – של רשב\"י – כמש\"כ בזח\"ג קכד, ב. וא\"כ ה\"ה להבעש\"ט שכשיפוצו מעינותיו חוצה קאתי משיח וכמש\"כ באגרת הבעש\"ט הידועה.\nוהנה בתולדות יעקב יוסף פ' בלק כתב: אחי' השילוני שקיבל ממשה רבינו ע\"ה והי' מיוצאי מצרים ואח\"כ מב\"ד של דוד המלך ע\"ה והי' רבו של אלי' הנביא ורבו של מורי זלה\"ה, עכ\"ל. משמע קצת דזה שהי' רבו של הבעש\"ט שייך למה שהי' רבו של אלי' הנביא.\nוי\"ל ע\"פ הנ\"ל, דאלי' הנביא ענינו הכנה לביאת המשיח, לקרב את הרחוקים וכו' וכמו שנאמר הנה אנכי שולח לכם את אלי' הנביא <i>לפני</i> גו' <i>והשיב לב</i> גו' (משנה סוף עדיות ובכ\"מ).\nוזהו ג\"כ מעניני הבעש\"ט: אהבת ישראל אפילו אַזאַ וואָס געפינט זיך בקצוי תבל, וגם הפשוטים ביותר. והפצת המעינות, שזהו הכנה וכלי לביאת המשיח (ראה שיחת שמח\"ת תר\"ץ [ספר השיחות תר\"ץ ע' 84 ואילך]).\nומה שרבן הוא דוקא אחי' השילוני – אולי אפ\"ל מפני שהוא ניבא על הפירוד בישראל לשתי ממלכות וכו' והפירוד הזה גרם לעשיית העגלים והגלות וכו' אשר כ\"ז יתוקן בביאת המשיח ש\"לא יחצו עוד לשתי ממלכות עוד ולא יטמאו עוד בגילוליהם גו' וטהרתי אותם גו' ועבדי דוד מלך עליהם\" (יחזקאל לז).\nהשייכות דח\"י (חי' יחידה) לפנימיות התורה ולמשיח מבוארת ע\"פ הידוע דסוד דפרד\"ס דתורה הוא באצילות, חי'. ומשיח הוא חי' יחידה."],["2","29","רשימת כ\"ק אדמו\"ר מהוריי\"צ – ספר המאמרים ה'שי\"ת ע' 250. ספר השיחות ה'שי\"ת ע' 391. ושם: דער סדר הקבלה איז: מורנו [ההמשך בפנים. וממשיך שם:] און האָט די ענינים מגלה און מוסר געווען צו זיינע תלמידים הקדושים און האָט בוחר געווען את רבינו המגיד ממעזריטש און האָט אים מסמיך געווען אַז ער זאָל זיין דער מנהל און מנהיג עדת הצדיקים מורנו הבעש\"ט און די עדת הצדיקים הנסתרים. לקוטי דיבורים ח\"א פד, א."]]],[300010806,"רפב\n\n<b>עם</b> הבעש\"ט למדה הנשמה עצמה שלו, והיא אמרה לו אשר מה שהגיע למדריגות נעלות כאלו, הוא לא בשביל התורה שלו ולא בשביל התפלה, רק ע\"י הדביקות בהאותיות עצמם, כידוע אשר הדביקות בהאותיות של תורה ותפלה חידש הבעש\"ט<sup data-n=\"1\">30</sup>.",[["1","30","ספר השיחות תרצ\"ו ע' 148. וראה לעיל סימן ט."]]],[300010807,"רפג\n\n<b>בהיות</b> הבעש\"ט כבן אחת עשרה שנה בשנת תס\"ט נכנס בחבורת הצדיקים הנסתרים, ובהיותו כבן ארבע עשר בשנת תע\"ב יסד את שיטתו, ודורשי רשומות מצאו רמז במספר שנת התחלת שיטת מורנו הבעש\"ט תע\"ב<sup data-n=\"1\">31</sup>.",[["1","31","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ד ע' רצב. וממשיך שם: בסעודת יום שני דחג השבועות תקל\"ד סיפר הרה\"צ הרמ\"מ מהאָראָדאָק, את אשר שמע מאת מורו ורבו מורנו הרב המגיד ממעזריטש בשם הישיש ר' מרדכי הצדיק – או כמו שהיו קוראים אותו בימי אברכותו – בשנות ת\"נ-ת\"ס – ר' מרדכי הנסתר, אשר בעבור כחמש עשרה שנה מאז אשר החבורה קדישא קיבלה שיטתו של ישראל הצעיר, וראו גודל עוצם מעלת התועלת אשר הביאה, קרא הישיש הצדיק ר' מאיר את הצעיר ר' ישראל הצדיק והניח ידיו על ראשו, ואמר תבוא עליך ברכה, עבור שיטתך באהבת ישראל.\nהחבורה קדישא – סיים הרב המגיד – עשו ציון ורמז בהר\"ת דברכת הצדיק הר' מאיר, תבא עליך ברכה שהוא מספר השנה דשנת תע\"ב, אשר אז יסד מורנו הבעש\"ט נ\"ע את שיטתו החדשה באהבת ישראל.\nוראה לקוטי שיחות חלק יד ע' 323 הערה *52: להעיר מהתחלת פעולות הבעש\"ט בגמ\"ח בשנת \"תבוא עליו ברכה\". וראה לקמן סימן רצד."]]],[300010808,"רפד\n\n<b>זייענדיק</b> אַלט פערצען יאָר גייט מורנו הבעל שם טוב אַריין אין דער מחנה ישראל פון די צדיקים הנסתרים, דאָס איז געווען אין דער צייט פון דער פירערשאַפט פון דעם גרויסען הייליגען בעל שם הגאון הצדיק ר' אדם מראָפּשיץ, דער תלמיד מובהק און נאָכפאָלגער פון דעם גאון הצדיק ר' יואל בעל שם מזאַמושטש, וועלכער איז געווען דער תלמיד מובהק און נאָכפאָלגער פון הגאון ר' אליהו בעל שם מווירמייזא<sup data-n=\"1\">32</sup>.",[["1","32","לקוטי דיבורים ח\"ג שפו, א. ספר השיחות תש\"א ע' 154. וראה ספר השיחות תש\"ג ע' 167."]]],[300010809,"רפה\n\n<b>מורנו</b> הבעש\"ט איז געווען אַ וואַלגער יתום-אינגל אויף וועלכן קיינער קוקט זיך ניט אַרום. ער האָט ניט געהאַט קיין באַשטימטען וואוין- אָרט. פאַר אַ געוויסע צייט ווערט ער אַ געהילף-שמש, פילט-אָן ריינע וואַסער אין כיור, גיסט אַרויס די אומריינע, קערט אויס די שול, בריינגט קינדער צו די מלמדים און פירט-זיי-אָפּ צוריק צו זייערע היימען. שפּעטער לעבט ער אין אַ קליין אָרעמער צובראָכענער שטיבל אין אַ בלאָטיקער געסל און ווערט אַ ליים-פירער פאַרבריינגט טעג און נעכט אין די בערג און וועלדער און טרעפט-זיך מיט די צדיקים נסתרים. אין אַן אַנדער אָרט ווערט בארוכה באַשריבען ווען און באַ וועלכע אומשטענדען מורנו הבעש\"ט ווערט דער נשיא הנסתרים און גיט זיך אָפּ מיט פּדיון-שבויים<sup data-n=\"1\">33</sup>. אידן וואָס זיינען אַריינגעפאַלען צו פּריצים אין די הענט פאַר ניט האָבען צו באַצאָלן די אַרענדע אָדער פאַר אַנדערע זאַכען און די פּריצים האָבען זיי באַהאַנדעלט ווי געפאַנגענע. ביז עס איז געקומען די גליקליכסטע הייליק-ליכטיקע התגלות-צייט<sup data-n=\"2\">34</sup>.",[["1","33","ראה גם ספר השיחות קייץ ה'ש\"ת ע' 83. הועתק לעיל סימן רנז."],["2","34","ספר השיחות תש\"ח ע' 242. ושם לפנ\"ז: באַ תלמידי הבעש\"ט איז געווען אַ סדר קבוע אין געוויסע זמנים – על פי צוואת ואזהרת מורם רבינו הבעש\"ט – צו דערציילען דעם סדר תולדותיו און וואָס עס האָט מיט אים פּאַסירט בפּרטיות ביז דעם זמן ההתגלות [ההמשך בפנים]."]]],[300010810,"רפו\n\n<b>בשנות</b> ההסתר הי' לבוש בבגדי כפרי והי' נמצא תמיד בחברת אנשים פּשוטים ומחזק אותם בעניני אמונה פּשוטה ומרגילם שלא ילמדו מהנכרים יושבי הכפרים ומרגילם לשמור לשונם מלשון הרע רכילות ודיבורי קללה.\nמחלק אגוזים ותפוחים לילדים קטנים ומרגילם לברך עליהם והי' עונה אמן אחר ברכותיהם בדבקו' עצומ'<sup data-n=\"1\">35</sup>.",[["1","35","לקוטי דיבורים ח\"ג תקכז, ב. ספר השיחות ה'שי\"ת ע' 421."]]],[300010811,"רפז\n\n<b>רגיל</b> הי' הבעש\"ט – בשנים שהי' בהסתר – להניח את ידו הקדושה על לב הילדים ומברכם: דו זאָלסט זיין אַ וואַרעמער איד{35}.\n----- הערות -----"],[300010812,"רפח\n\n<b>אין</b> יאָר ארבע מאות ושבעים ושש, ווען מורנו הבעל שם טוב איז אַלט אַכצן יאָר גיט ער אויף אַ נייעם דרך אין דער עבודה פון די נסתרים אַז זיי זאָלען זיך נעמען פאַר דעם חינוך, זעהן באַזאָרגן אַלע אידישע ישובים מיט מלמדים.\nדער נייער דרך וואָס מורנו הבעל שם טוב שלאָגט פאָר, אַז די מחנה צדיקים הנסתרים זאָלען איבערנעמען דעם אחריות החינוך און זעהען באזאָרגען די אַלע קינדער פון די ישובים אין גוטע חדרים, ווערט אָנגענומען אין דער מחנה צדיקים הנסתרים אַז זיי אַליין זאָלען דאָס בריינגען אין לעבען, וואו עס וועט פעלען אַ מלמד זאָל איינער פון זיי דעם פּלאַץ ערפילן.\nמורנו הבעש\"ט איז מקיים דעם געוויסען מאמר, אַז דער וואָס גיט אַ עצה אויף עפּעס טאָן, בעדאַרף דאָס אַליין טאָן.\nמורנו הבעל שם טוב ווערט אַ באַהעלפער באַ אַ מלמד, פירט די קליינע קינדערלאַך אין חדר, זאָגט מיט זיי ברכות, בענטשט ציצית, זאָגט שמע ישראל און תורה צוה, שפּילט זיך מיט זיי, דערצעלט זיי וועגען משה רבינו און מתן תורה, פירט זיי פון חדר צו זייערע עלטערען, לייענט מיט זיי קריאת שמע און בידך אפקיד רוחי<sup data-n=\"1\">36</sup>.\nמורנו הבעל שם טוב דערצעלט זיינע הייליגע תלמידים אַז די בעסטע נחת רוח צייט אין זיין לעבען איז געווען, ווען ער האָט מיט די קליינע קינדערלעך מיט די ריינע מיילעכלעך געזאָגט מודה אני און שמע ישראל, און מיט זיי גע'חזר'ט דעם קמץ אַלף אָ, קמץ ב' באָ.\nאיך האָב געפילט – האָט מורנו הבעל שם טוב געזאָגט – דעם גרויסען נחת רוח וואָס עס איז געווען אין הימעל, און די גרויסע קנאה, וואָס די מלאכי מעלה האָבן מקנא געווען די צאן קדשים.\nמורנו הבעל שם טוב האָט געבויט דעם עדת ישראל פון אונטען אַרויף ווי מען בויט אַ בנין, די ערשטע זאַך איז דער יסוד פון דעם בנין. ווען דער פונדאַמענט איז אַ געזונטער וועט דער בנין זיין אַ פעסטער<sup data-n=\"2\">37</sup>.",[["1","36","בספר הזכרונות ח\"א ע' 101: [הבעש\"ט סיפר:] \"ווען איך בין געווען אַ באַהעלפער, פלעג איך שטאַרק האָרעווען אַריינצוגעבן אין די הערצעלאַך פון די קליינע קינדער אהבת אב ואם. איך פלעג די קינדערלאַך באַשיינפּערליך אָנווייזען אויף די מידות טובות פון זייערע עלטערען\"."],["2","37","לקוטי דיבורים שם שפז, ב ואילך. ספר השיחות תש\"א ע' 155 ואילך."]]],[300010813,"רפט\n\n<b>מורנו</b> הבעל שם טוב ווערט דער נשיא פון דער מחנה צדיקים הנסתרים, און האָבענדיג אין משך פון יאָרען אויפגעשטעלט אין הונדערטער קהלות חדרים און ישיבות, האָבענדיג אויפגעשטעלט דעם חינוך אַפּאַראַט דורך מלמדים פון דער מחנה צדיקים נסתרים, גיט אַרויס מורנו הבעל שם טוב אַ דרך אין עבודה און אהבת ישראל, און אַז די מחנה צדיקים נסתרים זאָלען נעמען אויף זיך די אויפגאַבע צו הויבען די פּשוטע פאָלקס מענשען פון דעם עם הארצות זומפּ און ברענגען זיי צום תורה טיש.\nמורנו הבעל שם טוב איז דער גייסטיגער יורש פון דעם אַלעמען באַוואוסטען עין טוב און אוהב ישראל, דער רמב\"ן – ר' משה בן נחמן – וואָס געפינט אַ טרייסט וואָרט צו די ליידענדע אידען אין זיין צייט, ווען עס האָט געבושעוועט די גזירת השמד, און האָט אויסגעשטרעקט אַ טרייסט האַנט צו די אנוסים, און האָט זיי צוריק געבראַכט אין אידישען לאַגער.\nמורנו הבעל שם טוב זעהט אין יעדער אידישער תנועה אַ תפלה צום בורא עולם, אין יעדער אידישען קרעכץ זעהט מורנו הבעל שם טוב אַ תשובה-קער צום רבונו של עולם.\nמורנו הבעל שם טוב דערצעהלט זיינע תלמידים, ווי אַמאָהל האָט אַ געשריי ג-ט האָב רחמנות און אַ קוקורעקו קריי פון אַ פּראָסטען דאָרפס בחור צובראָכן אַלע מסכים המבדילים און מבטל געווען אַ גזרה רעה<sup data-n=\"1\">38</sup>, ווי אַמאָהל אַ ערנסטער געוויין פון אַ פּראָסטער אידענע וואָס האָט ניט געקענט דאַוונען, זי איז געשטאַנען אין דער ווייבערשער שול און געהערט ווי אַלע דאַוונען יום כפּור און וויינען זייער, זאָגט זי רבש\"ע אַזאַ געוויין קען דערנעמען אפילו אַ טאַטערישע האַרץ, האָט די תפלה פון יענער אידענע פּועל געווען אַז יענער יאָר איז אין יענער קהלה געווען אַ שנת ברכה אין בני חיי ומזונא<sup data-n=\"2\">39</sup>.",[["1","38","ראה בארוכה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ד ע' שיד ואילך."],["2","39","לקוטי דיבורים ח\"ג שפט, א ואילך. ספר השיחות תש\"א ע' 157 ואילך."]]],[300010814,"רצ\n\n<b>הבעש\"ט</b> נ\"ע קודם שנתגלה והי' עוזר – אַ באַהעלפער – והי' מוליך את הילדים לחדר ומביאם חזרה<sup data-n=\"1\">40</sup>, הי' מנשקם מרוב חיבה באהבת ישראל, ואמר הרב המגיד ממעזריטש נ\"ע:\nהנני מתברך – ער ווינטשט זעך – לנשק ספר תורה באותה חיבה אשר הבעש\"ט נ\"ע הי' מנשק ילד מישראל שאמר אלף בית<sup data-n=\"2\">41</sup>.",[["1","40","הובא ונתבאר בלקוטי שיחות חלק ח ע' 251 ואילך."],["2","41","רשימת כ\"ק אדמו\"ר מהוריי\"צ בספר המאמרים תש\"ט ע' 87. וראה ספר השיחות תש\"א ע' 32 (הועתק ב\"היום יום\" טז תמוז). אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ח ע' פח.\nבספר השיחות תש\"ג ע' 139: ביים בעש\"ט איז אַ קינדעריש אמן אַ פתחו של אולם. ווי עס בריינגט זיך אין היום יום (ע' עא [טז תמוז]) אז דער הרב המגיד ממעזריטש האָט געזאָגט, הלואי וואָלט מען אַזוי געקושט אַ ס\"ת, ווי דער בעש\"ט האָט געקושט די קינדער פיהרענדיג זיי אין חדר אַלס בעהעלפער.\nובספר השיחות תש\"ד ע' 163: עס איז ידוע וואָס מורנו הרב המגיד ממעזריטש האָט געזאָגט, הלואי זאָל מען קושן מיט אַזאַ אהבה אַ ספר תורה ווי דער בעש\"ט פלעגט קושן די קינדערלעך פירנדיק זיי אין חדר, אין דער צייט וואָס ער איז געווען אַ באַהעלפער, יעדער איד איז אַ ספר תורה."]]],[300010815,"רצא\n\n<b>אין</b> די יאָהרן, וואָס הוד כ\"ק מורנו הבעש\"ט נ\"ע איז געווען בהסתר, איז ער מיט זיינע חברים הצדיקים הנסתרים פלעגען אַרום גיין אין פערשידענע שטעט און ישובים און פלעגען אָפט מאַכען פערשידענע געשפּרעכען מיט גאָר פּשוט'ע יודען און שטאַרקען זיי אין אמונה און בטחון<sup data-n=\"1\">42</sup>.",[["1","42","לקוטי דיבורים ח\"ב ריט, א. ספר השיחות תרצ\"ו ע' 35. וראה שם הסיפור בהמשך לזה."]]],[300010816,"רצב\n\n<b>ווי</b> ידוע דער זיידע (דער בעל שם טוב) בעפאָר ער איז נתגלה געוואָרען, פלעגט ער אַרומפאָהרען פון שטאָט צו שטאָט און פון איין מושב פון אידען צו דעם צווייטען, מעורר זיין אידען און שטאַרקען זיי מיט מוטה און אין גייסט, און אויך זעהן זייער לאַגע און מעורר רחמים זיין, מתפּלל זיין פאַר זיי. מען האָט נאָך ניט געוואוסט ווער ער איז<sup data-n=\"1\">43</sup>.",[["1","43","לקוטי דיבורים ח\"ד תרצה, א. ספר השיחות תרח\"ץ ע' 277. וראה שם הסיפּור בהמשך לזה."]]],[300010817,"רצג\n\n<b>הוד</b> כ\"ק רבינו הזקן ספר . . . אשר זקנו מורנו הבעש\"ט אמר שתחלת עבודתו יחד עם חבריו הצדיקים הנסתרים היתה להבריא – געזונד מאַכען – את גופם של ישראל ואח\"כ להבריא את רוחם ונפשם, ולכן כל זמן שמורנו הבעש\"ט הי' נסתר היתה כל עבודתו להיות לעזר לישראל בעניני פּרנסה ועיקר עסקו הי' עם האנשים הפּשוטים שהם גופם של ישראל, ואחרי כן כשנתגלה, התחיל לעסוק עם תלמידי החכמים ובני תורה שהם נפשם ורוחם של ישראל<sup data-n=\"1\">44</sup>.",[["1","44","התמים חוברת ב ע' מד [סט, ב]. נתבאר בשיחת יום ב' דראש השנה תשל\"ו. וראה לקוטי שיחות חלק כא ע' 53. ספר הזכרונות חלק א פרק ט (ס\"ע 52 ואילך)."]]],[300010818,"רצד\n\n<b>איינע</b> פון די עניני ההשתדלות צו מקרב זיין אַ אידן איז טאָן יענעם אַ טובה אויך בגשמיות. אויסער דעם וואָס דאָס אַליין גייט אַריין אין אהבת ישראל, העלפט דאָס אויך צו מקרב זיין יענעם לרוחניות. מען דאַרף ניט וואַרטן און תולה זיין גשמיות אין רוחניות דוקא, בתנאי כו', נאָר מען דאַרף טאָן אויך בגשמיות, ניט שטעלנדיק קיינע תנאים, וואָס דאָס איז דאָך געווען דער אויפטו וואָס איז נתחדש געוואָרן פון בעל שם טוב אין דעם דרך העבודה פון די צדיקים הנסתרים בשנת תבוא<sup data-n=\"1\">45</sup> עליו ברכה<sup data-n=\"2\">46</sup>.\n**********",[["1","45","ראה לעיל סימן רפג-רפד."],["2","46","לקוטי שיחות חלק א ע' 261. חלק יז ע' 220 הערה 51."]]],[300010819,"רצה\n\n<b>התגלותו</b>\n<b>אַלע</b> ווייסן דעם גרויסן געראַנגל וואָס מורנו הבעש\"ט האָט געהאַט מיטן הימל, וואָס ער האָט ניט געוואָלט זיך מתגלה זיין צו דער אידישער וועלט אַלס מנהיג ישראל און מורה דרך אין עבודת הבורא ב\"ה, ענליך צום געראַנגעל וואָס משה רבינו האָט געהאַט מיט השי\"ת ווען ער האָט ניט געוואָלט אָננעמען די הייליגע שליחות צו זיין דער גואל ישראל פון גלות מצרים<sup data-n=\"1\">47</sup>.",[["1","47","ספר השיחות תש\"ג ע' 191."]]],[300010820,"רצו\n\n<b>מורנו</b> הבעש\"ט איז געווען אַ סך יאָהרען אַ מתבודד. ער איז געווען אין עולם שכלו טוב, כלו אור. געלערנט מיט אחי' השילוני געזעהן זאַכען מסוף העולם ועד סופו, געהערט שיחת בעלי-חיים ודקלים געגאַנגען אין עולמות העליונים און האָט זייער ניט געוואָלט אַרויסגיין פון דער התבודדות-וועלט.\nפון די כתבים וואָס ר' אדם בע\"ש שרייבט למורנו הבעש\"ט<sup data-n=\"1\">48</sup> אין וועלכע ער איז מכריח את מורנו הבעש\"ט צו מגלה זיין זיך, איז מובן צוויי זאַכען, די גוטסקייט און גרויסקייט פון התבודדות, אָפּגעזונדערטקייט פון דער וועלט, און די הויכקייט און די נויטיגקייט פון התגלות, זיין אין וועלט.\nמיר אַלע וועלכע לעבען אין זיבעטן דור פון דורו של מורנו הבעש\"ט נ\"ע, זעהן במוחש דעם אונטערשייד צווישען התבודדות און התגלות.\nוויפעל צדיקים נסתרים און בעלי-שם זיינען געווען ביז מורנו הבעש\"ט. ר' יואל בעל-שם, ר' אדם בעל-שם, ר' מרדכי הנסתר, ר' קהת הנסתר, יעדער פון זיי האָט אַ סך אויפגעטאָן בדורו, הן ישועות ורפואות פּרטיות און הן ישועות והצלחות כלליות.\nאויך דער בעש\"ט איידער ער איז נתגלה געוואָרען האט אויפגעטאָן שטילערהייט גרויסע זאַכען, אָבער דאָס אַלץ איז גילוים פון אַ מתבודד, ניט קיין גילוים פון התגלות, נאָר ווען מורנו הבעש\"ט איז נתגלה געוואָרען האָט זיך אָנגעהויבען אַ סדר פון גילוי אור, מיט עבודה פון סדר והנהגה . . .\nהתבודדות און התגלות זיינען צוויי דרכים אין עבודה, וואָס יעדער פון זיי האָט אַ מעלה מיט אַ חסרון.\nמעלת ההתבודדות איז, וואָס דאָס איז אַ בית-יד צום שכל, און חסרונו איז, וואָס דורך דער עבודה פירט זיך ניט דורך די כונה פון בירור וזכוך העולם.\nמעלת ההתגלות איז וואָס עס איז פאַראַן גילוי אור בעולם, וחסרונו איז, וואָס תחלת הגילוי ברענט און ברעכט די וועלט.\nהודו לה' כי טוב כי לעולם חסדו<sup data-n=\"2\">49</sup>, האָט דער אויבערשטער ב\"ה רחמנות געהאַט על עם קדושו בניו ונחלתו, און האָט מסבב הסבות געווען אַז מורנו הבעש\"ט נ\"ע זאָל נתגלה ווערען און אַז מיט זיין התגלות און דורך אים זאָל נתגלה ווערען אַ נייער דרך אין עבודה, וואָס דער דרך וועט זיין אַ התכללות פון די ביידע מעלות וואָס אין התבודדות און וואָס אין התגלות . . .<sup data-n=\"3\">50</sup>\nמורנו הבעש\"ט נ\"ע האָט זיך ניט געוואָלט מגלה זיין. אין דעם ניט וועלן מגלה זיין זיך זעהען מיר אָן צוויי זאַכען, ניט ער האָט געוואָלט געזעגענען זיך מיט דער התבודדות וועלט, און ניט ער האָט געוואָלט קומען אין דער התגלות וועלט.\nמורנו הבעש\"ט האָט זיך אַ משך זמן רב געראַנגעלט מיט ר' אדם בע\"ש און האָט זיך משתמט געווען פון מסכים זיין אויף נתגלה ווערן ביז זיין רבי, אחי' השילוני, האָט אים געזאָגט אַז מיט דער התגלות וועט ער ערשט צוקומען צו דער הפלאת המעלה פון התבודדות.\nדאָס הייסט, אַז זיין רבי אחי' השילוני האָט אים געגעבען אַ הבטחה אַז אין זיין התגלות וועלען זיך צונויפקומען ביידע מעלות, אי די מעלה פון התבודדות, אי די מעלה פון התגלות . . .<sup data-n=\"4\">51</sup>\nמיט דער התגלות פון מורנו הבעש\"ט האָבען מיר זוכה געווען צו גילוי פון פּנימיות התורה.\nדאָס הייסט, אַז דורך למוד פּנימיות התורה און קיום המצות איז מען מכשיר דעם עולם אַז וועלט זאָל זיין אַ כלי צו אלקות, און דורך פּנימיות התורה, למוד החסידות וההתעסקות בחסידות איז מען ממשיך גילוי אלקות בעולם.\nתורת מורנו הבעש\"ט איז כלולה פון די צוויי מעלות, די מעלה פון התבודדות און די מעלה פון התגלות, ד. ה. אַז תורת מורנו הבעש\"ט איז אַ בית-יד צום גילוי אור עצמי פון התגלות אַז דער גילוי אור עצמי פון התגלות זאָל זיין בתפיסה בכלי ההשגה<sup data-n=\"5\">52</sup>.",[["1","48","\"התמים\" חוברת א ע' יד [ח, ב] ואילך."],["2","49","תהלים קו, א. ועוד."],["3","50","וממשיך שם: דער שורש הענין איז כבר הי' לעולמים. די צוויי דורות, דורו של אברהם אבינו ודורו של משה רבינו, וואָס דאָס זיינען צוויי דורות של אור וגילוי, נאָר דאָך זיינען זיי חלוקים זה מזה בעצם ענינם. עד אברהם הי' העולם מתנהג באפלה, בא אברהם התחיל להאיר*. ביז אברהמ'ן זיינען אויך געווען צדיקים גדולים**, אָבער דער זמן בכללות איז געווען אַ גילוי אור וועלכער איז העכער פון התיישבות, ד. ה. אַז דער אור זאָל זיין בהתיישבות האָט מען אויף דעם געדאַרפט האָבען אַנדערע ענינים.\nדי גמרא זאָגט: (סנהדרין צ\"ו ע\"א) תנא דבי אליהו, ששת אלפים שנה הוי עלמא, ב' אלפים תהו, ב' אלפים תורה, ב' אלפים ימות המשיח. איז אין די שני אלפים תהו, הגם עס זיינען געווען גילוים נעלים צו די צדיקים הגדולים מכל מקום איז דאָס אור התהו, און דער אור התהו ווערט אין עולם התקון אָנגערופן אפלה.\nאברהם אבינו איז געווען בתחלת שני אלפים תורה, איז התחיל להאיר, ווייל תורה איז אור המאיר, אָבער דאָס איז אור פון התבודדות, אַ אור בלתי מסודר, השפּעת החסד לכל, און מאַכען אַלעמען פאַר עובדי ה', ווייל דאָס איז אַ אור וואָס איז העכער פון כלים און איז ניט שייך צו כלים.\nדורו של משה איז שוין גאָר עפּעס אַנדערש. משה איז חכמה דאצילות, חכמה איז אויך העכער פון כלים ממש. כלים ממש איז בינה, חכמה איז למעלה מכלים ממש, אָבער דאָס איז אור שבא בהתיישבות בכלים און אפילו די העכסטע מדרגה פון חכמה קען האָבען אַ אחיזה בכלי.\nמיר זעהען אין לעבען ווען איינער דערזעהן אַ ציור נאה ביותר אָדער דערהערט אַ טיף רייכען שכל-וואָרט, ווערט ער אינגאַנצען פאַרחאַפּט פון דעם אַז אים נעמט אָפּ דער לשון ר\"ל, ער האָט ניט קיין ווערטער און קיין אויסשפּראַך, ער איז ממולא, פול מיט אור.\nווען מען לערנט חומש, די טאָג פּרשה, און עס קומט דער וואָכעדיגער מיטוואָך פון פּרשת שמות און\nמען לערנט די פּרשה ומשה הי' רועה וגו' ביז זה שמי לעולם וזה זכרי לדר דר, און מען קוקט זיך גוט צו מיט'ן עין השכל אין דעם גאַנצען ענין פון דעם וואָס עס קומט פאָר אין דער פּרשה, יעמאָלט קען מען האָבן אַ אפס קצה הבנה אין דעם ענין פון דער געראַנגעל וואָס מורנו הבעש\"ט האָט זיך געראַנגעלט מיט ר' אדם בעל שם מכח דעם ענין ההתגלות [ההמשך בפנים]."],["4","51","וממשיך שם: ומשה הי' רועה וגו' ער האָט בוחר געווען זיין אַ רועה צאן בכדי ער זאָל קענען זיין אַ מתבודד און התבודדות האָט די גרעסטע מעלה וואָס דאָס איז אַ בית-יד צו שכל, איז דאָרטען אים נתגלה געוואָרען דער אור אלקי. ווען משה רבינו האָט דערזעהען אור אלקי האָט ער זיך געזאָגט (שמות ג' ג') אסורה נא ואראה את המראה הגדול הזה, זאָגט רש\"י אסורה מכאן להתקרב לשם.\nאין דעם אסורה מכאן להתקרב לשם איז תלוי די גאַנצע מענשהייט און אין דעם ליגט די גאַנצע עבודה בכלל און די עבודה פון אַ מתבודד בפרט.\nאסורה מכאן להתקרב לשם. ער – דער מתבודד – האַלט אין איין שטייגען, ער גייט אַלץ העכער.\nאסורה מכאן להתקרב לשם, וואו ער איז וויל ער אַלץ העכער, און דער וועהל זיינער גיסט זיך אויס אין צוויי תנועות, אין דעם תנועה פון אסורה מכאן, און אין דער תנועה פון להתקרב לשם.\nדער ענין פון אסורה מכאן להתקרב לשם איז אַ ענין כללי. ד. ה. דאָס איז אַ תוכן פּנימי ניט נאָר אין אַ ענין פּרטי, נאָר דאָס איז דער תוכן פּנימי פון אַ ענין כללי און דאָס איז די העכסטע דרגא אין אנושיות בכלל און אין עבודה בפרט.\nאסורה מכאן להתקרב לשם איז דער ענין פון שאיפה, שטרעבען. די שאיפה עפענט נייע מקורים אויף צו שטאַרקען די כחות וחושים ביז ער ווערט אַ מעין הנובע, און אַ נהר שאינו פּוסק.\nאסורה מכאן להתקרב לשם איז פאַראַן הן אין השכלה און הן אין עבודה, און אין ביידע פאַלען – השכלה און עבודה – איז דאָס די העכסטע דרגא וואָס בריינגט צו אמת'ע שלמות אין דער מדרגה אין וועלכער ער איז, ד. ה. הן אין השכלה און הן אין עבודה.\nאין השכלה איז דער אסורה מכאן להתקרב לשם דער ענין החריפות. ווי מיר זעהען במוחש, אַז דער וואָס איז אַ חריף, איז זיין אופן ההתעסקות במושכלות וואָס ער האַלט אין איין שטייגן און קלעטערן אין די סברות ההשכלה מיט די גרעסטע שאַרפקייט.\nיעדע סברא איז באַלד ווי זי ערשיינט ביי אים ווערט זי אַרויסגעשטויסען פון נאָך אַ שאַרפערע סברא, און אַזוי אַרום שטייגט ער פון העכער צו העכער.\nדי אַלע סברות זיינען די אמת'ע ריינקייט פון השכלה, דאָס זיינען די בליצען פון כח המשכיל וועלכער רעגענט מיט שאַרפזיניגע השכלות, וואָס די סברות שכליים זיינען תנועות פון נפש השכלי, און דורך דעם חוש החריפות קומט מען צו צו די שלמות פון השכלה.\nצו קומען צו אַזאַ מדרגה ווי שלמות אין השכלה קען נאָר אַ מתבודד.\nאָט דער וועלכער זאָגט זיך אַליין אָפּ פון וועלט-זאַכען און איז משעבד זיינע כחות וחושי הנפש צו השכלה, דער קומט צו צו דער העכסטער שלמות פון השכלה.\nמשה רבינו, ווען ער איז געווען אַ רועה צאן, איז ער געווען אין דער העכסטער דרגא פון אַ מתבודד, און אַזוי ווי ער האט דערזעהען דעם אור האלקי האָט ער געזאגט אסורה נא ואראה, אסורה מכאן להתקרב לשם, ד. ה. די שאיפה פון אַ מתבודד.\nאויף דעם איז געווען דער ענטפער מלמעלה, של נעליך מעל רגליך. די עבודה פון אַ מתבודד איז אַ הויכע דרגא, עס איז אָבער פאַראַן נאָך אַ העכערע עבודה-מדרגה פון דער עבודה-מדרגה פון אַ מתבודד, און אין דער צווייטער הויכער מדרגה איז אויך פאַראַן דער תוכן פּנימי פון אסורה מכאן להתקרב לשם.\nנאָר בכדי מען זאָל קענען צוקומען צו דעם אסורה מכאן להתקרב לשם פון דער צווייטער מדרגה, מוז פריער זיין דער של נעליך מעל רגליך.\nדי הכנה צו דעם אסורה מכאן להתקרב לשם פון דער צווייטער מדרגה ליכט אין דער עבודה פון קענען זיך אויסטאָן פון דעם וואָס שכל פאַרשטייט און זיך משעבד זיין צו העכער פון שכל.\nאין דער פּרשה פון ומשה הי' רועה זעהט מען דעם סדר עבודה פון משה, דעם גילוי מלמעלה, ווי השי\"ת איז מודיע משה רבינו אַז הוא ית' איז אלקי אברהם אלקי יצחק ואלקי יעקב, וואָס ביז איצטער איז געווען דער סדר עבודה ווי דער תוכן פּנימי פון התבודדות איז, אָבער פון איצטער אָן דאַרף זיך אָנהויבען אַ אַנדער סדר עבודה אַ עבודה פון התגלות.\nמשה רבינו וויל זיך ניט געזעגענען מיט דער התבודדות וועלט, און וויל זיך ניט באַגעגענען מיט דער התגלות וועלט, און עס גייט אַ דינגעריי ביז השי\"ת איז מגלה משה רבינו דעם זה שמי לעולם וזה זכרי לדר דר.\nדאָס הייסט, השי\"ת האָט מגלה געווען צו משה רבינו דעם סוד פון בירורים, וואָס דאָס איז די כונה עליונה פון בריאת העולם אַז די בירורים זיינען נאָר אין דער עבודה פון התגלות.\nמיט דער התגלות פון משה רבינו האָבען מיר זוכה געווען צו מתן תורה, וואָס דורך תורה ומצוה איז מען מברר ומזכך דעם עולם, און [ההמשך בפנים]."],["5","52","לקוטי דיבורים ח\"א קלז, א ואילך.\n-----שולי הגליון-----\n*) <i>ראה ב\"ר פ\"ב, ג. שמו\"ר פט\"ו, כו.</i>\n**) <i>ראה שיחת י\"ט כסלו תרצ\"ב</i>."]]],[300010821,"רצז\n\n<b>שש</b> שנים סרב הבעש\"ט להתגלות<sup data-n=\"1\">53</sup> ומשום זה הפחיתו לו שש שנים מחייו, ונסתלק ביום הרביעי – נטלו המאורות סימן – ראשון לחג השבועות בשנת תק\"ך כשהי' בן ששים ואחת שנה שמונה חדשים ושמונה עשר יום{35}.",[["1","53","ראה לעיל סימן רצה-רצו."]]],[300010822,"רחצ\n\n<b>איך</b> האָב זיך געמוזט מתגלה זיין און אויספירן די הייליגע שליחות וואָס פון הימל האָט מען אויף מיר אַרויף געלייגט, ווען ניט וואָלט איך געווען אַ גזלן וואָס לויערט אין וואַלד צו באַפאַלן די דורכגייער<sup data-n=\"1\">54</sup>.",[["1","54","ספר השיחות תש\"ג ע' 192. ושם ע' 191 ואילך: עס איז פאַראַן אַ וואָרט פון מורנו הבעש\"ט, וואָס דער בעש\"ט האָט געזאָגט זיינע תלמידים נאָך דער פּאַסירונג, וואָס ער – מורנו הבעש\"ט – האָט שטאַרק מוכיח געווען אַ אידן אַן אַרענדאַר און האָט אים – ביחידות – אויסגערעכנט דעם צעטל עבירות וואָס ער – דער אַרענדאַר – האָט געטאָן, און דער בעש\"ט האָט די שטראָף רייד גערעדט מיט שטאַרקע ווערטער וואָס האָט דעם מוכסן באַדאַרפט זייער וויי טאָן.\nדער אופן ווי דער בעש\"ט האָט גערעדט צום מוכסן – הגם דעם צעטל עבירות האָבן זיי ניט געהערט ווייל דאָס האָט דער בעש\"ט געזאָגט דעם מוכסן ביחידות, אָבער די שטראָף רייד האָבן זיי דאָך יאָ געהערט – האָט זיי זייער געוואונדערט.\nדער בעש\"ט האָט פאַרשטאַנען אַז די תלמידים וואונדערן זיך אויף זיין שטאַרקן ריידן, האָט ער געזאָגט: [ההמשך בפנים. וממשיך שם:].\nפאַראַן זאַכן וואָס ווען מען הערט זיי איז ניט נאָר וואָס מען קען עס ניט פאַרשטיין, נאָר עס שניידט דעם אויער הערנדיק: אַ מנהיג ישראל, אַ גאון און אַ צדיק וואָס פון קינדווייז אָן האָט ער זיך מוסר נפש געוען אויף תורה ועבודה לטובת כלל ישראל, יאָרן לאַנג געלייגט די גרעסטע מיהע איינצופלאַנצן דעם העכסטן איידלסטן אהבת ישראל אין צענדליקער טויזנטער אידישע הערצער, זאָל אויף זיך זאָגן, אַז ווען ער וואָלט זיך ניט מתגלה געווען עפענטליך אַלס בעל שם טוב וואָלט ער געווען אַ גזלן.\nמיט דעם מאמר האָט דער בעש\"ט פאַרענטפערט פאַר זיינע תלמידים זייער וואונדער פאַרוואָס ער האָט גערעדט צום מוכסן שטאַרקע רייד. עס מיינט צו זאָגן, אַז אַ מנהיג ישראל בעדאַרף ריידן ענטשלאָסן דברים הדברים. און ווען השעה צריכה לכך בעדאַרף מען ריידן מיט דער שטרענגסטער שטרענגקייט, ניט רעכענען זיך מיט דעם כבוד המדומה פון יחידים נאָר בלויז מיט דער טובת הרבים."]]],[300010823,"רצט\n\n<b>חסידות</b> און רביים זענען געווען מיום שברא הקב\"ה אדם על הארץ. דער ערשטער מענטש וואָס איז געווען אויף דער וועלט איז געווען אַ חסיד ווי די גמרא זאָגט (עירובין י\"ח, ע\"ב) אדם הראשון חסיד גדול הי'.\nבכל דור ודור זיינען געווען רביים און חסידים נאָר דאָס איז אַלץ געווען אַ סדר פון נסתר, צדיקים נסתרים ביז השי\"ת האָט מגלה געווען אַ קו פון גילוי אַז עס זאָלן זיין רביים און חסידים גלוים, און האָט אונז מגלה געווען דעם בעש\"ט הקדוש.\nפון דעם יום הבהיר וואָס דער בעש\"ט הקדוש איז נתגלה געוואָרן הויבט אָן מאיר זיין דער אור החסידות בגילוי און עס הויבט זיך אָן אַ קו פון התגלות המאור און קירוב המאור אל הניצוץ.\nביז דעם בעש\"ט הקדוש און אויך אַ זמן בחייו זענען געווען רביים און חסידים. נאָר דאָס זענען געווען נסתרים. מיט דער התגלות פון בעש\"ט הק' איז נתגלה געוואָרן דער אילנא דחיי מיט ענפים פון רביים מאורי אור בקרב ישראל<sup data-n=\"1\">55</sup>.\n**********",[["1","55","לקוטי דיבורים ח\"א ס, ב ואילך.\n**********"]]],[300010824,"ש\n\n<b>נסיעה לארץ ישראל</b>\n<b>הבעש\"ט</b> רצה לנסוע לארץ ישראל<sup data-n=\"1\">56</sup>, והגיע עד סטאַמבול<sup data-n=\"2\">57</sup>, וחזר למקומו<sup data-n=\"3\">58</sup>.\n**********",[["1","56","ראה גם תולדות יעקב יוסף רא, א. שיחת ש\"פ ויקהל כ\"ה אד\"ר תשנ\"ב."],["2","57","שבחי הבעש\"ט דפוס קאָרעץ (תקע\"ו) פס\"ב (כה, ב-ג)."],["3","58","שיחת אחרון של פסח תשי\"ב (תורת מנחם – התוועדויות ח\"ה ע' 155). וממשיך שם: וכן רבינו הזקן נסע עד \"לעיר מאָהליב אשר על נהר דניעסטער\", וחזר למקומו (מאמר אבות החסידות – \"התמים\" חוברת ב ע' נב. בית רבי ח\"א פ\"ו (ז, ב))."]]],[300010825,"שא\n\n<b>הסתלקותו</b>\n<b>ווי</b> עס איז ידוע אַז דער בעש\"ט האָט געזאָגט אַז ער האָט בכח עולה זיין בסערה השמימה כמו אלי', רק איך וויל דורכגיין דעם כי<sup data-n=\"1\">59</sup> עפר אתה ואל עפר תשוב<sup data-n=\"2\">60</sup>.",[["1","59","בראשית ג, יט."],["2","60","ספר השיחות תורת שלום ע' 46. וכ\"ה בלקוטי דיבורים ח\"א צו, ב. ובתורת שלום שם מבאר: וואָרום אַזוי ווי די התהוות פון עפר נעמט זיך דאָס פון עצמות דוקא (א\"ה עמ\"ש בתולדות ל\"ז ותבין) וואָס הוא בכחו ויכולתו להוות מאין ליש וכמ\"ש באגה\"ק, וואָרום עצמות א\"ס ב\"ה איז דאָך מציאותו מעצמותו בלי שום עילה וסיבה הקודמת לו בערכו, אַזוי איז אין מדרי' העפר אויך פראַן כח העצמות, וואָס עפר אין עבודה גייט דאָס אויף גוף ונה\"ב, און גאָר דער עיקר איז פּועל זיין דעם בירור הגוף ונה\"ב אין מדות טבעיים זיינע ער זאָל ניט וועלן קיין גשמיות'דיקע זאַכן, נאָר וואָס נוגע צו גשמיות זאָל זיין הן ולאו ורפיא בידו, און אויב ער קאָן ניט פּועל זיין באַ זיך אַז עס זאָל זיין הן ולאו שוין, זאָל ער טאַקע בעסער גאָר ניט עסן, ער קאָן זיך אויסנאַרן, און רעכענען אַז ער דאַרף דעם עסן מצד ההכרח, וויילע ער איז דאָך מלובש אין אַ גוף גשמי, אָדער נאָך טיפער נאַרן זיך, אַז דאָס איז גאָר לש\"ש, מיט דעם וועט ער קענען דאַוונען און לערנען, וואָס דאָס איז מער ניט ווי זיך אויס גינאַרט.\nדי בחינה אויף דערוף איז פּשוט אויב ער קען באַ זיך פּועל זיין אין מיטן עסן, בעת ער עסט דעם דבר הטוב והערב, ער זאָל אויפהערן דאָס עסן, יעמאָלט איז גוט.\nוראה לקוטי שיחות חלק ד ע' 1031 ואילך ביאור בזה."]]],[300010826,"שב\n\n<b>והנה</b> ממה שא' הבעש\"ט ז\"ל שביכולתו לעלות השמים כמו אלי' רק שרוצה דורך גיין מ\"ש כי עפר אתה ואל עפר תשוב נראה שנשמתו הי' מבחי' יחוד פּנימי דאו\"א והרוחניות שלו למטה הי' גם מצד הגוף וכמו אלי' שהעפיפה שלו הי' מצד זיכוך הגוף כו' כנודע<sup data-n=\"1\">61</sup>.",[["1","61","המשך תער\"ב ח\"ג ע' א'רנז. ועיי\"ש לפנ\"ז [הועתק לקמן סימן שכו], ששרש נשמת הבעש\"ט הוא מבחי' זווג רוחני. וראה לקוטי שיחות ח\"ב ע' 515 הערה 5. ח\"ד ע' 1031 ובהערה 31. ע' 1331. ח\"ט ע' 90 בהערה 23."]]],[300010827,"שג\n\n<b>רבינו</b> הבעש\"ט נסתלק ביום חגה\"ש דשנת תק\"ך (אמנם מסופקני<sup data-n=\"1\">62</sup> אם ביום א' נסתלק או ביום ב' דחה\"ש, אבל זה ודאי שזמן הסתלקותו הי' בחגה\"ש) ותומ\"י קיבל הרבנות בנו הרב ר' צבי, וכה ניהל הרבנות, והיו כל התלמידים בצוותא חדא. לתקופת השנה בחה\"ש בעת עריכת השולחן, וישבו כל התלמידים אמר הרב ר' צבי: היינט איז באַ מיר געווען דער טאַטע און האָט מיר געזאָגט: אַז די שכינה און פּמליא של מעלה מיט'ן גאַנצן פּעקל, האָט זיך אַריבערגעטראָגן צו אייך, ר' דובער (כוונתו אל המגיד ממעזריטש), ועמד ר' צבי ופשט את בגדו הלבן ולבשו את הרב ר' דובער ממעזריטש, והרב המגיד ישב על כסא הרבנות מעת ההיא, ולא סרב כלל<sup data-n=\"2\">63</sup>.",[["1","62","ראה שיחת כ' כסלו תרצ\"ג אות א' (לקוטי דיבורים ח\"א לב, א) שאח\"כ נפשט הספק, והסתלקותו היתה ביום א' דחג השבועות (הערת כ\"ק אדמו\"ר זי\"ע בספר השיחות תורת שלום ע' 83).\nוראה ספר השיחות תרצ\"ט ע' 333. לקוטי שיחות ח\"ד ע' 1031 ובהערות שם. ח\"ח ע' 22, 27 ובהערות שם (חלק נעתק לקמן בהערות לסימן שיח).\nוראה לקוטי שיחות ח\"ד שם ובהערות 30-*29, בנוגע לזמן קבורת הבעש\"ט וע\"ד ההלכה. ספר השיחות תרצ\"ט שם."],["2","63","תורת שלום שם."]]],[300010828,"דש\n\n<b>הרב</b> המגיד אמר:\nנשיאותו של מורנו הבעש\"ט עשרים ושש שנים כמנין שם הוי' וכמנין שני פעמים אחד{35}.\n----- הערות -----"],[300010829,"שה\n\n<b>הרה\"ק</b> הרמ\"מ זצ\"ל (האָראָדאָק) פתח ואמר, יודע ה' ימי תמימים<sup data-n=\"1\">64</sup>, יודע ה' וויסן דעם שם ה' קען מען דאָס וויסן פון די ימי תמימים וואָס זיינען ממשיך אלקות אין וועלט און זיינען מקשר וועלט מיט אלקות, וואָס מיט דעם מאַכט מען די וועלט גאַנץ און מיט דעם איז מען משלים דעם רצון אלקות, דער רבי דער בעש\"ט האָט געלעבט צוויי מאָל כ\"ו און איינמאָל עשר, די ערשטע כ\"ו איז כמספר שם הוי' הגלוי, דערפאַר איז ער געווען בהתגלות, נאָר בכדי ער זאָל קענען נתגלה ווערן האָט געדאַרפט דורכגיין דער סדר פון עשר ספירות וואָס דאָס זיינען די מיטעלע צען יאָר, ונחלתם לעולם תהי'{64}, מיט תורת הבעש\"ט וועלן מיר קומען אין ארצנו הק'<sup data-n=\"2\">65</sup>.",[["1","64","תהלים לז, ח."],["2","65","לקוטי דיבורים ח\"א לה, ב."]]],[300010830,"שו\n\n<b>איינמאָל</b> שבועות האָט הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ דערציילט וואָס ער האָט געהערט פון זיין זיידן, הוד כ\"ק רבינו הגדול: אין זוהר<sup data-n=\"1\">66</sup> שטייט מאן פני האדון הוי'<sup data-n=\"2\">67</sup> דא רשב\"י, און מיר זאָגן אַז דער בעש\"ט איז ב\"פּ הוי', הוי' הנעלם איז די כ\"ו שנים ווען דער בעש\"ט איז געווען אַ נעלם און הוי' הגלוי איז די כ\"ו שנים וואָס דער בעש\"ט איז געווען בגלוי<sup data-n=\"3\">68</sup>.",[["1","66","ח\"ב לח, א."],["2","67","תשא לד, כג."],["3","68","ספר השיחות תש\"ה ע' 86."]]],[300010831,"שז\n\n<b>עס</b> איז מקובל רבי מפּי רבי ששנות חיי הבעש\"ט נ\"ע בעלמא דין הם ע\"ב שנה, אלא שאין ידוע אם הם שנות הגילוי<sup data-n=\"1\">69</sup> או המילוי<sup data-n=\"2\">70</sup>.",[["1","69","הכוונה ימיו כפולים, והם היו\"ד שנים שלמד – הערה בלקוטי דיבורים."],["2","70","לקוטי דיבורים ח\"א לא, ב. ושם לפנ\"ז: אַז דער טאַטע האָט געלייענט דעם בריף הנ\"ל מהבעש\"ט נ\"ע להרה\"ק הרי\"י נ\"ע [הועתק לעיל בהערה לסימן ערב], אמר לי כ\"ק אאמו\"ר הרה\"ק, ווי וועט דאָס מתאים זיין מיט דעם וואָס [ההמשך בפנים]."]]],[300010832,"שז-א\n\n<b>מיט</b> יעדען יאָר וואָס דער בעש\"ט ווערט עלטער, ווערט אַלץ מער נתגלה דער אור המאיר פון זיין תורה און זיינע דרכי העבודה, וואָס צו אונז איז דאָס געקומען דורך דעם רבי'ן און די אַלע רביים<sup data-n=\"1\">71</sup>.\n**********",[["1","71","רשימת היומן של כ\"ק אדמו\"ר מהוריי\"צ – ח\"י אלול תרס\"ג (\"מבוא\" לקונטרס ומעין ע' 57)."]]],[300010833,"שח\n\n<b>מדריגתו וגדולתו</b>\n<b>אבות</b>\n<b>דער</b> בעש\"ט און דער מעזריטשער מגיד זיינען געווען ע\"ד ווי די אבות קודם מ\"ת. עבודת אברהם איז געווען ע\"י גמ\"ח, עבודת יצחק דורך חפירת בארות און עבודת יעקב ע\"י המקלות. נאָכדעם איז געווען מ\"ת, כידוע בענין שמן תורק שמך<sup data-n=\"1\">72</sup>.\nעל דרך זה איז געווען די התגלות פון בעש\"ט און מעזריטשער מגיד, זיי זיינען געווען בדוגמא של מעלה, ווי עס איז ידוע פון די בע\"ש'סקע מעשיות<sup data-n=\"2\">73</sup>.",[["1","72","שה\"ש א, ג. שהש\"ר פ\"א, ג (א)."],["2","73","ספר השיחות תש\"ב ע' 100. וממשיך שם (ע' 101): אָבער פון אַלטן רבי'ן אָן איז געווען די התגלות חב\"ד ע\"ד ווי מ\"ת, וואָס איז אַלץ אורות בכלים, בכדי אַז יעדערער זאָל קענען ממשיך זיין אורות פּנימים אין כלים פּנימים און אורות מקיפים אויף די כלים."]]],[300010834,"שט\n\n<b>א\"ק</b>\n<b>הרה\"ח</b> הרי\"מ נ\"ע<sup data-n=\"1\">74</sup> האָט דערציילט שפעם אחד הי' על יחידות<sup data-n=\"2\">75</sup> ושאל איזה דברים שהוזכרו בהדרוש של שבת ההוא בענין א\"ק, וציוה לי ללמוד הדרוש למנצח על השמינית בלקו\"ת, ותבקש אצל בני<sup data-n=\"3\">76</sup> הביאור שעל דרוש זה הבלתי נדפס, ובהמשך דיבור קדשו אמר אַ ציור מוחשי אויף פּרצוף א\"ק איז ווי דער בעש\"ט, אדם און עליית הנשמה כחדא<sup data-n=\"4\">77</sup>.",[["1","74","הרה\"ח ר' יעקב מרדכי בעזפּאַלאָוו. רב בפּאָלטאַווע. מחסידי אדמו\"ר מהר\"ש ואדמו\"ר מהורש\"ב. ראה אודותו: ספר השיחות תר\"ץ ע' 92. וש\"נ."],["2","75","אצל כ\"ק אדמו\"ר מהר\"ש."],["3","76","כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["4","77","לקוטי דיבורים ח\"א לז, א."]]],[300010835,"שי\n\n<b>אור החיים</b>\n<b>עס</b> איז דאָך ידוע<sup data-n=\"1\">78</sup> די שייכות פון דעם בעש\"ט מיטן אור החיים הקדוש<sup data-n=\"2\">79</sup>.",[["1","78","ראה שדי חמד שיורי הפאה מערכת ג' כלל ז' בסופו (כרך ח א'תשיט, ד). ועוד."],["2","79","לקוטי שיחות חלק כ ע' 515."]]],[300010836,"שיא\n\n<b>אור שנברא ביום ראשון</b>\n<b>מאמר</b> אדמו\"ר הזקן, ד' וישב כ' כסלו תקנ\"ט:\nעל יום הרביעי נאמר<sup data-n=\"1\">80</sup> יהי מארת חסר כתיב<sup data-n=\"2\">81</sup>, ופירש [אדמו\"ר הזקן] כפירוש הרמב\"ן<sup data-n=\"3\">82</sup> שאור שנברא ביום ראשון שמש ג' ימים<sup data-n=\"4\">83</sup>, ג' דורות – הבעש\"ט הרב המגיד – און האָט זיך אָפּגעשטעלט<sup data-n=\"5\">84</sup>.",[["1","80","בראשית א, יד."],["2","81","ירושלמי תענית פ\"ד ה\"ג. פרש\"י עה\"פ. ועוד."],["3","82","בראשית שם."],["4","83","ב\"ר פ\"ג, ו ובמתנת כהונה שם. תנא דבי אליהו זוטא פכ\"א."],["5","84","לקוטי דיבורים ח\"א מב, א."]]],[300010837,"שיב\n\n<b>אי אפשר \"לעבור\" למדריגתו</b>\n<b>המעשה</b> שמספרים שאמר הבעש\"ט נ\"ע לר' וואָלף קוצייעש אין ביני לבינך אלא כחוט השערה אך החוט השערה הזה לא תוכל לעברו לעולם, דהיינו כמלא נימא שבין שני שמות הוי'<sup data-n=\"1\">85</sup>.",[["1","85","אוה\"ת שה\"ש ח\"ב ע' תרסט. ושם לפנ\"ז: ויש לבאר ע\"ד מ\"ש השל\"ה בענין יצחק שאמר והי' כאשר תריד כו', כי מה שבתחלה עבמ\"ח לברוא את העולם במדה\"ד זהו לפי שעי\"ז יהי' העליי' יותר גדולה כמ\"ש בזח\"ג קרח קע\"ח ב' דאלמלא דינא כו' אלא שלא יוכלו לקבל ומ\"מ נשאר בחי' זו לצדיקים כמארז\"ל ע\"פ וסביביו נשערה מדקדק עמהם כחוט השערה. כי הנה בחי' כמלא נימא זהו הפסיק טעמא שבין שני שמות הוי' כמ\"ש בפרדס שער הטעמים פ\"ג גבי פסיק ובמא\"א נ' ט\"ז כי נימא בחי' צדיק כו', וע\"כ כדי להעלותן לבחי' ש' הוי' שלמעלה מהשתלשלות שע\"ז ארז\"ל קדש למד מלמטה והוי' מלמעלה בד\"ה ועשית ציץ הוא מדקדק עליהן כמלא נימא. ועד\"ז י\"ל [ההמשך בפנים]."]]],[300010838,"שיג\n\n<b>איש שדה</b>\n<b>מורנו</b> הבעש\"ט איז געווען אַ איש שדה. הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ האָט דאָס מבאר געווען. ער – דער בעש\"ט – האָט אויף זיך גענומען און האָט מצליח געווען מתקן צו זיין די בירורים און ניצוצות פון דעם איש שדה. אַלע ווייסן ווער עס ווערט אָנגערופן איש שדה<sup data-n=\"1\">86</sup>, וואָס ער איז מקטרג אויפ'ן עם ישראל און דערפון נעמען זיך אַלע גזירות אויף אידן<sup data-n=\"2\">87</sup>.",[["1","86","ראה בארוכה הוספות לביאורי הזהר בתחלתו. אוה\"ת תולדות ד\"ה ויגדלו הנערים."],["2","87","לקוטי דיבורים ח\"ד תרב, א. ספר השיחות תש\"ד ע' 118."]]],[300010839,"שיד\n\n<b>אליו נגלה האלקים</b>\n<b>הבעש\"ט</b> והה\"מ נ\"ע אשר אליו נגלו האלקים<sup data-n=\"1\">88</sup>.",[["1","88","סהמ\"צ להצ\"צ ס, ב."]]],[300010840,"שטו\n\n<b>אתפשטותא דמשה</b>\n<b>אתפשטותא</b> דמשה בכל דרא<sup data-n=\"1\">89</sup>. דער כללות חסידישער משה מיט די נ' שערי בינה וואָס נבראו בעולם<sup data-n=\"2\">90</sup>, איז דער בעל שם טוב מיט זיין תורת<sup data-n=\"3\">91</sup> החסידות<sup data-n=\"4\">92</sup>.",[["1","89","תקו\"ז תיקון סט."],["2","90","ר\"ה כא, ב."],["3","91","ראה שיחת שמח\"ת תר\"ץ אות ל' (הועתק לקמן סימן שמה)."],["4","92","ספר השיחות תש\"ג ע' 142 (בשם כ\"ק אדמו\"ר מהורש\"ב נ\"ע).\nוממשיך שם: אונזער חב\"ד – משה מיט די נ' שערי בינה איז רבינו הזקן מיט זיין תורת החסידות. כולם נמסרו למשה חסר אחד, וואָס דעם אחד דאַרפן חסידים משלים זיין ביזן ביאת המשיח, און דאָס איז דער יפוצו מעינותיך חוצה (ראה שיחת שמח\"ת תר\"ץ – הועתק לקמן סימן שמה)."]]],[300010841,"שטז\n\n<b>מורנו</b> הבעש\"ט נ\"ע הוא בחי' ומדרי' משה ראש נשיאי ישראל במשך כל הדורות עד הזמן הבהיר דהתגלות משיח צדקנו בקרוב ממש, והגילוי' העליונים שנתגלו למורנו הבעש\"ט בסוגי אתעדל\"ע הם ג\"כ בארבעה אופנים א) אתדל\"ע לעורר האתעדל\"ת להתגלות, ב) הגילוים באתעדל\"ע בתורה ובאותות ומופתים ע\"י העבודה באתעדל\"ת. ג) הגילוים באתעדל\"ע בדרך מתנה בתלמידיו החבריא קדישא לתת להם כח ועוז להנחיל את אור התורה והעבודה לדורותיהם ד) הגילוים דאתעדל\"ע בדרך מציאת חן להנחיל את כל ישראל את הכח דמס\"נ על מדות חסידות.\nוהנה אתפשטותא דמשה בכל דרא ודרא, בכל דור ודור עד ביאת משיח צדקנו הוא אתפשטותא כחו של מורנו הבעש\"ט נ\"ע, כי בהיותו בעלמא דין הי' גילוי בחי' נר\"נ ואחר הסתלקותו מעלמא דין בסוד גדולים צדיקים כו' והגילוים בתלמידי תלמידיו ובדורות האחרונים הם הגילוים המתגלים ע\"י מדריגת חי' יחידה של נשמת מורנו הבעש\"ט נ\"ע עד כי בעזרת נשמות הוד כ\"ק אבותינו רבותינו הק' הנה המקושר אליהם וההולך בעקבותיהם, גם החלוש בכחות הגלוים בידיעת תורת החסידות יאמר גבור אני<sup data-n=\"1\">93</sup> בעבודה בפועל ממש בהחזקת היהדות ובהרבצת תורה בכלל ובהנהגה בדרכי החסידות בפרט<sup data-n=\"2\">94</sup>.",[["1","93","יואל ד, י."],["2","94","אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ח ע' יט."]]],[300010842,"שיז\n\n<b>בעל הבית על העולם</b>\n<b>בכלל</b> יש שני מיני בעלי בתים יש מי שהוא עשיר והכל מתנהג אצלו בהתפשטות גדולה, ואינו מדקדק על דברים קטנים, שאינו תופס מקום, אבל מי שהוא באמת בעל הבית הנה כל דבר קטן תופס מקום אצלו, ואין זה מצד כילות רק כן הוא מחוש בעל הבית אמיתי, כי גם דבר קטן תופס מקום. הבעש\"ט הי' אַ בעל הבית אויף דער וועלט, וע\"כ תפס אצלו מקום גם ניצוץ היותר קטן שבנשמות<sup data-n=\"1\">95</sup>.",[["1","95","ספר השיחות תרצ\"ו ע' 149."]]],[300010843,"שיח\n\n<b>בעל שם טוב</b>\n<b>. . . נאָר</b> פאַרשטיין דאָס דאַרף מען פריער מקדים זיין וואָס איז דער ענין פון בעש\"ט, מ'דאַרף וויסן אַז דער בעש\"ט איז ניט געווען מופשט פון עולם, ער איז געווען אין עולם, און דוקא מלובש אין עולם און דאָ האָט ער דערהערט אלקות . . אין פלוג איז שם בעש\"ט היא מדרי' קטנה מאד, וואָרום אויף ניצן זיך מיט שמות איז דאָס ניט קיין הויכע מדריגה, אויף משביע זיין אַ שם און דער שם זאָל פּועל זיין, דאָס איז גאָר קיין קונץ ניט, וואָרום ער ווייס פון דעם שם ניט און דער שם ווייס פון אים ניט, און דער וואָס ווייס נאָר אַ ביסל כתבי האריז\"ל און אַ ביסל פון שער היחודים קאָן ער דאָס טאָן, ניט דאָס איז מדרי' הבעש\"ט, אַזאַ זאַך האָט געקאנט דער ליאָזנער בע\"ש אויך, וואָרום דאָס איז גאָר ניט קיין גרויסער קונץ, מ'זאָל זאָגן אַז דאָס איז געווען דער בעש\"ט, בשום אופן קאָן מען אַזוי ניט זאָגן, זאָלען קומען מלכי מזרח ומערב און זאָגען באופן כזה וועל איך באַ זיי דאָס ניט נעמען, דער בעש\"ט אין זיינע קמיעות האָט ער ניט געדאַרפט האָבן קיין שמות.\nנאָר לפי\"ד בעש\"ט איז דאָס מורה אויף שמות עצמיים, וואָרום אין שמות איז פאַראַן ב' מדרי': א' שמות וואָס דאָס איז מער ניט ווי אַ הארה שזהו מדרי' נמוכה, (פאַרשטייט מען אַז דאָס וואָס מי זאָגט אַז דאָס איז אַ מדרי' נמוכה, מיינט מען ניט אַז לגבינו איז דאָס אַ מדרי' נמוכה, לגבינו איז דאָס אַ מדרי' נעלית ביותר, וואָס דען למע', כי זהו הארה) והב' הוא מדרי' שמות עצמיים, וואָס אין דעם שם איז פאַראַן די עצמות, איז דאָס ע\"ד ווי תורה ווערט אָנגערופן שמות עצמיים, וכמאמר<sup data-n=\"1\">96</sup> כל הקורא בתורה כאלו קורא בשמותיו של הקב\"ה, וואָס עצמות א\"ס ב\"ה איז נקרא אין די שמות, וואָרום עס איז ידוע דאורייתא וקוב\"ה כולא חד<sup data-n=\"2\">97</sup>, והשנית גם ההמשכה דתורה היא מבחי' חכמה וכמאמר אורייתא מחכמה נפקת<sup data-n=\"3\">98</sup> און דער פירוש חכמה הוא ע\"ד אנת הוא חכים ולא בחכ' ידיעא<sup data-n=\"4\">99</sup>, שהוא אנת שהוא נושא וסובל בחי' חכמה, וזהו מדרי' השמות שבתורה שהם שמות עצמיים דוקא, וזהו\"ע בע\"ש וואָס אויף שמות עצמיים אויף דעם איז ער געווען בע\"ש<sup data-n=\"5\">100</sup>.",[["1","96","ראה זח\"ב פז, א. הקדמת הרמב\"ן לפירושו עה\"ת. יונת אלם פכ\"ט."],["2","97","תניא פ\"ד ורפכ\"ג בשם הזוהר. וראה זוהר ח\"א כד, א. ח\"ב ס, א. תקוני זוהר תיקון ו בתחילתו. לקו\"ת נצבים מו, א. ועוד."],["3","98","זח\"ב סב, א. פה, א. ועוד."],["4","99","תקוני זוהר בהקדמה (יז, ב)."],["5","100","ספר השיחות תורת שלום ע' 45. וממשיך שם: ע' ברשימותיי דס\"ג ותמצא בענין בעש\"ט ותצרף לכאן ושם מבואר בהרחב יותר.\nובספר השיחות קייץ ה'ש\"ת ע' 170:\nעס זיינען פאַראַן צוויי אויסשפּראַכן אין דעם ענין פון שם, אָבער די צוויי אויסשפּראַכן האָבן צוויי פאַרשידנאַרטיקע באַדייטונגען. די אויסשפּראַכן בר שמחה און בעל שמחה באַדייטן ביידע דעם ענין השמחה אָבער דאָס זיינען צוויי באַזונדערע באַדייטונגען. בר שמחה מיינט אַ פּועל יוצא פון שמחה, דער גילוי וואָס בא מן השמחה. בעל שמחה דער וואָס מאַכט די שמחה. און בעל שם איז דער טייטש דער בעל פון דעם פּעולת השם.\nמורנו הבעל שם איז לבד זאת וואָס ער איז געווען אַ בעל שם, ניט נאָר אַ בר שם נאָר אַ בעל שם, איז ער אויך געווען אין דער דרגא פון בעל שם טוב. ער איז געווען אַ בעל אויף דעם שם טוב, ער איז געווען אַ בעל שם אויף צו ממשיך זיין דעם טוב שלמעלה אין אידן, און צו מעלה ומגביה זיין אידן צום טוב של מעלה.\nוראה ספר המאמרים תרפ\"א ע' קעז: ויא דער רבי זאגט (כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע, הכ\"מ, ע' ברשימת רס\"ג, ובמכ') דבעל שם, הוא שהשם שלו.\nובספר השיחות תרפ\"ט ע' 27: בשנת תרס\"ג בש\"ק חזון ערב ת\"ב (בעת סעודת המפסקת) שאל ר' יצחק גרשון מהו השם שקורין בעל שם, מאחר שהבעש\"ט הי' כ\"כ מופלא מהו התואר דבעל שם. והשיב כ\"ק אאמו\"ר נ\"ע הפי' בעל על השם שיכול לעשות בהשם כרצונו, כי יש פרטי ענינים בענין השמות וכמו לכוון בשם שהוא בפרטי מדרי' הספי' כי לכל ברכה יש שם פרטי וע\"י הכוונה שמכוון בשם ממשיך המדרי' פרטי' ההיא, וכאן הכוונה בעל על השם כנ\"ל (מאותו ש\"ק יש אצלי הנחה על ב' ענינים על ענין הנ\"ל ועל ענין בריך שמי').\nואמר אאמו\"ר נ\"ע אַז מיט סמעטענע קען מען דאָס ניט פאַרשטיין.\nובספר השיחות תרצ\"ט ע' 321 ואילך:\nהחסיד ר' איטשע גרשון, הי' רגיל לבוא אל כ\"ק אאמו\"ר נ\"ע על תשעה באב, פעם אחת בא וחל אז ערב ת\"ב בשבת, והיתה אז הסעודה השלישית – אַ מילכיגע סעודה – מצד הבריאות.\nושאל אז לכ\"ק אאמו\"ר נ\"ע, הטעם על קריאת בעל שם טוב, והשיב לו, כי הטוב הוא ע\"ד הטוב שנאמר במשה, ותרא אותו כי טוב הוא.\nושאל הרש\"ג לכ\"ק אדמו\"ר הטעם על קריאת בעל שם? והשיב כ\"ק אדמו\"ר: אַ בעל הבית אויף דעם שם. ואמר בע\"ש זיינען געווען אַ סאַך, עס איז גיווען ר' אדם בעל שם, ר' יואל בעל שם, והטעם הפּשוט שהיו נקראים בע\"ש, כי היו בעלי מופתים והיו מפורסמים. בזמן של אדמו\"ר הזקן הי' בליאזנע ר' ראובן בע\"ש, ער איז געווען אַ ערליכער איד, ער פלעגט פּראַווען מופתים, וכשנגנב דבר שאלו אצלו, ואמר מקום הגניבה והגנב.\nובספר השיחות תש\"ה ע' 92 ואילך: הוד כ\"ק אאמו\"ר הרה\"ק האָט מבאר געווען דעם טעם פון דעם נאָמען בעל שם, אַז ער איז אַ בעל אויף דעם שם. פאַרן בעש\"ט זיינען אויך געווען בעל שם'ס, וועלכע האָבן זיך משתמש געווען מיט קבלה שמות. שמות איז אין מדרי' אריך, אָבער אים רופט מען בעל שם, היינו שם העצם, און דערפאַר ווערט ער אָנגערופן טוב, בעל שם טוב, וואָס טוב איז מדרי' עתיק.\nוראה לקוטי שיחות חלק ח ע' 21 ואילך ובהערה 42 שם: וזה נרמז גם בשמו – \"(ר') ישראל בעל שם טוב\": \"ישראל\" הוא (כמו מ\"ת) בספי' הת\"ת (כידוע בענין ג' האבות), עיקר <i>ז\"א</i>; \"שם\" מורה על ספירת המלכות, העלאת המטה (כידוע בענין הלך הקב\"ה מהלך ת\"ק שנה לקנות לו שם); \"וישראל <i>בעל</i> שם\" הוא, שההעלאה ד\"שם\" היא (לא כמו שהיא מצד עצמה, אלא) כמו שהיא מצד ההמשכה ד\"ישראל\". והיינו שגם בבחי' המלכות ישנה מעלת <i>האור והגילוי</i>, שזהו \"שם טוב\": \"טוב\" הו\"ע האור (כמ\"ש וירא אלקים את האור כי טוב)* וע\"י ש\"ישראל\" הוא בעל על השם, נעשה גם השם טוב.\nועפ\"ז יומתק גם מה שהסתלקות וקבורת הבעש\"ט שייכת <i>לב'</i> הימים – ו' וז' (ראה לקוטי שיחות שם הערה 11), המורים על ז\"א מלכות (ראה שם הערה 18) – כי ענינו הוא יחוד ב' הקווין**. וראה לקוטי לוי יצחק לזהר ח\"ב ע' רמ.\n-----שולי הגליון-----\n*) <i>וכן גבי משה כתיב \"ותרא אותו כי </i>טוב<i> הוא\" שכשנולד נתמלא הבית כולו </i>אורה<i> (שמות ב</i>,<i> ב</i>.<i> סוטה יב</i>,<i> א</i>.<i> יג</i>,<i> רע\"א</i>.<i> פרש\"י שמות שם</i>.<i> אוה\"ת עה\"פ</i>).\n<i>אלא שבמשה הי' זה מצד</i> הנשמה <i>(ולא מצד הבית (גוף – ראה ד\"ה ויבא עמלק תרפ\"ח</i>)<i> עצמו</i>),<i> שלכן גופו של משה טעון קבורה (ראה המשך תרס\"ו ס\"ע קנח ואילך</i>)<i> משא\"כ אצל הבעש\"ט שהי' יכול לעלות בסערה השמימה כמו אלי' הנביא (תורת שלום ע' 46</i>),<i> הרי האור הי' שם גם מצד </i>הגוף <i>–</i> \"שם טוב\".\n<i>וע\"פ המבואר בפנים ההערה</i>,<i> י\"ל בדא\"פ שה\"שם טוב\" – שכן נקרא הבעש\"ט – הוא נעלה יותר גם מזיכוך הגוף דאלי' (ולהעיר מספר השיחות תש\"ד ע' 113</i>),<i> שהרי זיכוך הגוף דאלי' הוא זיכוך דב\"ן (וראה המשך תרס\"ו שם ע' קס</i>),<i> משא\"כ</i> <i>\"שם </i>טוב<i>\" דהבעש\"ט</i>,<i> הרי \"טוב\" הו\"ע ה\"אור\" כמו \"טוב\" שנאמר גבי משה (בחי' מ\"ה, שלמעלה מכלים בחי' ב\"ן), ואצל הבעש\"ט, גם ה\"שם\" הוא \"טוב\".</i>\n**) <i>ומה שעיקר החביבות אצל הבעש\"ט הי' יום השני דשבועות (ספר השיחות תש\"ד ע' 135</i>.<i> ונתבאר בארוכה בלקוטי שיחות חלק ד ע' 1027 ואילך</i>)<i> – כי </i>עיקר<i> המעלה הוא זיכוך </i>המטה<i> אלא שתכלית השלימות שבזה הוא שה\"מטה\" יתעלה כ\"כ עד שיהי' בו גם ענין ה\"אור\" של העליון [שלכן גם לע\"ל, כשיוסף ויהודה יתחברו יחדיו \"בתכלית היחוד האמיתי\" יהי' \"עבדי דוד מלך על כל ישראל\" (תו\"א מד, ריש ע\"ב)]</i>."]]]]});
